local function isCharacterPart(part)
	if not part then
		return false
	end
	local model = part:FindFirstAncestorOfClass("Model")
	if model and (model:FindFirstChildOfClass("Humanoid") or Players:GetPlayerFromCharacter(model)) then
		return true
	end
	return false
end

local function levelRay(from, to, passThrough)
    local dx, dy, dz = to[0]-from[0], to[1]-from[1], to[2]-from[2]
    local length = sqrt(dx*dx+dy*dy+dz*dz)
    if length < 1e-6 then return false end
    local origin = Vector3.new(from[0]*SCALE, from[1]*SCALE, from[2]*SCALE)
    local direction = Vector3.new(dx*SCALE, dy*SCALE, dz*SCALE)
    local ignored = {}
    for i, part in ipairs(passThrough or ignoreList) do ignored[i] = part end


    for attempt = 1, 16 do
        rayParams.FilterDescendantsInstances = ignored
        local hit = Workspace:Raycast(origin, direction, rayParams)
        if not hit then return false end
        local part = hit.Instance
        if part.CanCollide and not isCharacterPart(part) then
            local p = collisionHit.point
            local position = hit.Position
            p[0],p[1],p[2] = position.x/SCALE,position.y/SCALE,position.z/SCALE
            collisionHit.part, collisionHit.normal = part, hit.Normal
            collisionHit.fraction = hit.Distance/(length*SCALE)
            return true
        end
        ignored[#ignored+1] = part
    end
    return false
end

