				nearBoxes[nearBoxCount] = box
			end
			local x, y, z, r00, r01, r02, r10, r11, r12, r20, r21, r22 = part.CFrame:components()
			local size = part.Size
			box.x, box.y, box.z = x / SCALE, y / SCALE, z / SCALE
			box.r00, box.r01, box.r02 = r00, r01, r02
			box.r10, box.r11, box.r12 = r10, r11, r12
			box.r20, box.r21, box.r22 = r20, r21, r22
			box.hx, box.hy, box.hz = size.x * 0.5 / SCALE, size.y * 0.5 / SCALE, size.z * 0.5 / SCALE
			box.wedge = part:IsA("WedgePart")
			box.ball = part:IsA("Part") and part.Shape == Enum.PartType.Ball
		end
	end
end

local function boxDistance(box, px, py, pz)
	local dx, dy, dz = px - box.x, py - box.y, pz - box.z
	if box.ball then
		local length = sqrt(dx * dx + dy * dy + dz * dz)
		if length < 1e-6 then
			return -box.hx, px, py, pz, 0, 1, 0
		end
		local nx, ny, nz = dx / length, dy / length, dz / length
		return length - box.hx, box.x + nx * box.hx, box.y + ny * box.hx, box.z + nz * box.hx, nx, ny, nz
	end
	local lx = dx * box.r00 + dy * box.r10 + dz * box.r20
	local ly = dx * box.r01 + dy * box.r11 + dz * box.r21
	local lz = dx * box.r02 + dy * box.r12 + dz * box.r22
	local hx, hy, hz = box.hx, box.hy, box.hz
	local qx, qy, qz = clamp(lx, -hx, hx), clamp(ly, -hy, hy), clamp(lz, -hz, hz)
	if box.wedge then


		local inside = ly >= -hy and lz <= hz and hz * ly <= hy * lz
		local nx, ny, nz, distance
		if inside then
			qy, qz = ly, lz
		else
			local best = math.huge
			local function edge(ay, az, by, bz)
				local ey, ez = by - ay, bz - az
				local t = clamp(((ly - ay) * ey + (lz - az) * ez) / (ey * ey + ez * ez), 0, 1)
				local y, z = ay + ey * t, az + ez * t
				local d = (ly - y)^2 + (lz - z)^2
				if d < best then best, qy, qz = d, y, z end
			end
			edge(-hy, -hz, -hy, hz)
			edge(-hy, hz, hy, hz)
			edge(hy, hz, -hy, -hz)
		end
		local ex, ey, ez = lx - qx, ly - qy, lz - qz
		distance = sqrt(ex * ex + ey * ey + ez * ez)
		if distance > 1e-6 then
			nx, ny, nz = ex / distance, ey / distance, ez / distance
		else


			local diagonal = sqrt(hy * hy + hz * hz)
			local depth = hx - abs(lx)
			nx, ny, nz = lx >= 0 and 1 or -1, 0, 0
			if ly + hy < depth then depth, nx, ny, nz = ly + hy, 0, -1, 0 end
			if hz - lz < depth then depth, nx, ny, nz = hz - lz, 0, 0, 1 end
			local sloped = (hy * lz - hz * ly) / diagonal
			if sloped < depth then depth, nx, ny, nz = sloped, 0, hz / diagonal, -hy / diagonal end
			distance = -depth
			qx, qy, qz = lx + nx * depth, ly + ny * depth, lz + nz * depth
		end
		return distance,
			box.x + qx * box.r00 + qy * box.r01 + qz * box.r02,
			box.y + qx * box.r10 + qy * box.r11 + qz * box.r12,
			box.z + qx * box.r20 + qy * box.r21 + qz * box.r22,
			nx * box.r00 + ny * box.r01 + nz * box.r02,
			nx * box.r10 + ny * box.r11 + nz * box.r12,
			nx * box.r20 + ny * box.r21 + nz * box.r22
	end
	local ex, ey, ez = lx - qx, ly - qy, lz - qz
	local distance = sqrt(ex * ex + ey * ey + ez * ez)
	local nx, ny, nz
	if distance > 1e-6 then
		nx, ny, nz = ex / distance, ey / distance, ez / distance
	else

		local px_, py_, pz_ = hx - abs(lx), hy - abs(ly), hz - abs(lz)
		if px_ <= py_ and px_ <= pz_ then
			nx, ny, nz = lx >= 0 and 1 or -1, 0, 0
			qx = nx * hx
			distance = -px_
		elseif py_ <= pz_ then
			nx, ny, nz = 0, ly >= 0 and 1 or -1, 0
			qy = ny * hy
			distance = -py_
		else
			nx, ny, nz = 0, 0, lz >= 0 and 1 or -1
			qz = nz * hz
			distance = -pz_
		end
	end
	return distance,
		box.x + qx * box.r00 + qy * box.r01 + qz * box.r02,
		box.y + qx * box.r10 + qy * box.r11 + qz * box.r12,
		box.z + qx * box.r20 + qy * box.r21 + qz * box.r22,
		nx * box.r00 + ny * box.r01 + nz * box.r02,
		nx * box.r10 + ny * box.r11 + nz * box.r12,
		nx * box.r20 + ny * box.r21 + nz * box.r22
end

local bodies = {}
local bodyCount = 0
local joints = {}
local jointCount = 0
local tickBonds = {}
local tickBondCount = 0

local function createBody(position, rotation, mass, inverseInertia)
	local b = {
		mass = mass,
		px = position[0], py = position[1], pz = position[2],
		vx = 0, vy = 0, vz = 0,
		dvx = 0, dvy = 0, dvz = 0,
		R = {},
		Lx = 0, Ly = 0, Lz = 0,
		wx = 0, wy = 0, wz = 0,
		dwx = 0, dwy = 0, dwz = 0,
		iix = inverseInertia[0], iiy = inverseInertia[1], iiz = inverseInertia[2],
	}
	copy9(b.R, rotation)
	b.ix, b.iy, b.iz = 1 / b.iix, 1 / b.iiy, 1 / b.iiz
	b.least = min(b.ix, b.iy, b.iz)
	bodyCount = bodyCount + 1
	bodies[bodyCount] = b
	return b
end

local function createJoint(a, b, anchorA, anchorB)
	local j = {
		a = a, b = b,
		lax = anchorA[0], lay = anchorA[1], laz = anchorA[2],
		lbx = anchorB[0], lby = anchorB[1], lbz = anchorB[2],
		bias = v3(),
		has_axis = false,
		axis = v3(),
		angular_limit = 0,
		rax = 0, ray = 0, raz = 0, rbx = 0, rby = 0, rbz = 0,
		pbx = 0, pby = 0, pbz = 0,
		abx = 0, aby = 0, abz = 0,
		share_a = 0.5, share_b = 0.5, angular_scale = 0,
	}
	jointCount = jointCount + 1
	joints[jointCount] = j
	return j
end

local function newTickBond()
	tickBondCount = tickBondCount + 1
	local bond = tickBonds[tickBondCount]
	if not bond then
		bond = {}
		tickBonds[tickBondCount] = bond
	end
	bond.peerScale, bond.gripBudget = nil, nil
	bond.tvx, bond.tvy, bond.tvz = 0, 0, 0
	return bond
end

local function addWorldContact(body, ox, oy, oz, nx, ny, nz, depth, friction, depthScale, stiffness)
	local c = newTickBond()
	c.kind = 5
	c.body = body
	c.rx, c.ry, c.rz = ox, oy, oz
	c.nx, c.ny, c.nz = nx, ny, nz
	c.depth = depth * depthScale
	c.stiffness = stiffness
	c.friction = friction
	return c
end

local function prepareJoint(j)
	local a, b = j.a, j.b
	local ra, rb = a.R, b.R
	local x, y, z = j.lax, j.lay, j.laz
	local rax = (y * ra[3] + x * ra[0]) + z * ra[6]
	local ray = (y * ra[4] + x * ra[1]) + z * ra[7]
	local raz = (y * ra[5] + x * ra[2]) + z * ra[8]
	x, y, z = j.lbx, j.lby, j.lbz
	local rbx = (y * rb[3] + x * rb[0]) + z * rb[6]
	local rby = (y * rb[4] + x * rb[1]) + z * rb[7]
	local rbz = (y * rb[5] + x * rb[2]) + z * rb[8]
	j.rax, j.ray, j.raz, j.rbx, j.rby, j.rbz = rax, ray, raz, rbx, rby, rbz


	local dx = (rax + a.px) - (rbx + b.px)
	local dy = (ray + a.py) - (rby + b.py)
	local dz = (raz + a.pz) - (rbz + b.pz)
	local length = sqrt(dx * dx + dy * dy + dz * dz)
	if length > 0.0625 then
		local scale = 0.0625 / length
		dx, dy, dz = dx * scale, dy * scale, dz * scale
	end
	j.pbx, j.pby, j.pbz = dx * 0.1875, dy * 0.1875, dz * 0.1875

	local total = 1 / (b.mass + a.mass)
	j.share_b = total * a.mass
	j.share_a = total * b.mass
	local bias = j.bias
	j.abx, j.aby, j.abz = bias[0] * 0.875, bias[1] * 0.875, bias[2] * 0.875
	j.angular_scale = min((j.share_b + j.share_b) * b.least, (j.share_a + j.share_a) * a.least)
end

local function solveJoint(j)
	local a, b = j.a, j.b
	local rax, ray, raz, rbx, rby, rbz = j.rax, j.ray, j.raz, j.rbx, j.rby, j.rbz
	local awx, awy, awz = a.wx, a.wy, a.wz
	local bwx, bwy, bwz = b.wx, b.wy, b.wz
	local k = 0.1875

	local pax = (awz * ray - awy * raz) + a.vx
	local pay = (awx * raz - awz * rax) + a.vy
	local paz = (awy * rax - awx * ray) + a.vz
	local pbx = (bwz * rby - bwy * rbz) + b.vx
	local pby = (bwx * rbz - bwz * rbx) + b.vy
	local pbz = (bwy * rbx - bwx * rby) + b.vz
	local vx = (pax * k + j.pbx) - pbx * k
	local vy = (pay * k + j.pby) - pby * k
	local vz = (paz * k + j.pbz) - pbz * k
	local length = sqrt(vx * vx + vy * vy + vz * vz)
	if length > 0.033333335 then
		local scale = 0.033333335 / length
		vx, vy, vz = vx * scale, vy * scale, vz * scale
	end
	local share_a, share_b = j.share_a, j.share_b
	local share = -share_a
	a.dvx = a.dvx + vx * share
	a.dvy = a.dvy + vy * share
	a.dvz = a.dvz + vz * share
	a.dwx = a.dwx + (raz * vy - ray * vz) * share
	a.dwy = a.dwy + (rax * vz - raz * vx) * share
	a.dwz = a.dwz + (ray * vx - rax * vy) * share
	b.dvx = b.dvx + vx * share_b
	b.dvy = b.dvy + vy * share_b
	b.dvz = b.dvz + vz * share_b
	b.dwx = b.dwx + (rbz * vy - rby * vz) * share_b
	b.dwy = b.dwy + (rbx * vz - rbz * vx) * share_b
	b.dwz = b.dwz + (rby * vx - rbx * vy) * share_b

	local wx = (j.abx - awx * 0.875) + bwx * 0.875
	local wy = (j.aby - awy * 0.875) + bwy * 0.875
	local wz = (j.abz - awz * 0.875) + bwz * 0.875
	local limit = j.angular_limit
	if limit ~= 0 then
		length = sqrt(wx * wx + wy * wy + wz * wz)
		if length > limit then
			local scale = limit / length
			wx, wy, wz = wx * scale, wy * scale, wz * scale
		end
		wx = wx + (bwx - awx) * 0.125
		wy = wy + (bwy - awy) * 0.125
		wz = wz + (bwz - awz) * 0.125
	end
	if j.has_axis then
		local n = j.axis
		local nx, ny, nz = n[0], n[1], n[2]
		length = sqrt(nx * nx + ny * ny + nz * nz)
		local ux, uy, uz = 0, 0, 0
		if length ~= 0 then
			local scale = 1 / length
			ux, uy, uz = nx * scale, ny * scale, nz * scale
		end
		local along = ((bwx - awx) * ux + (bwy - awy) * uy) + (bwz - awz) * uz
		wx = wx + (along * ux * 0.875 + nx * 0.875)
		wy = wy + (along * uy * 0.875 + ny * 0.875)
		wz = wz + (along * uz * 0.875 + nz * 0.875)
	end
	local s = j.angular_scale
	wx, wy, wz = wx * s, wy * s, wz * s
	a.dwx = a.dwx + wx * share_a
	a.dwy = a.dwy + wy * share_a
	a.dwz = a.dwz + wz * share_a
	b.dwx = b.dwx - share_b * wx
	b.dwy = b.dwy - share_b * wy
	b.dwz = b.dwz - share_b * wz
end

local function solveBodyContact(c)
	local body = c.body
	local nx, ny, nz = c.nx, c.ny, c.nz
	local rx, ry, rz = c.rx, c.ry, c.rz
	local wx, wy, wz = body.wx, body.wy, body.wz
	local k = -c.stiffness
	local ux = ((wz * ry - rz * wy) + body.vx - (c.tvx or 0)) * k + nx * c.depth
	local uy = ((rz * wx - rx * wz) + body.vy - (c.tvy or 0)) * k + ny * c.depth
	local uz = ((rx * wy - ry * wx) + body.vz - (c.tvz or 0)) * k + nz * c.depth
	local along = (nx * ux + ny * uy) + nz * uz
	if along > 0 then
		local ix, iy, iz = nx * along, ny * along, nz * along
		local tx, ty, tz = ux - ix, uy - iy, uz - iz
		local tangential = sqrt(tx * tx + ty * ty + tz * tz)
		if tangential > 0 then
			local inverse = 1 / tangential
			local normal = sqrt(ix * ix + iy * iy + iz * iz)
			local limit = normal * c.friction



			local scale = body.gravityScale or 1
			local cap = 0.0068055559 * scale
			local amount = tangential
			local work = 0
			if amount > limit then
				work = (amount - limit) * normal * 480
				amount = limit
			end
			if amount > cap then
				work = work + (amount - cap) * normal * 480
				amount = cap
			end
			body.frictionWork = (body.frictionWork or 0) + work / (scale * scale)
			ix = ix + amount * inverse * tx
			iy = iy + amount * inverse * ty
			iz = iz + amount * inverse * tz
		end
		if c.peerScale then
            local scale = c.peerScale
            ix, iy, iz = ix*scale, iy*scale, iz*scale
        end
		body.dvx = body.dvx + ix
		body.dvy = body.dvy + iy
		body.dvz = body.dvz + iz
		body.dwx = body.dwx + (rz * iy - iz * ry)
		body.dwy = body.dwy + (iz * rx - rz * ix)
		body.dwz = body.dwz + (ix * ry - iy * rx)
	end
end

local function solveBodySurface(bond)
	local body = bond.body
	local nx, ny, nz = bond.nx, bond.ny, bond.nz
	local s = bond.stiffness
	local push = s * bond.distance
	local k = bond.damping
	local ux = push * nx + (body.vx - bond.tvx) * -k
	local uy = push * ny + (body.vy - bond.tvy) * -k
	local uz = push * nz + (body.vz - bond.tvz) * -k
	local along = (ux * nx + uy * ny) + uz * nz
	if along > 0 then
		local ix, iy, iz = nx * along, ny * along, nz * along
		local tx, ty, tz = ux - ix, uy - iy, uz - iz
		local length = sqrt(tx * tx + ty * ty + tz * tz)
		if length > 0 then
			local limit = min(sqrt(ix * ix + iy * iy + iz * iz) * bond.friction, length)
			local inverse = 1 / length
			ix = ix + inverse * tx * limit
			iy = iy + inverse * ty * limit
			iz = iz + inverse * tz * limit
		end
		local weight = bond.weight0
		body.dvx = body.dvx + ix
		body.dvy = body.dvy + iy * bond.weight1
		body.dvz = body.dvz + iz
		local gain = min(along * 1024, 1)
		local spin = (weight * s) * gain
		local turn = -((weight * k) * gain)
		body.dwx = body.dwx + (spin * bond.turnx + turn * body.wx)
		body.dwy = body.dwy + (spin * bond.turny + turn * body.wy)
		body.dwz = body.dwz + (spin * bond.turnz + turn * body.wz)
	end
end

local Bonds = {}

function Bonds.point(a, b, lax, lay, laz, lbx, lby, lbz)
	local c = newTickBond()
	local ra, rb = a.R, b.R
	local rax = (lay * ra[3] + lax * ra[0]) + laz * ra[6]
	local ray = (lay * ra[4] + lax * ra[1]) + laz * ra[7]
	local raz = (lay * ra[5] + lax * ra[2]) + laz * ra[8]
	local rbx = (lbx * rb[0] + lby * rb[3]) + lbz * rb[6]
	local rby = (lby * rb[4] + lbx * rb[1]) + lbz * rb[7]
	local rbz = (lby * rb[5] + lbx * rb[2]) + lbz * rb[8]
	c.kind = 7
	c.a, c.b = a, b
	c.rax, c.ray, c.raz, c.rbx, c.rby, c.rbz = rax, ray, raz, rbx, rby, rbz
	local ex = (rax + a.px) - (rbx + b.px)
	local ey = (ray + a.py) - (rby + b.py)
	local ez = (raz + a.pz) - (rbz + b.pz)
	if b.item then

		local length = sqrt((ey * ey + ex * ex) + ez * ez)
		if length > 0.125 then
			local scale = 0.125 / length
			ex, ey, ez = ex * scale, ey * scale, ez * scale
		end
	end
	c.bx, c.by, c.bz = ex * 0.1875, ey * 0.1875, ez * 0.1875
	local total = 1 / (b.mass + a.mass)
	c.share_a = total * b.mass
	c.share_b = total * a.mass
	return c
end

function Bonds.rotation(a, b, bx, by, bz, angularLimit)
	local c = newTickBond()
	c.kind = 8
	c.a, c.b = a, b
	c.bx, c.by, c.bz = bx * 0.875, by * 0.875, bz * 0.875
	local total = 1 / (a.mass + b.mass)
	local massA, massB = a.mass * total, b.mass * total
	local scale = min((massA + massA) * b.least, (massB + massB) * a.least)
	c.share_a = massB * scale
	c.share_b = massA * scale
	c.angular_limit = angularLimit
	return c
end

function Bonds.removeBody(body)
	for index = 1, bodyCount do
		if bodies[index] == body then
			bodies[index] = bodies[bodyCount]
			bodies[bodyCount] = nil
			bodyCount = bodyCount - 1
			return
		end
	end
end

function Bonds.solvePoint(c)
	local a, b = c.a, c.b
	local rax, ray, raz, rbx, rby, rbz = c.rax, c.ray, c.raz, c.rbx, c.rby, c.rbz
	local k = 0.1875
	local pax = (a.wz * ray - a.wy * raz) + a.vx
	local pay = (a.wx * raz - a.wz * rax) + a.vy
	local paz = (a.wy * rax - a.wx * ray) + a.vz
	local pbx = (b.wz * rby - b.wy * rbz) + b.vx
	local pby = (b.wx * rbz - b.wz * rbx) + b.vy
	local pbz = (b.wy * rbx - b.wx * rby) + b.vz
	local vx = (pax * k + c.bx) - pbx * k
	local vy = (pay * k + c.by) - pby * k
	local vz = (paz * k + c.bz) - pbz * k
	local length = sqrt(vx * vx + vy * vy + vz * vz)
	if length > 0.033333335 then
		local scale = 0.033333335 / length
		vx, vy, vz = vx * scale, vy * scale, vz * scale
	end
	if c.gripBudget then
        local needed = sqrt(vx*vx+vy*vy+vz*vz)*c.share_a*a.mass
        local available = c.gripBudget.left
        if needed > available and needed > 0 then
            local scale = available/needed
            vx,vy,vz = vx*scale,vy*scale,vz*scale
        end
        c.gripBudget.left = max(0,available-needed)
    end
	local share = -c.share_a
	a.dvx = a.dvx + vx * share
	a.dvy = a.dvy + vy * share
	a.dvz = a.dvz + vz * share
	a.dwx = a.dwx + (raz * vy - ray * vz) * share
	a.dwy = a.dwy + (rax * vz - raz * vx) * share
	a.dwz = a.dwz + (ray * vx - rax * vy) * share
	share = c.share_b
	b.dvx = b.dvx + vx * share
	b.dvy = b.dvy + vy * share
	b.dvz = b.dvz + vz * share
	b.dwx = b.dwx + (rbz * vy - rby * vz) * share
	b.dwy = b.dwy + (rbx * vz - rbz * vx) * share
	b.dwz = b.dwz + (rby * vx - rbx * vy) * share
end

function Bonds.solveRotation(c)
	local a, b = c.a, c.b
	local k = 0.875
	local dx, dy, dz = b.wx - a.wx, b.wy - a.wy, b.wz - a.wz
	local wx = (a.wx * -k + c.bx) + b.wx * k
	local wy = (a.wy * -k + c.by) + b.wy * k
	local wz = (a.wz * -k + c.bz) + b.wz * k
	local limit = c.angular_limit
	if limit ~= 0 then
		local length = sqrt(wx * wx + wy * wy + wz * wz)
		if length > limit then
			local scale = limit / length
			wx, wy, wz = wx * scale, wy * scale, wz * scale
		end
		wx, wy, wz = wx + dx * 0.125, wy + dy * 0.125, wz + dz * 0.125
	end
	local share_a, share_b = c.share_a, -c.share_b
	a.dwx = a.dwx + share_a * wx
	a.dwy = a.dwy + share_a * wy
	a.dwz = a.dwz + share_a * wz
	b.dwx = b.dwx + share_b * wx
	b.dwy = b.dwy + share_b * wy
	b.dwz = b.dwz + share_b * wz
end

local function integrateBodies()
	for index = 1, bodyCount do
		local body = bodies[index]
		if not body.settled then
		local r = body.R
		body.vx = body.vx + body.dvx
		body.vy = body.vy + body.dvy
		body.vz = body.vz + body.dvz
		local lx, ly, lz = body.Lx + body.dwx, body.Ly + body.dwy, body.Lz + body.dwz
		local limit = body.least * 8
		local length = sqrt(lx * lx + ly * ly + lz * lz)
		if length > limit then
			local scale = limit / length
			lx, ly, lz = lx * scale, ly * scale, lz * scale
		end
		body.Lx, body.Ly, body.Lz = lx, ly, lz
		local x = ((lx * r[0] + ly * r[1]) + lz * r[2]) * body.iix
		local y = ((ly * r[4] + lx * r[3]) + lz * r[5]) * body.iiy
		local z = ((ly * r[7] + lx * r[6]) + lz * r[8]) * body.iiz
		body.wx = (r[3] * y + x * r[0]) + r[6] * z
		body.wy = (y * r[4] + x * r[1]) + z * r[7]
		body.wz = (y * r[5] + x * r[2]) + z * r[8]
		end
	end
end

local function physicsSolve()
	for index = 1, jointCount do
		prepareJoint(joints[index])
	end
	for index = 1, bodyCount do bodies[index].frictionWork = 0 end
	for iteration = 1, 32 do
		for index = 1, bodyCount do
			local body = bodies[index]
			body.dvx, body.dvy, body.dvz = 0, 0, 0
			body.dwx, body.dwy, body.dwz = 0, 0, 0
		end

		local vehicles = Bonds.vehicles
		if vehicles then vehicles:solveWheels() end
		for index = 1, jointCount do
			solveJoint(joints[index])
		end
		for index = 1, tickBondCount do
			local bond = tickBonds[index]
			local kind = bond.kind
			if kind == 5 then
				solveBodyContact(bond)
			elseif kind == 7 then
				Bonds.solvePoint(bond)
			elseif kind == 8 then
				Bonds.solveRotation(bond)
			else
				solveBodySurface(bond)
			end
		end

		if vehicles then vehicles:drive() end
		integrateBodies()
	end
	tickBondCount = 0
end

local function angularVelocityAt(m, lx, ly, lz, iix, iiy, iiz)
	local a = ((m[1] * ly + m[0] * lx) + m[2] * lz) * iix
	local b = ((m[4] * ly + m[3] * lx) + m[5] * lz) * iiy
	local c = ((m[7] * ly + m[6] * lx) + m[8] * lz) * iiz
	return (m[0] * a + m[3] * b) + m[6] * c, (m[4] * b + m[1] * a) + m[7] * c, (m[5] * b + m[2] * a) + m[8] * c
end

local rkSample = {}

local function turned(rotation, wx, wy, wz, part)
	copy9(rkSample, rotation)
	local speed = sqrt(wx * wx + wy * wy + wz * wz)
	if speed > SMALL then
		local inverse = 1 / speed
		rotateRows(rkSample, wx * inverse, wy * inverse, wz * inverse, speed * part)
	end
end

local function integrateRotation(body)
	local rotation = body.R
	local lx, ly, lz = body.Lx, body.Ly, body.Lz
	if lx == 0 and ly == 0 and lz == 0 then
		body.wx, body.wy, body.wz = 0, 0, 0
		return
	end
	local iix, iiy, iiz = body.iix, body.iiy, body.iiz
	local k1x, k1y, k1z = angularVelocityAt(rotation, lx, ly, lz, iix, iiy, iiz)
	turned(rotation, k1x, k1y, k1z, 0.5)
	local k2x, k2y, k2z = angularVelocityAt(rkSample, lx, ly, lz, iix, iiy, iiz)
	turned(rotation, k2x, k2y, k2z, 0.5)
	local k3x, k3y, k3z = angularVelocityAt(rkSample, lx, ly, lz, iix, iiy, iiz)
	turned(rotation, k3x, k3y, k3z, 1)
	local k4x, k4y, k4z = angularVelocityAt(rkSample, lx, ly, lz, iix, iiy, iiz)
	local wx = (k4x + k1x) + ((k3x + k3x) + (k2x + k2x))
	local wy = (k4y + k1y) + ((k3y + k3y) + (k2y + k2y))
	local wz = (k4z + k1z) + ((k3z + k3z) + (k2z + k2z))
	local sx, sy, sz = wx / 6, wy / 6, wz / 6
	body.wx, body.wy, body.wz = sx, sy, sz
	local speed = sqrt(sx * sx + sy * sy + sz * sz)
	if speed > SMALL then
		local inverse = 1 / speed
		rotateRows(rotation, sx * inverse, sy * inverse, sz * inverse, speed)
	end
end

local function integrateBodyPositions()
	for index = 1, bodyCount do
		local body = bodies[index]
		if not body.settled then
		local vy = body.vy - (GRAVITY * gravityScale) * (body.gravityScale or 1)
		body.vy = vy
		local carrier = body.carrier
		body.px = body.px + body.vx - (carrier and carrier.vx or 0)
		body.py = body.py + vy - (carrier and carrier.vy or 0)
		body.pz = body.pz + body.vz - (carrier and carrier.vz or 0)
		integrateRotation(body)
		end
	end
end

local function noop() end
local Items = {useHands = noop, updateActions = noop, tick = noop, updateBullets = noop,
	updateParticles = noop, spawnBlood = noop}

local createHuman, physicsTick
do

local gameTick = 0

local function newLeg()
	return {
		ground_bond = nil, rest_ticks = 0, state = LEG_LOOSE, air_ticks = 0, progress = 0,
		start = v3(), swing = v3(), planted = v3(),
		contact = 0, ground_height = 0, pitch = 0, previous_pitch = 0, yaw = 0, landing = v3(),
	}
end

function createHuman(x, y, z, yaw)
	bodies, bodyCount = {}, 0
	joints, jointCount = {}, 0
	tickBondCount = 0

	local orientation = headingAxes(yaw)
	local h = {
		bones = {},
		stamina = 127, max_stamina = 127,
		old_health = 100, health = 100, damage_ticks = 0,
		blood = 100, bleeding = false, bleed_phase = random(0, 255), bandage_progress = 0,
		leg_health = {[0] = 100, 100}, arm_health = {[0] = 100, 100},
		on_ground = false, movement_state = STATE_STAND, stand_up_ticks = 0, zoom_level = 0,
		throw_pitch = 0, standing = false,
		view_yaw = yaw, view_pitch = 0, look_yaw_offset = 0,
		lean_side = 0, lean_forward = 0, walk_amount = 0,
		input_strafe = 0, input_forward = 0, input_yaw = yaw, input_pitch = 0,
		input_spine_twist = 0, input_spine_bend = 0, input_jump_forward = 0, input_jump_side = 0,
		input_flags = 0, input_ragdoll = false,
		idle_sway = v3(), idle_sway_velocity = v3(),
		bounds_min = v3(), bounds_max = v3(),
		jump_charge = 0, jump_side = 0, jump_forward = 0,
		centre = v3(x, y, z), smoothed_rotation = identity3(), smoothed_quat = {[0] = 0, 0, 0, 0},
		trunk_velocity = v3(), centre_velocity = v3(), smoothed_angular_velocity = v3(),
		mean_angular_velocity = v3(),
		hip_turn = {[0] = v3(), v3()},
		jump_pose_angle = 0,
		walk_point = v3(x, y, z), ground_velocity = v3(), walk_velocity = v3(), step_offset = v3(),
		ground_flat = 0, ground_rise = 0, stillness = 0, push_leg = 0,
		legs = {[0] = newLeg(), newLeg()},
		pose_rotations = {},
		stride_lean = 0,
		inventory_anim_flags = -1,
		hands = {},
		slots = {{}, {}, {}, {}, {}},
		last_input_flags = 0, drive_lean = 0, drive_aiming = false,
		actions = {}, inventory_anim_progress = 0,
	}


	for i = 0, 15 do
		local t = SKELETON[i]
		local lx, ly, lz = t.pos[0], t.pos[1], t.pos[2]
		local parent = t.parent
		while parent ~= 0 do
			local ancestor = SKELETON[parent]
			lx, ly, lz = lx + ancestor.pos[0], ly + ancestor.pos[1], lz + ancestor.pos[2]
			parent = ancestor.parent
		end
		local m = orientation
		local world = v3(
			(lz * m[6] + lx * m[0]) + (ly * m[3] + x),
			(lz * m[7] + lx * m[1]) + (ly * m[4] + y),
			(lz * m[8] + lx * m[2]) + (ly * m[5] + z))
		local body = createBody(world, orientation, t.mass, t.inverseInertia)
		body.bone = i
		local bone = {
			index = i,
			body = body,
			position = v3(world[0], world[1], world[2]),
			previous_position = v3(world[0], world[1], world[2]),
			velocity = v3(),
			rotation = identity3(),
			angular_velocity = v3(),
			mass = t.mass,
			ground_bond_strength = body.least,
			euler_angles = v3(),
			segment0 = v3(), segment1 = v3(),
			bond = nil,
			ground_bond_count = 0,
		}
		copy9(bone.rotation, orientation)
		h.bones[i] = bone
	end


	for _, link in ipairs(JOINT_LINKS) do
		local parent, child = link[1], link[2]
		local t = SKELETON[child]
		local anchor = t.anchor
		local other = v3(anchor[0] - t.pos[0], anchor[1] - t.pos[1], anchor[2] - t.pos[2])
		h.bones[child].bond = createJoint(h.bones[parent].body, h.bones[child].body, anchor, other)
	end
	return h
end

local function syncBones(h)
	local bmin, bmax = h.bounds_min, h.bounds_max
	bmin[0], bmin[1], bmin[2] = 1e9, 1e9, 1e9
	bmax[0], bmax[1], bmax[2] = -1e9, -1e9, -1e9
	for i = 0, 15 do
		local bone = h.bones[i]
		local body = bone.body
		local p, prev = bone.position, bone.previous_position
		prev[0], prev[1], prev[2] = p[0], p[1], p[2]
		p[0], p[1], p[2] = body.px, body.py, body.pz
		bone.velocity[0], bone.velocity[1], bone.velocity[2] = body.vx, body.vy, body.vz
		copy9(bone.rotation, body.R)
		bone.angular_velocity[0], bone.angular_velocity[1], bone.angular_velocity[2] = body.wx, body.wy, body.wz


		if i <= 3 and levelRay(prev, p) then
			local part = collisionHit.fraction * 0.975
			p[0] = (p[0] - prev[0]) * part + prev[0]
			p[1] = (p[1] - prev[1]) * part + prev[1]
			p[2] = (p[2] - prev[2]) * part + prev[2]
			body.px, body.py, body.pz = p[0], p[1], p[2]
		end

		local t = SKELETON[i]
		local row = 3 * t.axisRow
		local r = bone.rotation
		local half = t.length * 0.5
		for k = 0, 2 do
			bone.segment0[k] = -half * r[row + k] + p[k]
			bone.segment1[k] = half * r[row + k] + p[k]
			local low = min(bone.segment0[k], bone.segment1[k]) - t.radius
			local high = max(bone.segment0[k], bone.segment1[k]) + t.radius
			if bmin[k] > low then
				bmin[k] = low
			end
			if bmax[k] < high then
				bmax[k] = high
			end
		end
	end
	bmin[1] = bmin[1] - 0.25
end

local function trunkMean(h, field, mean)
	local b = h.bones
	local total = (b[0].mass + b[1].mass) + b[2].mass
	for k = 0, 2 do
		mean[k] = b[2].mass * b[2][field][k] + (b[1][field][k] * b[1].mass + b[0][field][k] * b[0].mass)
	end
	if total > 0 then
		local scale = 1 / total
		mean[0], mean[1], mean[2] = mean[0] * scale, mean[1] * scale, mean[2] * scale
	end
end

local function halveToward(kept, value)
	for k = 0, 2 do
		kept[k] = (value[k] + kept[k]) * 0.5
	end
end

local function updateCentre(h)
	local b = h.bones
	local mean = v3()
	trunkMean(h, "position", h.centre)
	trunkMean(h, "velocity", mean)
	halveToward(h.trunk_velocity, mean)
	for k = 0, 2 do
		h.centre_velocity[k] = h.trunk_velocity[k] - h.ground_velocity[k]
	end
	trunkMean(h, "angular_velocity", mean)
	halveToward(h.smoothed_angular_velocity, mean)

	local mx, my, mz, total = 0, 0, 0, 0
	for i = 0, 15 do
		local bone = b[i]
		mx = mx + bone.mass * bone.angular_velocity[0]
		my = my + bone.mass * bone.angular_velocity[1]
		mz = mz + bone.mass * bone.angular_velocity[2]
		total = total + bone.mass
	end
	if total > 0 then
		mx, my, mz = mx / total, my / total, mz / total
	end
	h.mean_angular_velocity[0], h.mean_angular_velocity[1], h.mean_angular_velocity[2] = mx, my, mz


	local q, kept = {}, h.smoothed_quat
	quatFromMat3(q, b[0].rotation)
	if not ((q[3] * kept[3] + q[2] * kept[2]) + (q[1] * kept[1] + q[0] * kept[0]) >= 0) then
		q[0], q[1], q[2], q[3] = -q[0], -q[1], -q[2], -q[3]
	end
	local x, y, z, w = q[0] + kept[0], q[1] + kept[1], q[2] + kept[2], q[3] + kept[3]
	local length = sqrt(((x * x + y * y) + (z * z + w * w)) * 0.25)
	if length == 0 or length ~= length then
		kept[0], kept[1], kept[2], kept[3] = 0, 0, 0, 1
	else
		local scale = 0.5 / length
		kept[0], kept[1], kept[2], kept[3] = x * scale, y * scale, z * scale, w * scale
	end
	mat3FromQuat(h.smoothed_rotation, kept)
end

local function jointRotation(q, parent, child)
	local m = {}
	multiplyTransposed(m, child.rotation, parent.rotation)
	quatFromMat3(q, m)
end

local function jointTurn(axis, q, target)
	if not (((q[3] * target[3] + q[2] * target[2]) + (q[1] * target[1] + q[0] * target[0])) >= 0) then
		q[0], q[1], q[2], q[3] = -q[0], -q[1], -q[2], -q[3]
	end
	q[0], q[1], q[2] = -q[0], -q[1], -q[2]
	local turn = {}
	quatMultiply(turn, q, target)
	normalize3(axis, turn)
	local half = acos(clamp(turn[3], -1, 1))
	return half + half
end

local function limitAngle(angle)
	return clamp(angle, -PI_8, PI_8)
end

local function jointDamping(damping, parent, child)
	local d = v3(
		parent.angular_velocity[0] - child.angular_velocity[0],
		parent.angular_velocity[1] - child.angular_velocity[1],
		parent.angular_velocity[2] - child.angular_velocity[2])
	toLocal(damping, parent.rotation, d)
	damping[0], damping[1], damping[2] = damping[0] * -0.25, damping[1] * -0.25, damping[2] * -0.25
end

local function setJointBias(bias, child, axis, angle, damping)
	local u = v3(
		(axis[0] * angle) * 0.75 + damping[0],
		(axis[1] * angle) * 0.75 + damping[1],
		(axis[2] * angle) * 0.75 + damping[2])
	toWorld(bias, child.rotation, u)
end

local function limitJointChange(h, parentBone, childBone, bias, limit, share)
	local parent, child = h.bones[parentBone], h.bones[childBone]
	local cx = (parent.angular_velocity[0] - child.angular_velocity[0]) * share
	local cy = (parent.angular_velocity[1] - child.angular_velocity[1]) * share
	local cz = (parent.angular_velocity[2] - child.angular_velocity[2]) * share
	local dx, dy, dz = bias[0] - cx, bias[1] - cy, bias[2] - cz
	local length = sqrt(dx * dx + dy * dy + dz * dz)
	if length > limit then
		local scale = limit / length
		bias[0], bias[1], bias[2] = dx * scale + cx, dy * scale + cy, dz * scale + cz
	end
end

local function dotRows(a, ra, b, rb)
	return (a[ra * 3 + 1] * b[rb * 3 + 1] + a[ra * 3] * b[rb * 3]) + a[ra * 3 + 2] * b[rb * 3 + 2]
end

local function angleSpring(angle, rate, low, high)
	local correction = 0
	if not (angle >= low) then
		local t = (angle - low) * -0.25 - rate * 0.5
		if t > 0 then
			correction = t
		end
	end
	if angle > high then
		local t = (angle - high) * -0.25 - rate * 0.5
		if not (t >= 0) then
			correction = correction + t
		end
	end
	return correction
end

local function limitJointAngles(h, parentBone, childBone, axis)
	local parent, child = h.bones[parentBone], h.bones[childBone]
	local limits = SKELETON[childBone]
	local p, c = parent.rotation, child.rotation
	local angle, rate, correction = {}, {}, {}

	angle[0] = atan2(dotRows(c, 1, p, 2), dotRows(c, 2, p, 2))
	local r00, r01 = dotRows(c, 0, p, 0), dotRows(c, 0, p, 1)
	angle[1] = atan2(-dotRows(c, 0, p, 2), sqrt(r01 * r01 + r00 * r00))
	local s, co = sin(angle[0]), cos(angle[0])
	angle[2] = atan2(dotRows(c, 2, p, 0) * s - dotRows(c, 1, p, 0) * co,
		dotRows(c, 1, p, 1) * co - dotRows(c, 2, p, 1) * s)

	local dx = parent.angular_velocity[0] - child.angular_velocity[0]
	local dy = parent.angular_velocity[1] - child.angular_velocity[1]
	local dz = parent.angular_velocity[2] - child.angular_velocity[2]
	rate[0] = (dy * p[1] + dx * p[0]) + dz * p[2]
	rate[1] = (dy * p[4] + dx * p[3]) + dz * p[5]
	rate[2] = (dx * p[6] + dy * p[7]) + dz * p[8]
	for i = 0, 2 do
		correction[i] = angleSpring(angle[i], rate[i], limits.minAngle[i], limits.maxAngle[i])
		child.euler_angles[i] = min(max(limits.minAngle[i], angle[i]), limits.maxAngle[i])
	end
	axis[0] = (correction[1] * p[3] + p[0] * correction[0]) + (correction[2] * p[6] + axis[0])
	axis[1] = (correction[2] * p[7] + correction[0] * p[1]) + (correction[1] * p[4] + axis[1])
	axis[2] = (correction[2] * p[8] + correction[0] * p[2]) + (correction[1] * p[5] + axis[2])
end

local function setJointAxis(h, parentBone, childBone, limit)
	local j = h.bones[childBone].bond
	local axis = j.axis
	j.has_axis = false
	axis[0], axis[1], axis[2] = 0, 0, 0
	limitJointAngles(h, parentBone, childBone, axis)
	if (axis[0] * axis[0] + axis[1] * axis[1]) + axis[2] * axis[2] > 0 then
		j.has_axis = true
	end
	j.angular_limit = limit
end

local function setJointAxes(h, spineLimit, armLimit)
	setJointAxis(h, BONE_PELVIS, BONE_STOMACH, spineLimit)
	setJointAxis(h, BONE_STOMACH, BONE_CHEST, spineLimit)
	setJointAxis(h, BONE_CHEST, BONE_HEAD, spineLimit)
	for side = 0, 1 do
		local shoulder = BONE_SHOULDER + 3 * side
		setJointAxis(h, BONE_CHEST, shoulder, armLimit)
		setJointAxis(h, shoulder, shoulder + 1, armLimit)
	end
end

local function limbJointBias(bias, q, target, child, limit)
	if not (((q[3] * target[3] + q[2] * target[2]) + (q[0] * target[0] + q[1] * target[1])) >= 0) then
		q[0], q[1], q[2], q[3] = -q[0], -q[1], -q[2], -q[3]
	end
	q[0], q[1], q[2] = -q[0], -q[1], -q[2]
	local turn, axis = {}, v3()
	quatMultiply(turn, q, target)
	normalize3(axis, turn)
	local half = acos(clamp(turn[3], -1, 1))
	local angle = max(half + half, -limit)
	if not (limit >= angle) then
		angle = limit
	end
	toWorld(bias, child.rotation, v3(axis[0] * angle, axis[1] * angle, axis[2] * angle))
end

local function finishLimbJoint(child, bias, velocity, angularLimit)
	bias[0] = velocity[0] * 0.5 + bias[0]
	bias[1] = velocity[1] * 0.5 + bias[1]
	bias[2] = velocity[2] * 0.5 + bias[2]
	child.bond.has_axis = false
	child.bond.angular_limit = angularLimit
end

local function limbIK(h, parentBone, bone, target, frame, velocity, length, twist, wristTurn, changeLimit,
		angularLimit, limit, flags)
	local upper, lower, hand = h.bones[bone], h.bones[bone + 1], h.bones[bone + 2]
	local flag2, flag4, flag8 = hasFlag(flags, 2), hasFlag(flags, 4), hasFlag(flags, 8)
	local q, m = {}, {}


	local reach = sqrt((target[0] * target[0] + target[1] * target[1]) + target[2] * target[2])
	if reach > abs(length) then
		reach = abs(length)
	end
	local bend = acos(clamp(reach / length, -1, 1)) * -2
	if flag4 then
		bend = -bend
	end

	jointRotation(q, h.bones[parentBone], upper)


	local l = v3()
	toLocal(l, frame, target)
	if not flag4 and l[1] > -0.0625 then
		l[1] = -0.0625
	end
	local row1 = v3(-l[0], -l[1], -l[2])
	normalize3(row1, row1)

	local row2 = v3(0, -row1[2], row1[1])
	normalize3(row2, row2)
	local row0 = v3(
		row2[2] * row1[1] - row2[1] * row1[2],
		row2[0] * row1[2] - row2[2] * row1[0],
		row2[1] * row1[0] - row2[0] * row1[1])
	normalize3(row0, row0)

	m[0], m[1], m[2] = row0[0], row1[0], row2[0]
	m[3], m[4], m[5] = row0[1], row1[1], row2[1]
	m[6], m[7], m[8] = row0[2], row1[2], row2[2]
	rotateRows(m, 0, 1, 0, twist)
	rotateRows(m, 1, 0, 0, bend * -0.5)
	local shoulderTarget, conjugateSource = {}, {}
	quatFromMat3(shoulderTarget, m)
	for i = 0, 3 do
		conjugateSource[i] = shoulderTarget[i]
	end
	if flag8 then
		local n = identity3()
		rotateRows(n, 0, 1, 0, twist)
		rotateRows(n, 1, 0, 0, bend * -0.5)
		quatFromMat3(conjugateSource, n)
	end

	local bias = upper.bond.bias
	limbJointBias(bias, q, shoulderTarget, upper, limit)
	bias[0] = velocity[0] * 0.5 + bias[0]
	bias[1] = velocity[1] * 0.5 + bias[1]
	bias[2] = velocity[2] * 0.5 + bias[2]
	if bone == 10 or bone == 13 then
		local hipTurn = h.hip_turn[bone == 10 and 0 or 1]
		bias[0] = bias[0] + hipTurn[0]
		bias[1] = bias[1] + hipTurn[1]
		bias[2] = bias[2] + hipTurn[2]
	end
	if hasFlag(flags, 0x10) then
		limitJointChange(h, parentBone, bone, bias, changeLimit, 1)
	end
	upper.bond.has_axis = false
	upper.bond.angular_limit = angularLimit[0]


	jointRotation(q, upper, lower)
	local sine, cosine = sin(bend * 0.5), cos(bend * 0.5)
	if not (sine * q[0] + cosine * q[3] >= 0) and not (cosine * q[3] >= 0) then
		q[0], q[1], q[2], q[3] = -q[0], -q[1], -q[2], -q[3]
	end
	q[0], q[1], q[2] = -q[0], -q[1], -q[2]
	do
		local x = cosine * q[0] + sine * q[3]
		local z = q[2] * cosine - q[1] * sine
		local w = cosine * q[3] - sine * q[0]
		local y = q[2] * sine + q[1] * cosine
		local axis = v3()
		normalize3(axis, v3(x, y, z))
		local half = acos(clamp(w, -1, 1))
		local angle = max(half + half, -limit)
		if not (limit >= angle) then
			angle = limit
		end
		bias = lower.bond.bias
		toWorld(bias, lower.rotation, v3(axis[0] * angle, axis[1] * angle, axis[2] * angle))
		finishLimbJoint(lower, bias, velocity, angularLimit[1])
	end


	jointRotation(q, lower, hand)
	local wristTarget = {[0] = 0, 0, 0, 1}
	do
		local s, cx, cy, cz = sine, conjugateSource[0], conjugateSource[1], conjugateSource[2]
		if flag2 then
			s, cx, cy, cz = -s, -cx, -cy, -cz
			wristTarget[3] = cosine
			wristTarget[0] = s
			quatMultiply(wristTarget, wristTarget, {[0] = cx, cy, cz, conjugateSource[3]})
			if not (((wristTarget[3] * wristTurn[3] + wristTarget[2] * wristTurn[2])
					+ (wristTarget[1] * wristTurn[1] + wristTarget[0] * wristTurn[0])) >= 0) then
				for i = 0, 3 do
					wristTurn[i] = -wristTurn[i]
				end
			end
			quatMultiply(wristTarget, wristTarget, wristTurn)
		end
		if flag8 then
			s, cx, cy, cz = -s, -cx, -cy, -cz
			wristTarget[3] = cosine
			wristTarget[0] = s
			wristTarget[1] = 0
			wristTarget[2] = 0
			quatMultiply(wristTarget, wristTarget, {[0] = cx, cy, cz, conjugateSource[3]})
		end
	end
	bias = hand.bond.bias
	limbJointBias(bias, q, wristTarget, hand, limit)
	finishLimbJoint(hand, bias, velocity, angularLimit[2])
end

local function spineYaw(h)
	if h.seat then return (h.look_yaw_offset + h.drive_lean) * .5 end
	return (((h.input_spine_twist * 0.5) + h.look_yaw_offset) + h.drive_lean) * 0.5
end

local function driveLowerSpine(h)
	local pelvis, stomach = h.bones[BONE_PELVIS], h.bones[BONE_STOMACH]
	local q, axis, damping = {}, v3(), v3()
	local bias = stomach.bond.bias
	jointRotation(q, pelvis, stomach)
	local pitch
	if hasFlag(h.input_flags, INPUT_THROW) then
		pitch = h.view_pitch * 0.5
	else
		pitch = (h.view_pitch + h.input_spine_bend) * 0.75
	end
	if h.seat then pitch = h.input_pitch end
	pitch = pitch * 0.75
	local yaw = spineYaw(h)
	local sy, cy = sin(yaw * -0.5), cos(yaw * -0.5)
	local sp, cp = sin(pitch * -0.5), cos(pitch * -0.5)
	local target = {[0] = sp * cy, cp * sy, -(sp * sy), cp * cy}

	local angle = limitAngle(jointTurn(axis, q, target))
	jointDamping(damping, pelvis, stomach)
	setJointBias(bias, stomach, axis, angle, damping)
	limitJointChange(h, BONE_PELVIS, BONE_STOMACH, bias, 1.125, 1)
	stomach.bond.angular_limit = 0
end

local function driveUpperSpine(h)
	local stomach, chest = h.bones[BONE_STOMACH], h.bones[BONE_CHEST]
	local q, axis, damping = {}, v3(), v3()
	local bias = chest.bond.bias
	jointRotation(q, stomach, chest)
	local pitch
	if hasFlag(h.input_flags, INPUT_THROW) then
		pitch = h.view_pitch * 0.5
	else
		pitch = h.input_spine_bend * 0.75 + h.view_pitch * 0.25
	end
	if h.seat then pitch = h.input_pitch end
	pitch = pitch * 0.5
	local sp, cp = sin(pitch * -0.5), cos(pitch * -0.5)
	local yaw = spineYaw(h)
	local sy, cy = sin(yaw * -0.5), cos(yaw * -0.5)
	local target = {[0] = cy * sp, sy * cp, sy * sp, cy * cp}

	local angle = limitAngle(jointTurn(axis, q, target))
	jointDamping(damping, stomach, chest)
	setJointBias(bias, chest, axis, angle, damping)
	limitJointChange(h, BONE_STOMACH, BONE_CHEST, bias, 1.125, 1)
	chest.bond.angular_limit = 0
	return damping
end

local function buildLookPose(h, twist)
	local function turn(axis, halfAngle)
		local q = {[0] = 0, 0, 0, cos(halfAngle)}
		q[axis] = sin(halfAngle)
		return q
	end
	local pose = h.pose_rotations
	for i = 0, 3 do
		pose[i] = {[0] = 0, 0, 0, 1}
	end
	local q = turn(1, (h.input_spine_twist * 0.5 + h.look_yaw_offset) * -0.5)
	quatMultiply(pose[0], pose[0], q)
	q = turn(0, h.view_pitch * -0.25)
	quatMultiply(pose[0], pose[0], q)
	quatMultiply(pose[3], pose[3], q)
	q = turn(0, h.input_spine_bend * -0.375)
	quatMultiply(pose[0], pose[0], q)

	q = turn(0, h.view_pitch * -0.125)
	quatMultiply(pose[1], pose[1], q)
	quatMultiply(pose[3], pose[3], q)
	q = turn(1, twist * -0.5)
	quatMultiply(pose[1], pose[1], q)
	quatMultiply(pose[3], pose[3], q)
	q = turn(1, h.input_spine_twist * -0.125)
	quatMultiply(pose[1], pose[1], q)

	pose[3][0], pose[3][1], pose[3][2] = -pose[3][0], -pose[3][1], -pose[3][2]
end

local function driveSpineToLookPose(h)
	local pelvis, stomach, chest = h.bones[BONE_PELVIS], h.bones[BONE_STOMACH], h.bones[BONE_CHEST]
	local q, axis = {}, v3()
	buildLookPose(h, h.drive_lean)

	jointRotation(q, pelvis, stomach)
	local angle = limitAngle(jointTurn(axis, q, h.pose_rotations[0]))
	toWorld(stomach.bond.bias, stomach.rotation, v3(axis[0] * angle, axis[1] * angle, axis[2] * angle))
	stomach.bond.angular_limit = 0

	jointRotation(q, stomach, chest)
	angle = limitAngle(jointTurn(axis, q, h.pose_rotations[1]))
	toWorld(chest.bond.bias, chest.rotation, v3(axis[0] * angle, axis[1] * angle, axis[2] * angle))
	chest.bond.angular_limit = 0
end

local function driveHead(h, stomachDamping)
	local chest, head = h.bones[BONE_CHEST], h.bones[BONE_HEAD]
	local q, axis = {}, v3()
	local bias = head.bond.bias
	jointRotation(q, chest, head)
	local yaw = h.input_spine_twist * 0.5 - h.drive_lean
	local sy, cy = sin(yaw * -0.5), cos(yaw * -0.5)
	local tx, ty, tz, tw = 0, sy, 0, cy
	if h.zoom_level == 2 and h.drive_aiming then

		tx = sy * -0.098017141
		ty = sy * 0.99518472
		tz = cy * -0.098017141
		tw = cy * 0.99518472
	end
	local pitch = h.input_spine_bend * 0.25 + h.view_pitch * 0.5
	local sp, cp = sin(pitch * -0.5), cos(pitch * -0.5)
	local target = {[0] = tx * cp + tw * sp, ty * cp + tz * sp, tz * cp - ty * sp, tw * cp - tx * sp}

	if h.drive_aiming and not h.seat then

		local p = h.pose_rotations[3]
		local s, c = sin(h.view_pitch * -0.5), cos(h.view_pitch * -0.5)
		local y = p[2] * s + p[1] * c
		local z = p[2] * c - p[1] * s
		local x = c * p[0] + s * p[3]
		local w = c * p[3] - s * p[0]
		s, c = sin(h.input_spine_twist * -0.125), cos(h.input_spine_twist * -0.125)
		target[0] = x * c - z * s
		target[1] = y * c + w * s
		target[2] = z * c + x * s
		target[3] = w * c - y * s
	end

	local angle = limitAngle(jointTurn(axis, q, target))
	setJointBias(bias, head, axis, angle, stomachDamping)
	limitJointChange(h, BONE_CHEST, BONE_HEAD, bias, 1.125, 1)
	head.bond.angular_limit = 0
end

local function emptyHandTarget(h, side, bothHandsEmpty, target)
	h.arm_pose_twist = h.arm_pose_twist or {[0] = 0, [1] = 0}
	h.arm_active_pose = h.arm_active_pose or {[0] = false, [1] = false}
	h.arm_pose_twist[side] = 0
	h.arm_active_pose[side] = false

	local outSign = (side == 1) and 1 or -1
	local swingMult = (Cfg and Cfg.ArmSwing) or 1.2
	local turnOut = min(abs(h.smoothed_angular_velocity[1]) * 1.5 + abs(h.lean_side) * 2.5, 0.16)
	target[0] = outSign * (0.0625 + turnOut)
	local swing = h.stride_lean * 0.39269908169875 * swingMult
	if h.zoom_level > 0 then
		swing = swing * 0.55
	end
	if side == 1 then
		swing = -swing
	end
	local bend = swing + (h.zoom_level ~= 0 and 0.196349540849375 or 0.39269908169875)
	if h.jump_charge > 0 then
		bend = PI_4
	end
	local scale = h.zoom_level ~= 0 and 0.875 or 0.75
	if h.movement_state == STATE_FALL or h.movement_state == STATE_JUMP then
		scale = 0.9375
		bend = 1.570796326795 - (h.input_spine_bend + h.view_pitch)
	end

	if h.seat then bend = 1.570796326795 end
	target[1] = cos(bend) * -0.65625 * scale
	target[2] = sin(bend) * -0.65625 * scale

	-- Independent LMB (left arm), RMB (right arm), or LMB+RMB (both arms) reach toward look direction
	local lmb = hasFlag(h.input_flags, INPUT_PRIMARY)
	local rmb = hasFlag(h.input_flags, INPUT_AIM)
	local reachThisArm = false
	if bothHandsEmpty and (Cfg == nil or Cfg.MouseReach ~= false) and not (Bonds.boxing and Bonds.boxing:posing(h)) then
		if side == 0 and lmb then
			reachThisArm = true
		elseif side == 1 and rmb then
			reachThisArm = true
		end
	elseif bothHandsEmpty and side == 1 and h.input_flags % 4 == 3 then
		reachThisArm = true
	end

	if reachThisArm then
		h.arm_active_pose[side] = true
		target[0] = -outSign * 0.06
		target[1] = 0.05
		target[2] = -0.64
		local a = clamp(h.view_pitch + h.input_spine_bend * 0.75, -0.85, 0.95)
		rotateVector(target, 1, 0, 0, a)
		a = clamp(h.input_spine_twist * 0.75, -0.68722339, PI_4)
		rotateVector(target, 0, 1, 0, a)
		return
	end

	-- 12 Physics-Driven Arm Poses:
	-- 1 = Hands Up / Surrender (H)
	-- 2 = Wave / Greet (G)
	-- 3 = Crossed Arms / Folded (J)
	-- 4 = Hands Behind Back / Parade Rest (K)
	-- 5 = Hands on Hips / Akimbo (L)
	-- 6 = Military Salute (U)
	-- 7 = Facepalm / Hold Head (I)
	-- 8 = T-Pose (O)
	-- 9 = Double Bicep Flex (P)
	-- 10 = Point Forward / Accuse (Y)
	-- 11 = Thinker / Chin Stroke (T)
	-- 12 = Zombie / Franken-Reach (F)
	local poseMode = h.arm_pose_mode or 0
	if bothHandsEmpty and poseMode ~= 0 then
		if poseMode == 1 then
			-- 1: Hands Up / Surrender (H)
			local sway = sin(gameTick * 0.08 + side * 1.5) * 0.025
			target[0] = outSign * 0.14 + sway
			target[1] = 0.48
			target[2] = -0.18
			h.arm_pose_twist[side] = outSign * 0.45
			h.arm_active_pose[side] = true
			return
		elseif poseMode == 2 then
			-- 2: Wave / Greet (G) - right hand waves high, left hand rests on hip
			if side == 1 then
				local waveAngle = sin(gameTick * 0.28) * 0.22
				target[0] = 0.18 + waveAngle
				target[1] = 0.46 + abs(cos(gameTick * 0.28)) * 0.05
				target[2] = -0.22
				h.arm_pose_twist[side] = 0.5
			else
				target[0] = -0.16
				target[1] = -0.32
				target[2] = -0.10
				h.arm_pose_twist[side] = -1.05
			end
			h.arm_active_pose[side] = true
			return
		elseif poseMode == 3 then
			-- 3: Crossed Arms / Folded (J)
			target[0] = -outSign * 0.24
			target[1] = -0.10 + (side == 1 and 0.035 or -0.02)
			target[2] = -0.32
			h.arm_pose_twist[side] = outSign * 0.85
			h.arm_active_pose[side] = true
			return
		elseif poseMode == 4 then
			-- 4: Hands Behind Back / Parade Rest (K)
			target[0] = -outSign * 0.15
			target[1] = -0.36
			target[2] = 0.25
			h.arm_pose_twist[side] = -outSign * 0.65
			h.arm_active_pose[side] = true
			return
		elseif poseMode == 5 then
			-- 5: Hands on Hips / Akimbo (L)
			target[0] = outSign * 0.18
			target[1] = -0.30
			target[2] = -0.12
			h.arm_pose_twist[side] = outSign * 1.25
			h.arm_active_pose[side] = true
			return
		elseif poseMode == 6 then
			-- 6: Military Salute (U)
			if side == 1 then
				target[0] = -0.05
				target[1] = 0.30 - h.view_pitch * 0.12
				target[2] = -0.26
				h.arm_pose_twist[side] = 1.15
				h.arm_active_pose[side] = true
				return
			end
		elseif poseMode == 7 then
			-- 7: Facepalm / Hold Head in Disbelief (I)
			if side == 1 then
				target[0] = -0.14
				target[1] = 0.24 - h.view_pitch * 0.15
				target[2] = -0.28
				h.arm_pose_twist[side] = 0.55
			else
				target[0] = 0.14
				target[1] = 0.24 - h.view_pitch * 0.15
				target[2] = -0.28
				h.arm_pose_twist[side] = -0.55
			end
			h.arm_active_pose[side] = true
			return
		elseif poseMode == 8 then
			-- 8: T-Pose / Assert Dominance (O)
			target[0] = outSign * 0.62
			target[1] = 0.04
			target[2] = -0.02
			h.arm_pose_twist[side] = 0
			h.arm_active_pose[side] = true
			return
		elseif poseMode == 9 then
			-- 9: Double Bicep Flex / Bodybuilder (P)
			local pulse = sin(gameTick * 0.4) * 0.015
			target[0] = outSign * (0.34 + pulse)
			target[1] = 0.36 + pulse
			target[2] = -0.14
			h.arm_pose_twist[side] = -outSign * 0.45
			h.arm_active_pose[side] = true
			return
		elseif poseMode == 10 then
			-- 10: Point Forward / Accuse (Y)
			if side == 1 then
				target[0] = -0.06
				target[1] = 0.06
				target[2] = -0.64
				local a = clamp(h.view_pitch + h.input_spine_bend * 0.75, -0.85, 0.95)
				rotateVector(target, 1, 0, 0, a)
				a = clamp(h.input_spine_twist * 0.75, -0.68722339, PI_4)
				rotateVector(target, 0, 1, 0, a)
			else
				target[0] = -0.16
				target[1] = -0.32
				target[2] = -0.10
				h.arm_pose_twist[side] = -1.1
			end
			h.arm_active_pose[side] = true
			return
		elseif poseMode == 11 then
			-- 11: Thinker / Chin Stroke (T)
			if side == 1 then
				local stroke = sin(gameTick * 0.14) * 0.02
				target[0] = -0.15 + stroke
				target[1] = 0.14 - h.view_pitch * 0.15
				target[2] = -0.28
				h.arm_pose_twist[side] = 0.35
			else
				target[0] = 0.20
				target[1] = -0.14
				target[2] = -0.30
				h.arm_pose_twist[side] = -0.8
			end
			h.arm_active_pose[side] = true
			return
		elseif poseMode == 12 then
			-- 12: Zombie / Franken-Reach (F)
			local zSway = sin(gameTick * 0.09 + side * 2.1) * 0.05
			target[0] = outSign * 0.06 + cos(gameTick * 0.07 + side) * 0.04
			target[1] = 0.06 + zSway - h.view_pitch * 0.25
			target[2] = -0.58
			h.arm_pose_twist[side] = outSign * 0.25
			h.arm_active_pose[side] = true
			return
		end
	end

	-- Procedural Wall-Bracing & Stumble Catch Reflex
	if bothHandsEmpty and (Cfg == nil or Cfg.ArmBraceReflex ~= false) and not h.seat then
		local chest = h.bones[BONE_CHEST]
		local r, offset = chest.rotation, ARM_OFFSET[side]
		local sx = ((r[0] * offset[0] + chest.position[0]) + r[3] * offset[1]) + r[6] * offset[2]
		local sy = ((r[1] * offset[0] + chest.position[1]) + r[4] * offset[1]) + r[7] * offset[2]
		local sz = ((r[2] * offset[0] + chest.position[2]) + r[5] * offset[1]) + r[8] * offset[2]
		local cv = h.centre_velocity
		local speedXZ = sqrt(cv[0] * cv[0] + cv[2] * cv[2])
		local tilting = h.smoothed_rotation[4] < 0.78
		if speedXZ > 0.035 or tilting or h.movement_state == STATE_FALL then
			local dirX = -r[6] * 0.55 + cv[0] * 6 + (side == 1 and r[0] or -r[0]) * 0.15
			local dirY = (tilting or h.movement_state == STATE_FALL) and -0.55 or -0.12
			local dirZ = -r[8] * 0.55 + cv[2] * 6 + (side == 1 and r[2] or -r[2]) * 0.15
			local fromPt = v3(sx, sy, sz)
			local toPt = v3(sx + dirX, sy + dirY, sz + dirZ)
			if levelRay(fromPt, toPt) and collisionHit.fraction < 0.92 then
				local hitWorld = v3(
					collisionHit.point[0] - sx,
					collisionHit.point[1] - sy,
					collisionHit.point[2] - sz
				)
				local localHit = v3()
				toLocal(localHit, r, hitWorld)
				target[0] = clamp(localHit[0], -0.45, 0.45)
				target[1] = clamp(localHit[1], -0.58, 0.45)
				target[2] = clamp(localHit[2], -0.62, 0.25)
				h.arm_active_pose[side] = true
			end
		end
	end
end

local function pushSpring(h)
	local p, v = h.idle_sway, h.idle_sway_velocity
	local push = v3()
	randomDirection(push, 0.0078125, 0)
	for k = 0, 2 do
		v[k] = ((push[k] + v[k]) - p[k] * 0.00390625) * 0.9375
		p[k] = v[k] + p[k]
	end
end

local function probeAhead(h, side, target)
	local chest = h.bones[BONE_CHEST]
	local r, offset = chest.rotation, ARM_OFFSET[side]
	local n = v3(r[1], r[4], r[7])
	normalize3(n, n)
	local point = v3(
		((r[0] * offset[0] + chest.position[0]) + r[3] * offset[1]) + r[6] * offset[2],
		((r[1] * offset[0] + chest.position[1]) + r[4] * offset[1]) + r[7] * offset[2],
		((r[2] * offset[0] + chest.position[2]) + r[5] * offset[1]) + r[8] * offset[2])
	local reach = 0.65625
	if levelRay(point, v3(point[0], point[1] - 1, point[2])) then
		reach = (point[1] - collisionHit.point[1]) + 0.00390625
	end
	reach = -min(reach, 0.65625)
	target[0], target[1], target[2] = n[0] * reach, n[1] * reach, n[2] * reach
end

local ARM_FRAME = identity3()
local ZERO3 = v3()

local ARM = {}
Bonds.arm = ARM

function ARM.chooseItem(h, side)
	local hands = h.hands
	if side == 1 then
		return hands[0], false, 0
	end
	if hands[1] then
		return hands[1], false, 0
	end
	local item = hands[0]
	if item and item.type.hands > 1
			and (h.smoothed_rotation[4] > 0.70700002 or not hasFlag(h.input_flags, INPUT_CROUCH)) then
		return item, true, 1
	end
	return nil, false, 0
end

local Grab = {}
Bonds.grab = Grab

function Grab.release(h, side)
	if not h or not h.grabs then return end
	for i = 0, 1 do
		if side == nil or side == i then
			local g = h.grabs[i]
			h.grabs[i] = nil
		end
	end
end
Bonds.releaseGrab = Grab.release

function Grab.update(h)
	h.grabs = h.grabs or {}
	if not h.input_grab or h.old_health <= 0 or h.health < 50 or h.seat or h.canGrab == false then
		Grab.release(h)
		return
	end
	local lmb = hasFlag(h.input_flags, INPUT_PRIMARY)
	local rmb = hasFlag(h.input_flags, INPUT_AIM)
	for side = 0, 1 do
		local wantSide = true
		if lmb and not rmb then
			wantSide = (side == 0)
		elseif rmb and not lmb then
			wantSide = (side == 1)
		end
		local occupied = h.hands[side == 0 and 1 or 0]
		local right = h.hands[0]
		if side == 0 and right and right.type.hands > 1 then occupied = right end
		if Bonds.thrower and Bonds.thrower:holdsArm(side) then occupied = true end
		if occupied or not wantSide then
			Grab.release(h, side)
		elseif not h.grabs[side] then
			h.grabs[side] = {}
		end
	end
end

function Grab.target(h, side, target)
	if not h.grabs or not h.grabs[side] then return false end
	local z = min(abs(h.view_pitch / 10), 0.1)
	target[0], target[1], target[2] = side == 0 and 0.1 or -0.1, 0.05 - z * 1.1, -0.55 - z
	if hasFlag(h.input_flags, INPUT_AIM) then target[2] = target[2] + 0.18 end
	return true
end

function Grab.armFrame(h, side, limb, torsoFrame)
	local b = h.bones[BONE_HAND + side * 3].body
	local palm = Vector3.new(b.px * SCALE, b.py * SCALE, b.pz * SCALE)


	local up = limb:vectorToWorldSpace(Vector3.new(0, SCALE / BASE_SCALE, 0))
	return (limb - limb.p) + (palm + up)
end

function Grab.touchItem(h, hand, g)
	for _, item in ipairs(Items.list or {}) do
		if not item.gone and not item.hidden and not item.holder and not item.parent and (item.mine or item.free) then
			local b, half, p = item.body, item.type.half, v3()
			toLocal(p, b.R, v3(hand.px - b.px, hand.py - b.py, hand.pz - b.pz))
			local x, y, z = clamp(p[0], -half[0], half[0]), clamp(p[1], -half[1], half[1]), clamp(p[2], -half[2], half[2])
			if (p[0]-x)^2 + (p[1]-y)^2 + (p[2]-z)^2 <= 0.01 then
				local point = v3(); toWorld(point, b.R, v3(x, y, z))
				point[0], point[1], point[2] = point[0]+b.px, point[1]+b.py, point[2]+b.pz
				if not levelRay(v3(hand.px, hand.py, hand.pz), point) then
					g.item, g.offset = item, v3(x, y, z)
					item.mine, item.claiming, item.rest, item.dropOwner = true, true, 0, nil
					for _, child in ipairs(item.children) do child.mine, child.claiming = true, true end
					return
				end
			end
		end
	end
end

function Grab.touchWorld(hand, bone, g)


	for axis = 0, 3 do
		local from, to = v3(), v3(hand.px, hand.py, hand.pz)
		if axis == 3 then for k = 0, 2 do from[k] = bone.previous_position[k] end
		else
			local r, k = hand.R, axis * 3
			from[0], from[1], from[2] = hand.px+r[k]*.1, hand.py+r[k+1]*.1, hand.pz+r[k+2]*.1
			to[0], to[1], to[2] = hand.px-r[k]*.1, hand.py-r[k+1]*.1, hand.pz-r[k+2]*.1
		end
		if levelRay(from, to) and (collisionHit.part.CanCollide or (Grab.isVehicleHull and Grab.isVehicleHull(collisionHit.part))) then
			g.part = collisionHit.part
			local p = collisionHit.point
			g.offset = g.part.CFrame:inverse() * Vector3.new(p[0]*SCALE, p[1]*SCALE, p[2]*SCALE)
			return
		end
	end
end

function Grab.bind(h)
	if (h.mantle_cool or 0) > 0 then h.mantle_cool = h.mantle_cool - 1 end
	if not h.input_grab or h.old_health <= 0 or h.health < 50 or h.seat then Grab.release(h); return end
	for side = 0, 1 do
		local g = h.grabs and h.grabs[side]
		if g then
			local bone = h.bones[BONE_HAND + 3 * side]
			local hand = bone.body
			if not g.item and not g.part and not g.peer then
				Grab.touchItem(h, hand, g)
				if not g.item and h.canGrabWorld ~= false and (h.mantle_cool or 0) <= 0 then Grab.touchWorld(hand, bone, g) end
			end
			if g.peer then
				if Grab.bindPeer then Grab.bindPeer(h, side, g) end
			elseif g.item then
				local item = g.item
				if item.gone or item.holder or item.parent or not item.mine then Grab.release(h, side)
				else
					item.body.settled, item.rest, item.dropOwner = false, 0, nil
					local o = g.offset
					Bonds.point(hand, item.body, 0, 0, 0, o[0], o[1], o[2])
				end
			elseif g.part then
				if not g.part.Parent or not (g.part.CanCollide or (Grab.isVehicleHull and Grab.isVehicleHull(g.part))) then Grab.release(h, side)
				else
					local p = g.part.CFrame * g.offset
					local mantleDone = false
					if CLIMB_SPEED > 0 and typeof(g.offset) == "Vector3" then
						local half = g.part.Size * 0.5
						local step = h.input_forward * CLIMB_SPEED * TICK
						-- a part whose top face points up is a ledge we can pull ourselves over
						local ledge = g.part.CFrame:VectorToObjectSpace(Vector3.new(0, 1, 0)).Y > 0.7
						local over = g.over or 0
						if h.input_forward ~= 0 and not (ledge and over > 0 and step < 0) then
							-- Climb: slide the grip point along world-up, never past the part's bounds.
							local o = g.offset + g.part.CFrame:VectorToObjectSpace(Vector3.new(0, step, 0))
							g.offset = Vector3.new(
								clamp(o.X, -half.X - 0.1, half.X + 0.1),
								clamp(o.Y, -half.Y - 0.1, half.Y + 0.1),
								clamp(o.Z, -half.Z - 0.1, half.Z + 0.1))
						end
						if ledge then
							-- Mantle: at the top edge, W keeps raising the hands above the ledge (S lowers them back).
							if h.input_forward > 0 and g.offset.Y >= half.Y + 0.05 then
								over = math.min(over + step, MANTLE.reach)
							elseif h.input_forward < 0 and over > 0 then
								over = math.max(0, over + step)
							end
							g.over = over
						end
						p = g.part.CFrame * g.offset
						if ledge and over > 0 then
							local v = g.offset
							local pb = h.bones[BONE_PELVIS].body
							local pl = g.part.CFrame:PointToObjectSpace(Vector3.new(pb.px, pb.py, pb.pz) * SCALE)
							local xFace = math.abs(v.X) / math.max(half.X, 0.01) > math.abs(v.Z) / math.max(half.Z, 0.01)
							-- how far inside the ledge's edge the hips are (negative = still outside)
							local depth = xFace and (half.X - math.sign(v.X) * pl.X) or (half.Z - math.sign(v.Z) * pl.Z)
							if pl.Y > half.Y + MANTLE.clear and depth >= MANTLE.depth then
								-- hips are over the ledge: let go and stand up
								g.over = 0
								mantleDone = true
								h.mantle_cool = 45 -- ticks without world grabs so we don't instantly re-grab the ledge
							else
								-- lift the whole body together so it doesn't tumble: up first, then over the edge
								local lift = MANTLE.lift * TICK / BASE_SCALE
								local push = MANTLE.push * TICK / BASE_SCALE
								local inward = g.part.CFrame:VectorToWorldSpace(xFace and Vector3.new(-math.sign(v.X), 0, 0) or Vector3.new(0, 0, -math.sign(v.Z)))
								local overEdge = pl.Y > half.Y - 0.3
								for i = 0, 15 do
									local bd = h.bones[i].body
									if overEdge then
										if bd.vy < lift * 0.5 then bd.vy = lift * 0.5 end
										local c = bd.vx * inward.X + bd.vz * inward.Z
										if c < push then
											bd.vx, bd.vz = bd.vx + (push - c) * inward.X, bd.vz + (push - c) * inward.Z
										end
									elseif bd.vy < lift then
										bd.vy = lift
									end
								end
								-- hands rest just over the edge, slightly inward
								local d = math.min(over * 1.2, MANTLE.inward)
								local lp = Vector3.new(v.X, half.Y + over, v.Z)
								if xFace then
									lp = Vector3.new(v.X - math.sign(v.X) * d, lp.Y, v.Z)
								else
									lp = Vector3.new(v.X, lp.Y, v.Z - math.sign(v.Z) * d)
								end
								p = g.part.CFrame * lp
							end
						end
					end
					local dx, dy, dz = p.x/SCALE-hand.px, p.y/SCALE-hand.py, p.z/SCALE-hand.pz

					if mantleDone or dx*dx+dy*dy+dz*dz > 1 then Grab.release(h, side)
					else
						local b = g.anchor or {R=identity3(), mass=1, wx=0, wy=0, wz=0}
						b.vx, b.vy, b.vz = g.last and (p.x-g.last.x)/SCALE or 0, g.last and (p.y-g.last.y)/SCALE or 0, g.last and (p.z-g.last.z)/SCALE or 0
						b.px, b.py, b.pz = p.x/SCALE, p.y/SCALE, p.z/SCALE
						b.dvx,b.dvy,b.dvz,b.dwx,b.dwy,b.dwz = 0,0,0,0,0,0
						g.anchor, g.last = b, p
						local c = Bonds.point(hand, b, 0,0,0, 0,0,0)
						c.share_a, c.share_b = 1, 0
						if Grab.moveProp then Grab.moveProp(h, side, g, p, hand) end
					end
				end
			end
		end
	end
end

function ARM.baseHandRotation(h, item, aimed, r)
	local follow = hasFlag(h.input_flags, INPUT_THROW) or h.inventory_anim_flags == 0
	if not item then
		return
	end
	rotateRows(r, 1, 0, 0, h.view_pitch * 0.5 - 0.049087387)
	rotateAboutRow(r, 0, 0.0061359233)
	rotateAboutRow(r, 1, -0.018407769)
	if h.inventory_anim_flags == 1 then
		rotateAboutRow(r, 2, PI_8)
	end
	if not h.seat and hasFlag(h.input_flags, INPUT_AIM) then
		rotateRows(r, 1, 0, 0, PI_4)
	end
	if follow then
		rotateRows(r, 1, 0, 0, h.throw_pitch + h.throw_pitch)
	end
	rotateRows(r, 0, 1, 0, -h.drive_lean)
	if aimed and not h.seat then

		local p = h.pose_rotations[3]
		mat3FromQuat(r, {[0] = -p[0], -p[1], -p[2], p[3]})
		rotateAboutRow(r, 0, h.view_pitch - 0.03681553890925782)
		if hasFlag(h.input_flags, INPUT_AIM) then
			rotateAboutRow(r, 0, PI_4)
		end
		if follow then
			rotateAboutRow(r, 0, h.throw_pitch + h.throw_pitch)
		end
	end
end

function ARM.handOffset(h, side, item, r, offset)
	local a, b, c = 0.1875, 0.0625, 0
	if h.zoom_level == 2 then
		a, b = 0.0625, 0.125
	end
	if h.seat and item.type.gun then b = .125 end
	if side == 0 and h.hands[1] then
		a, b = -0.125, 0.125
	end
	if hasFlag(h.input_flags, INPUT_THROW) or h.inventory_anim_flags == 0 then
		local reach = -0.25 - sin(min(h.throw_pitch + 1.17809724509625, 0) * 3) * 0.375
		c = reach * r[8]
		a = a + reach * r[6]
		b = b + reach * r[7]
	end
	offset[0] = ((a - r[6] * 0.1875) - r[6] * 0.375) + r[3] * 0.0625
	offset[1] = ((b - r[7] * 0.1875) - r[7] * 0.375) + r[4] * 0.0625
	offset[2] = ((c - r[8] * 0.1875) - r[8] * 0.375) + r[5] * 0.0625
	if item.type.id == 11 then
		if h.zoom_level == 2 then
			offset[0] = offset[0] + r[6] * -0.25
			offset[1] = offset[1] + r[7] * -0.25
			offset[2] = offset[2] + r[8] * -0.25
		else
			offset[0] = offset[0] + r[3] * -0.125
			offset[1] = offset[1] + r[4] * -0.125
			offset[2] = offset[2] + r[5] * -0.125
		end
	end
	if side == 0 and h.hands[1] then
		offset[0] = offset[0] + r[6] * 0.125
		offset[1] = offset[1] + r[7] * 0.125
		offset[2] = offset[2] + r[8] * 0.125
	end
end

function ARM.aimHandTarget(target, h, grip, itemType, r)
	local x, y, z = 0.1875 - 0.0625, 0.0625, -0.09375
	if h.inventory_anim_flags ~= 1 and h.zoom_level < 2 then
		y = y - 0.25
	end

	local sight, offset = itemType.sight, itemType.grip[grip]
	for row = 0, 2 do
		local s = -sight[row]
		x = s * r[row * 3] + x
		y = s * r[row * 3 + 1] + y
		z = s * r[row * 3 + 2] + z
	end
	for row = 0, 2 do
		local g = offset[row]
		x = g * r[row * 3] + x
		y = g * r[row * 3 + 1] + y
		z = g * r[row * 3 + 2] + z
	end
	target[0], target[1], target[2] = x, y, z
end

function ARM.holdItem(h, handBone, item, gripOffset, gripTurn)
	local hand = h.bones[handBone]
	local body = item.body
	body.settled = false
	Bonds.point(hand.body, body, 0, 0, 0, gripOffset[0], gripOffset[1], gripOffset[2])

	local r, m, q, axis, bias = hand.rotation, {}, {}, v3(), v3()
	multiplyTransposed(m, body.R, r)
	if not (abs(gripTurn[3]) <= 0) then
		rotateRows(m, gripTurn[0], gripTurn[1], gripTurn[2], gripTurn[3])
	end
	quatFromMat3(q, m)
	normalize3(axis, v3(-q[0], -q[1], -q[2]))
	local angle = 2 * acos(clamp(q[3], -1, 1))
	toWorld(bias, r, v3(axis[0] * angle, axis[1] * angle, axis[2] * angle))
	Bonds.rotation(hand.body, body, bias[0] * 0.25, bias[1] * 0.25, bias[2] * 0.25, 0.26666668)
end

function ARM.easeTarget(h, side, target, active)
	h.arm_targets = h.arm_targets or {}
	if not active then h.arm_targets[side] = nil; return end
	local pose = h.arm_targets[side]
	if not pose then
		local free = v3()
		emptyHandTarget(h, side, true, free)
		pose = {position = free, velocity = v3()}
		h.arm_targets[side] = pose
	end
	for k = 0, 2 do
		local punching=Bonds.boxing and Bonds.boxing.responsive and Bonds.boxing.swing==side and not Bonds.boxing.spent
		local velocity = (pose.velocity[k] + (target[k] - pose.position[k]) * (punching and .4 or .28)) * .62
		pose.velocity[k] = velocity
		pose.position[k] = pose.position[k] + velocity
		target[k] = pose.position[k]
	end
end

local function driveArm(h, side, health, bothHandsEmpty)
	local target = v3()
	local shoulder = BONE_SHOULDER + 3 * side
	local chest = h.bones[BONE_CHEST]
	local item, both, gripIndex = ARM.chooseItem(h, side)
	local itemType = item and item.type
	local aimed = item ~= nil and itemType.gun
	local throwing = hasFlag(h.input_flags, INPUT_THROW) or h.inventory_anim_flags == 0
	local r = identity3()
	ARM.baseHandRotation(h, item, aimed, r)

	if item then
		local offset = v3()
		ARM.handOffset(h, side, item, r, offset)
		local g = itemType.grip[gripIndex]
		target[0] = g[2] * r[6] + ((g[0] * r[0] + offset[0]) + g[1] * r[3])
		target[1] = g[2] * r[7] + ((g[0] * r[1] + offset[1]) + g[1] * r[4])
		target[2] = g[2] * r[8] + ((g[0] * r[2] + offset[2]) + g[1] * r[5])
		if aimed and itemType.id ~= 11 and (side == 1 or both) then
			ARM.aimHandTarget(target, h, both and 1 or 0, itemType, r)
		end

		if h.inventory_anim_flags == 1 then
			local along = -(((target[1] * r[1] + target[0] * r[0]) + target[2] * r[2]) * h.inventory_anim_progress)
			target[0] = target[0] + r[0] * along
			target[1] = target[1] + r[1] * along
			target[2] = target[2] + r[2] * along
		end


		local body, tv = item.body, h.trunk_velocity
		local axis = v3()
		toLocal(axis, chest.rotation, v3(body.vx - tv[0], body.vy - tv[1], body.vz - tv[2]))
		if not hasFlag(h.input_flags, INPUT_THROW) and h.inventory_anim_flags ~= 0 then
			target[0] = target[0] + axis[0] * -0.75
			target[1] = target[1] + axis[1] * -0.75
			target[2] = target[2] + axis[2] * -0.75
		end


		local t = itemType.turn[gripIndex]
		if abs(t[3]) > 0 then
			rotateRows(r,
				(r[3] * t[1] + r[0] * t[0]) + r[6] * t[2],
				(r[4] * t[1] + r[1] * t[0]) + r[7] * t[2],
				(r[5] * t[1] + r[2] * t[0]) + r[8] * t[2], -t[3])
		end
	end

	if side == 0 then
		pushSpring(h)
	end
	do
		local offset = ARM_OFFSET[side]
		target[0] = (r[3] * 0.0625 + target[0]) - offset[0]
		target[1] = (r[4] * 0.0625 + target[1]) - offset[1]
		target[2] = (r[5] * 0.0625 + target[2]) - offset[2]
	end
	if not item then
		emptyHandTarget(h, side, bothHandsEmpty, target)
	end
	local holdingTool = not item and Bonds.thrower and Bonds.thrower:target(h, side, target, r)
	local grabbing = not item and not holdingTool and Grab.target(h, side, target)
	local boxing = not item and not grabbing and not holdingTool and Bonds.boxing and Bonds.boxing:target(h, side, target, r)
	local customPose = not item and not grabbing and not boxing and not holdingTool and (h.arm_active_pose and h.arm_active_pose[side] == true)
	ARM.easeTarget(h, side, target, grabbing or boxing or holdingTool or customPose)


	local wristTurn = {}
	quatFromMat3(wristTurn, r)
	wristTurn[0], wristTurn[1], wristTurn[2] = -wristTurn[0], -wristTurn[1], -wristTurn[2]
	local limit = 0.19634955
	if h.inventory_anim_flags == 0 then
		limit = PI_4
	end
	if h.jump_charge > 0 then
		limit = PI_4
	end
	if h.movement_state == STATE_JUMP then
		limit = PI_4
	end
	if not grabbing and not boxing and not holdingTool and not customPose and h.movement_state ~= STATE_LIE and h.on_ground and h.smoothed_rotation[4] < 0.5
			and hasFlag(h.input_flags, INPUT_CROUCH) then
		probeAhead(h, side, target)
	end

	local flags = (item or holdingTool) and 6 or 4
	local changeLimit = 0.29452431
	local angularLimit = {[0] = 0, 0, 0}
	if not (health >= 1) then
		flags = flags + 1
	end
	local itemFree = not item and hasFlag(h.input_flags, side ~= 1 and INPUT_AIM or INPUT_PRIMARY)


	local twist = boxing and .72 or (holdingTool and Bonds.thrower:twist(h, side) or (customPose and h.arm_pose_twist and h.arm_pose_twist[side] or 0))
	if boxing and Bonds.boxing.swing == side and not Bonds.boxing.spent then twist = 0 end
	local done = false
	if grabbing or boxing or holdingTool or customPose or itemFree then
		local punching = boxing and Bonds.boxing.swing ~= nil and not Bonds.boxing.spent
		limit = boxing and (punching and .44 or .3) * health or ((grabbing or holdingTool or customPose) and .46 * health or PI_8)
		if boxing or grabbing or customPose then changeLimit = punching and .18 or .16 end
		if punching and Bonds.boxing.responsive and Bonds.boxing.swing==side then
			limit,changeLimit=.58*health,.24
		end
	else
		local loose = false
		if not item and not h.seat then
			if h.movement_state == STATE_JUMP then
				loose = h.legs[0].progress >= 0.875
			else
				loose = h.movement_state == STATE_FALL and not hasFlag(h.input_flags, INPUT_CROUCH)
			end
		end
		if loose then

			angularLimit[0], angularLimit[1], angularLimit[2] = 0.0625, 0.0625, 0.0625
			limbIK(h, BONE_CHEST, shoulder, target, ARM_FRAME, ZERO3, 0.65625, 0, wristTurn, 0.073631078,
				angularLimit, limit, flags)
			done = true
		elseif item then
			twist = PI_4
			if itemType.id == 11 then
				twist = PI_8
			elseif itemType.id == 3 then
				twist = 1.3744468
			end
		end
	end
	if not done then
		if side == 0 and not customPose then
			twist = -twist
		end
		if throwing then
			twist = 0
		end
		if health < 1 then
			local weak = health * 0.015625 + 0.00390625
			angularLimit[0], angularLimit[1] = weak, weak
		end
		flags = flags + 0x10
		limbIK(h, BONE_CHEST, shoulder, target, ARM_FRAME, ZERO3, 0.65625, twist, wristTurn, changeLimit,
			angularLimit, limit, flags)
	end

	if item then
		ARM.holdItem(h, BONE_HAND + 3 * side, item, itemType.grip[gripIndex], itemType.turn[both and 1 or 0])
	elseif not grabbing and not boxing and not holdingTool and h.movement_state == STATE_LIE then

		local tilt = asin(clamp(h.bones[BONE_PELVIS].rotation[7], -1, 1))
		local bend = tilt * (tilt <= 0 and 0.25 or 4)
		if bend > 2.748893571891069 then
			bend = 2.7488935
		end
		target[0] = side == 1 and 0.09375 or -0.09375
		target[1] = cos(bend) * -0.4921875
		target[2] = sin(bend) * -0.4921875
		local armTwist = bend <= 0 and 0 or bend * 0.5
		if side == 0 then
			armTwist = -armTwist
		end
		angularLimit[0], angularLimit[1], angularLimit[2] = 0.0625, 0.0625, 0.0625
		limbIK(h, BONE_CHEST, shoulder, target, ARM_FRAME, ZERO3, 0.65625, armTwist, wristTurn, changeLimit,
			angularLimit, limit, flags)
	end
end

local function driveRagdoll(h)
	local hands = h.hands
	if h.inventory_anim_flags ~= 0 and hasFlag(h.input_flags, INPUT_THROW) then
		h.throw_pitch = h.input_spine_bend * 8
	end
	local health0, health1 = 1, 1
	if h.arm_health[0] < 100 then
		health0 = h.arm_health[0] * 0.0099999998
	end
	if h.arm_health[1] < 100 then
		health1 = h.arm_health[1] * 0.0099999998
	end
	if h.movement_state == STATE_FALL and 0 > h.trunk_velocity[1] then
		h.jump_pose_angle = 0
	end



	local aiming = (hands[0] ~= nil and hands[0].type.gun) or (hands[1] ~= nil and hands[1].type.gun) or (Bonds.thrower and Bonds.thrower:aiming(h))
	local lean = h.zoom_level == 2 and PI_4 or PI_8
	if hasFlag(h.input_flags, INPUT_AIM) or not aiming then
		lean = 0
	end
	if hands[0] and hands[0].type.leanOther then
		lean = -lean
	end
	if Bonds.thrower and Bonds.thrower:leftGun() then lean = -lean end
	h.drive_aiming = aiming
	h.drive_lean = lean

	driveLowerSpine(h)
	local stomachDamping = driveUpperSpine(h)
	if aiming and not h.seat then
		driveSpineToLookPose(h)
	end
	driveHead(h, stomachDamping)
	local bothHandsEmpty = not hands[0] and not hands[1]
	driveArm(h, 0, health0, bothHandsEmpty)
	driveArm(h, 1, health1, bothHandsEmpty)

	for _, bone in ipairs({BONE_STOMACH, BONE_CHEST, BONE_HEAD, BONE_SHOULDER, BONE_FOREARM, BONE_SHOULDER + 3,
			BONE_FOREARM + 3}) do
		h.bones[bone].bond.has_axis = false
	end
	if h.movement_state == STATE_LIE then
		setJointAxes(h, 0.0078125, 0.03125)
	end
	if h.damage_ticks > 0 then
		local limit = 0.125 - min(h.damage_ticks * 0.016666668, 1) * 0.1171875
		setJointAxes(h, limit, limit * 0.25)
	end
end

local function limitStep(step, limit)
	if not (step >= -limit) then
		return -limit
	end
	if step > limit then
		return limit
	end
	return step
end

local function probeDown(x, y, z, reach)
	return levelRay(v3(x, y + reach, z), v3(x, y - reach, z))
end

local function groundUnderPelvis(h)
	local p = h.bones[BONE_PELVIS].position
	if levelRay(p, v3(p[0], p[1] - 1.75, p[2])) then
		return collisionHit.point[1]
	end
	return p[1]
end

local function feelGroundAhead(h)
	local axes = headingAxes(h.view_yaw)
	local pelvis = h.bones[BONE_PELVIS].position
	local here = groundUnderPelvis(h)
	local lowest, highest, hits = 65536, -65536, 0

	local dx, dy, dz = h.walk_velocity[0], 0, h.walk_velocity[2]
	local speed = sqrt(dz * dz + dx * dx)
	if not (speed >= 0.016666668) then
		local missing = speed - 0.016666668
		dy = axes[7] * missing
		dx = axes[6] * missing + dx
		dz = axes[8] * missing + dz
	end
	local length = sqrt((dy * dy + dx * dx) + dz * dz)
	if length == 0 then
		dx, dy, dz = 0, 0, 0
	else
		local scale = 0.66666669 / length
		dx, dy, dz = dx * scale, dy * scale, dz * scale
	end

	local x, z, height = pelvis[0], pelvis[2], here
	for i = 0, 3 do
		if probeDown(x, height, z, 0.75) then
			if i == 0 then
				h.ground_velocity[0], h.ground_velocity[1], h.ground_velocity[2] = 0, 0, 0
			end
			height = collisionHit.point[1]
			hits = hits + 1
			lowest = min(height, lowest)
			highest = max(height, highest)
		end
		x = x + dx
		z = z + dz
		height = dy + height
	end

	if hits > 0 then
		local rise = highest - here
		local uneven = max(min(abs(highest - lowest), 0.5), min(abs(rise), 0.625))
		h.ground_flat = h.ground_flat + clamp((1 - uneven) - h.ground_flat, -0.03125, 0.03125)
		h.ground_rise = h.ground_rise + clamp(rise - h.ground_rise, -0.03125, 0.03125)
	end
end

local function updateWalkHeight(h)
	local axes = headingAxes(h.view_yaw)
	local pelvis = h.bones[BONE_PELVIS].position
	local heights, hits = {}, 0
	local y = groundUnderPelvis(h)

	local dx = (h.walk_velocity[0] - axes[6] * 0.015625) * 3.75
	local dz = (h.walk_velocity[2] - axes[8] * 0.015625) * 3.75
	local dy = (axes[7] * -0.015625) * 3.75
	local x = pelvis[0] - dx
	local z = pelvis[2] - dz
	y = y - dy
	for _ = 1, 8 do
		if probeDown(x, y, z, 0.75) then
			y = collisionHit.point[1]
			hits = hits + 1
			heights[hits] = y
		end
		x, y, z = x + dx, y + dy, z + dz
	end


	local carried = max(cos(h.view_pitch * 0.5) * h.smoothed_rotation[4], 0.125)
	local low
	if h.zoom_level ~= 0 then
		low = h.walk_amount * 0.46875 + 0.125
	else
		low = h.walk_amount * 0.21875 + 0.34375
	end
	local uphill = min(max(h.ground_rise, 0), 1)
	carried = ((carried + 1) * low) * (1 - uphill) + (h.walk_amount * 0.9375 + 0.3125) * uphill

	local target = h.centre[1]
	if hits > 0 then
		for leg = 0, 1 do
			local l = h.legs[leg]
			if l.state == LEG_PLANTED and h.bones[BONE_FOOT + 3 * leg].ground_bond_count > 0 then
				local limit = l.ground_height + 0.125
				for i = 1, hits do
					if not (limit >= heights[i]) then
						heights[i] = limit
					end
				end
			end
		end
		local sum = 0
		for i = 1, hits do
			sum = sum + heights[i]
		end
		target = sum / hits + carried
	end

	local height = clamp(h.walk_point[1], h.centre[1] - 0.125, h.centre[1] + 0.125)
	h.walk_point[1] = (target - height) * 0.25 + height
end

local function wantedVelocity(h, wanted)
	local speed = 0.050000001
	if h.zoom_level == 0 then
		speed = 0.083333336
	elseif h.zoom_level == 2 then
		speed = 0.025
	end
	local amount = h.jump_charge ~= 0 and 1 or h.walk_amount
	speed = ((speed * amount) * h.ground_flat) * speedScale
	local axes = headingAxes(h.look_yaw_offset + h.view_yaw)

	local back = -h.input_forward
	local x = axes[6] * back + h.input_strafe * axes[0]
	local z = axes[8] * back + h.input_strafe * axes[2]
	local y = axes[7] * back + h.input_strafe * axes[1]
	local length = sqrt((y * y + x * x) + z * z)
	if length == 0 then
		x, y, z = 0, 0, 0
	else
		local scale = 1 / length
		x, y, z = scale * x, scale * y, scale * z
	end

	local across = ((axes[0] * x + axes[1] * y) + axes[2] * z) * -0.25
	x, y, z = across * axes[0] + x, across * axes[1] + y, across * axes[2] + z
	if not (h.input_forward >= 0) then
		local along = ((y * axes[7] + x * axes[6]) + z * axes[8]) * -0.5
		x, y, z = along * axes[6] + x, along * axes[7] + y, along * axes[8] + z
	end
	x, y, z = x * speed, y * speed, z * speed


	length = sqrt((y * y + x * x) + z * z)
	if length > 0.050000001 then
		if gameTick % 16 == 0 and h.stamina > 0 then
			h.stamina = h.stamina - 1
		end
		if h.stamina < 8 then
			local scale = 0.050000001 / length
			x, y, z = scale * x, scale * y, scale * z
		end
	end
	if 0.5 > h.smoothed_rotation[4] then
		x, y, z = 0, 0, 0
	end
	wanted[0], wanted[1], wanted[2] = x, y, z
end

local function updateWalkPoint(h)
	local cv, wv, wp = h.centre_velocity, h.walk_velocity, h.walk_point

	local target = hasFlag(h.input_flags, INPUT_CROUCH) and 0.625 or 1
	local rate = 0.03125
	if h.jump_charge > 0 then
		rate = 0.125
	end
	if not (h.walk_amount >= target - rate) then
		h.walk_amount = h.walk_amount + rate
	elseif h.walk_amount > rate + target then
		h.walk_amount = h.walk_amount - rate
	else
		h.walk_amount = target
	end

	local heading = headingAxes(h.view_yaw)
	feelGroundAhead(h)


	local dx, dy, dz = wv[0] - cv[0], wv[1] - cv[1], wv[2] - cv[2]
	local length = sqrt((dx * dx + dy * dy) + dz * dz)
	if length > 0.033333335 then
		local scale = 0.033333335 / length
		wv[0], wv[1], wv[2] = dx * scale + cv[0], dy * scale + cv[1], dz * scale + cv[2]
	end
	wv[1] = 0


	wp[0], wp[1], wp[2] = wp[0] + h.ground_velocity[0], wp[1] + h.ground_velocity[1], wp[2] + h.ground_velocity[2]
	dx, dz = wp[0] - h.centre[0], wp[2] - h.centre[2]
	local leash = sqrt((wv[0] * wv[0] + wv[1] * wv[1]) + wv[2] * wv[2]) * 1.875 + 0.0625
	length = sqrt(dz * dz + dx * dx)
	if length > leash then
		local scale = leash / length
		wp[0] = dx * scale + h.centre[0]
		wp[2] = dz * scale + h.centre[2]
	end

	local wanted = v3()
	wantedVelocity(h, wanted)


	local lean = h.lean_side
	h.lean_side = lean + limitStep(
		((((wanted[0] * heading[0] + wanted[1] * heading[1]) + wanted[2] * heading[2])
			- ((heading[1] * cv[1] + heading[0] * cv[0]) + heading[2] * cv[2])) - lean) * 0.0625, 0.0078125)
	local forward = ((wanted[0] * heading[6] + wanted[1] * heading[7]) + heading[8] * wanted[2])
		- ((heading[7] * cv[1] + heading[6] * cv[0]) + heading[8] * cv[2])
	if forward > 0 then
		forward = abs(forward) * -0.125
	else
		forward = -abs(forward)
	end
	lean = h.lean_forward
	h.lean_forward = lean + limitStep((forward - lean) * 0.0625, 0.0078125)


	local still = h.stillness
	still = still + limitStep(
		(1 - min(sqrt((wv[0] * wv[0] + wv[1] * wv[1]) + wv[2] * wv[2]) * 120, 1)) - still, 0.03125)
	h.stillness = still
	local keep = 0.96875 - still * 0.5
	local vx, vy, vz = keep * wv[0], keep * wv[1], keep * wv[2]


	dx, dz = wanted[0] - vx, wanted[2] - vz
	local limit = h.movement_state == STATE_GET_UP and 0 or 0.0044444446
	length = sqrt(dz * dz + dx * dx)
	if length > limit then
		local scale = length == 0 and 0 or limit / length
		dx, dz = dx * scale, dz * scale
	end
	wv[0], wv[1], wv[2] = vx + dx, 0, dz + vz
	wp[0], wp[2] = wv[0] + wp[0], wp[2] + wv[2]
	updateWalkHeight(h)
end

local function hipPoint(pelvis, leg, hip)
	local x = HIP_ANCHOR_X[leg]
	hip[0] = pelvis.rotation[0] * x + pelvis.position[0]
	hip[1] = pelvis.rotation[1] * x + pelvis.position[1]
	hip[2] = pelvis.rotation[2] * x + pelvis.position[2]
end

local function anklePoint(h, leg, ankle)
	local shin = h.bones[BONE_SHIN + 3 * leg]
	for k = 0, 2 do
		ankle[k] = SHIN_ANCHOR_Y * shin.rotation[3 + k] + shin.position[k]
	end
end

local function footTurn(h, leg, foot, turn)
	local axes = identity3()
	rotateRows(axes, 0, 1, 0, leg.state == LEG_PLANTED and leg.yaw or h.view_yaw)
	rotateAboutRow(axes, 0, -leg.pitch)
	local target, q = {}, {}
	quatFromMat3(target, axes)
	quatFromMat3(q, foot.rotation)
	if not (((target[3] * q[3] + target[2] * q[2]) + (target[0] * q[0] + target[1] * q[1])) >= 0) then
		q[0], q[1], q[2], q[3] = -q[0], -q[1], -q[2], -q[3]
	end
	q[0], q[1], q[2] = -q[0], -q[1], -q[2]
	local out = {}
	quatMultiply(out, target, q)
	local x, y, z, w = out[0], out[1], out[2], out[3]
	local length = sqrt((x * x + y * y) + z * z)
	if length == 0 then
		x, y, z = 0, 0, 0
	else
		local angle = 2 * acos(clamp(w, -1, 1)) / length
		x, y, z = x * angle, y * angle, z * angle
	end
	if leg.state == LEG_LOOSE then
		x, y, z = 0, 0, 0
	end
	length = sqrt((y * y + x * x) + z * z)
	if length > 0.25 then
		local scale = 0.25 / length
		x, y, z = x * scale, y * scale, z * scale
	end
	turn[0], turn[1], turn[2] = x, y, z
end

local function startJump(h, legIndex)
	local pelvis = h.bones[BONE_PELVIS]
	h.movement_state = STATE_JUMP
	h.legs[legIndex].state = LEG_PLANTED
	h.push_leg = 1 - legIndex
	h.jump_side = h.input_jump_side
	h.jump_forward = h.input_jump_forward
	h.jump_pose_angle = 2.3561945
	h.legs[0].progress = 0
	h.legs[1].progress = 0
	for side = 0, 1 do
		local shin = h.bones[BONE_SHIN + 3 * side]
		local hip = HIP_ANCHOR_X[side]
		for k = 0, 2 do
			h.legs[side].start[k] = (SHIN_ANCHOR_Y * shin.rotation[3 + k] + shin.position[k])
				- (hip * pelvis.rotation[k] + pelvis.position[k])
		end
	end
end

local function footGroundContact(h, legIndex)
	local leg = h.legs[legIndex]
	local foot = h.bones[BONE_FOOT + 3 * legIndex]
	local shin = h.bones[BONE_SHIN + 3 * legIndex]
	local px, py, pz = foot.position[0], foot.position[1], foot.position[2]



	local reach = sin(leg.pitch) * 0.1875 - 0.03125
	local hit = levelRay(v3(px, max(py,foot.previous_position[1]) + 0.5, pz), v3(px, py + reach, pz))
	if 0 > shin.rotation[4] or not hit then
		return
	end
	local ground = collisionHit.point[1]
	leg.ground_height = ground

	local depth = ground - (py + reach)
	if depth >= 0.0625 then
		depth = 0.0625
	end
	local bond = newTickBond()
	bond.kind = 9
	bond.body = foot.body
	bond.distance = depth
	bond.stiffness = 0.5
	bond.damping = 0.5
	bond.nx, bond.ny, bond.nz = 0, 1, 0
	bond.friction = 4
	bond.tvx, bond.tvy, bond.tvz = h.ground_velocity[0], h.ground_velocity[1], h.ground_velocity[2]
	bond.weight0 = foot.ground_bond_strength + foot.ground_bond_strength
	bond.weight1 = 0.1875
	if h.movement_state == STATE_LIE then
		bond.weight0 = 0
	elseif h.movement_state == STATE_JUMP then
		bond.weight1 = 1
	end
	if leg.state == LEG_LOOSE or leg.state == LEG_STEPPING then
		bond.friction = 0
		bond.stiffness = 0.015625
		bond.damping = 0.015625
	end
	if h.movement_state == STATE_LIE then
		bond.friction = 0.1
	end

	local turn = v3()
	footTurn(h, leg, foot, turn)
	local r = foot.rotation
	bond.turnx = (turn[1] * r[3] + turn[0] * r[0]) + turn[2] * r[6]
	bond.turny = (turn[1] * r[4] + turn[0] * r[1]) + turn[2] * r[7]
	bond.turnz = (turn[1] * r[5] + turn[0] * r[2]) + turn[2] * r[8]

	leg.ground_bond = bond
	foot.ground_bond_count = foot.ground_bond_count + 1
	h.on_ground = true
	if h.movement_state ~= STATE_JUMP and h.jump_charge > 0 and not hasFlag(h.input_flags, INPUT_JUMP)
			and leg.state == LEG_PLANTED and leg.contact == 0 then
		startJump(h, legIndex)
	end
end

local function plantFoot(h, leg)
	local l = h.legs[leg]
	local foot = h.bones[BONE_FOOT + 3 * leg]
	l.state = LEG_PLANTED
	l.rest_ticks = 5
	l.planted[0], l.planted[1], l.planted[2] = foot.position[0], 0.03125, foot.position[2]
	l.yaw = atan2(-foot.rotation[6], foot.rotation[8])
end

local function startStep(h, leg, from, to)
	local l = h.legs[leg]
	l.state = LEG_STEPPING
	l.progress = 0
	l.start[0] = to[leg][0] - from[leg][0]
	l.start[1] = to[leg][1] - from[leg][1]
	l.start[2] = to[leg][2] - from[leg][2]
end

local function followFoot(h, leg)
	local l = h.legs[leg]
	local foot = h.bones[BONE_FOOT + 3 * leg]
	if l.state ~= LEG_PLANTED then
		return
	end
	if foot.ground_bond_count == 0 then
		l.contact = 0
	end
	local dx, dz = foot.position[0] - l.planted[0], foot.position[2] - l.planted[2]
	local length = sqrt(dz * dz + dx * dx)
	if length > 0.03125 then
		local scale = 0.03125 / length
		l.planted[0] = dx * scale + l.planted[0]
		l.planted[2] = dz * scale + l.planted[2]
	end
end

local function landStep(h, leg)
	local l = h.legs[leg]
	local foot = h.bones[BONE_FOOT + 3 * leg]
	if l.state ~= LEG_STEPPING or 1 > l.progress then
		return
	end
	l.progress = 1
	local from = v3(foot.position[0], foot.position[1] + 0.375, foot.position[2])
	local to = v3(from[0], from[1] - 0.75, from[2])
	local pelvisHeight = h.bones[BONE_PELVIS].position[1]
	if from[1] > pelvisHeight then
		to[1] = pelvisHeight - 0.375
		from[1] = pelvisHeight
	end
	if levelRay(from, to) then
		l.state = LEG_PLANTED
		l.contact = 0
		l.rest_ticks = 5
		l.planted[0], l.planted[1], l.planted[2] = foot.position[0], 0.03125, foot.position[2]
		l.yaw = h.view_yaw
		if footstepSink then footstepSink(foot.position[0] * SCALE, foot.position[1] * SCALE, foot.position[2] * SCALE) end
	end
end

local function countAirTicks(h, leg)
	local l = h.legs[leg]
	if h.bones[BONE_FOOT + 3 * leg].ground_bond_count == 0 and l.state == LEG_PLANTED then
		l.air_ticks = l.air_ticks + 1
		if l.air_ticks >= 30 then
			l.state = LEG_LOOSE
		end
	else
		l.air_ticks = 0
	end
end

local function countGroundContact(h, leg)
	local l = h.legs[leg]
	if l.state ~= LEG_PLANTED then
		return
	end
	if not (l.contact >= 1) then
		l.contact = l.contact + 0.5
	end
	if h.bones[BONE_FOOT + 3 * leg].ground_bond_count == 0 then
		l.contact = 0
	end
end

local function planSteps(h, from, to)
	local pelvis = h.bones[BONE_PELVIS]
	local foot0, foot1 = h.bones[BONE_FOOT], h.bones[BONE_FOOT + 3]
	local legs, cv = h.legs, h.centre_velocity

	if legs[0].rest_ticks > 0 then
		legs[0].rest_ticks = legs[0].rest_ticks - 1
	end
	if legs[1].rest_ticks > 0 then
		legs[1].rest_ticks = legs[1].rest_ticks - 1
	end


	if legs[0].state == LEG_PLANTED and legs[1].state == LEG_PLANTED then
		local x = (cv[0] * 8 + h.centre[0]) + h.walk_velocity[0] * 16
		local z = (cv[2] * 8 + h.centre[2]) + h.walk_velocity[2] * 16
		local sideX, sideZ = pelvis.rotation[0] * 0.09375, pelvis.rotation[2] * 0.09375
		local backX, backZ = pelvis.rotation[6] * 0.03125, pelvis.rotation[8] * 0.03125
		local ax = foot0.position[0] - ((x - sideX) - backX)
		local az = foot0.position[2] - ((z - sideZ) - backZ)
		local off0 = sqrt(az * az + ax * ax)
		local bx = foot1.position[0] - ((sideX + x) - backX)
		local bz = foot1.position[2] - ((sideZ + z) - backZ)
		local off1 = sqrt(bz * bz + bx * bx)
		local mx = (foot1.position[0] + foot0.position[0]) * 0.5 - h.centre[0]
		local mz = (foot0.position[2] + foot1.position[2]) * 0.5 - h.centre[2]
		local offMiddle = sqrt(mz * mz + mx * mx)
		if off0 > 0.125 or off1 > 0.125 or offMiddle > 0.125 then
			local leg = off1 > off0 and 1 or 0
			if legs[leg].rest_ticks == 0 or legs[1 - leg].rest_ticks ~= 0 then
				startStep(h, leg, from, to)
			end
		end
	end

	followFoot(h, 0)
	followFoot(h, 1)
	landStep(h, 0)
	landStep(h, 1)


	if legs[0].state == LEG_LOOSE and 0.033333335 > cv[1] and foot0.ground_bond_count > 0 then
		plantFoot(h, 0)
	end
	if legs[1].state == LEG_LOOSE and 0.033333335 > cv[1] and foot1.ground_bond_count > 0 then
		plantFoot(h, 1)
	end


	if h.movement_state == STATE_STAND and 0.5 > h.smoothed_rotation[4] then
		h.jump_charge = 0
		legs[0].state = LEG_LOOSE
		legs[1].state = LEG_LOOSE
		if h.on_ground and hasFlag(h.input_flags, INPUT_CROUCH) then
			h.movement_state = STATE_GET_UP
		end
	end

	if legs[0].state == LEG_LOOSE and legs[1].state == LEG_PLANTED and foot1.ground_bond_count > 0 then
		plantFoot(h, 0)
	end
	if legs[1].state == LEG_LOOSE and legs[0].state == LEG_PLANTED and foot0.ground_bond_count > 0 then
		plantFoot(h, 1)
	end


	if h.movement_state == STATE_GET_UP then
		h.jump_charge = 0
		if not hasFlag(h.input_flags, INPUT_CROUCH) then
			legs[0].state = LEG_LOOSE
			legs[1].state = LEG_LOOSE
		else
			local ax, az = foot0.position[0] - h.centre[0], foot0.position[2] - h.centre[2]
			local off0 = sqrt(az * az + ax * ax)
			local bx, bz = foot1.position[0] - h.centre[0], foot1.position[2] - h.centre[2]
			local off1 = sqrt(bz * bz + bx * bx)
			if legs[0].state == LEG_LOOSE and legs[1].state == LEG_LOOSE then
				startStep(h, off0 > off1 and 1 or 0, from, to)
			end
		end
		if 0.5 >= h.smoothed_rotation[4] then
			h.stand_up_ticks = 0
		else
			h.stand_up_ticks = h.stand_up_ticks + 1
			if h.stand_up_ticks >= 10 then
				h.movement_state = STATE_STAND
			end
		end
	end

	countAirTicks(h, 0)
	countAirTicks(h, 1)
	countGroundContact(h, 0)
	countGroundContact(h, 1)
end

local function swingStep(h, leg, hipTarget, axes)
	local l = h.legs[leg]
	local foot = h.bones[BONE_FOOT + 3 * leg]
	local cv, wv = h.centre_velocity, h.walk_velocity
	local sign = leg == 1 and 1 or -1

	if l.progress == 0 then
		local px = cv[0] * 15 + h.centre[0] + sign * axes[0] * 0.0234375
		local py = cv[1] * 15 + h.centre[1] + sign * axes[1] * 0.0234375
		local pz = cv[2] * 15 + h.centre[2] + sign * axes[2] * 0.0234375
		if levelRay(v3(px, py + 0.25, pz), v3(px, py - 1.75, pz)) then
			py = collisionHit.point[1]
		end
		l.landing[0], l.landing[1], l.landing[2] = px, py, pz
	end


	local x = h.centre[0] + sign * axes[0] * 0.0234375 - axes[6] * 0.03125
	local z = h.centre[2] + sign * axes[2] * 0.0234375 - axes[8] * 0.03125
	local leadX, leadZ = wv[0] * 7.5, wv[2] * 7.5
	local length = sqrt((wv[2] * wv[2] + wv[0] * wv[0]) * 56.25)
	if length > 0.1875 then
		local scale = 0.1875 / length
		leadX, leadZ = leadX * scale, leadZ * scale
	end
	x, z = leadX + x, leadZ + z
	local lagX, lagZ = cv[0] - wv[0], cv[2] - wv[2]
	length = sqrt(lagZ * lagZ + lagX * lagX)
	if length > 0.015625 then
		local scale = 0.015625 / length
		lagX, lagZ = lagX * scale, lagZ * scale
	end
	x, z = lagX * 7.5 + x, lagZ * 7.5 + z


	local ahead = (1 - l.progress) * 11.25
	local fx, fy, fz = wv[0] * ahead + x, wv[1] * ahead + hipTarget[1], wv[2] * ahead + z
	local ground
	if levelRay(v3(fx, fy, fz), v3(fx, fy - 1.75, fz)) then
		ground = collisionHit.point[1]
	else
		ground = foot.position[1]
	end
	local footHeight = min(foot.position[1], h.bones[BONE_PELVIS].position[1])
	if levelRay(v3(foot.position[0], footHeight + 0.25, foot.position[2]),
			v3(foot.position[0], footHeight - 0.25, foot.position[2]))
			and not (ground >= collisionHit.point[1]) then
		ground = collisionHit.point[1]
	end

	local ex = x - hipTarget[0]
	local ez = z - hipTarget[2]
	local ey = (ground - sin(l.pitch) * 0.25) - hipTarget[1]
	l.progress = l.progress + 0.050000001
	if h.movement_state ~= STATE_GET_UP then
		l.progress = l.progress + 0.033333335
	end
	local t = min(l.progress, 1)
	local u = 1 - t


	local speed = clamp(sqrt((wv[0] * wv[0] + wv[1] * wv[1]) + wv[2] * wv[2]) * 7.5 - 0.125, 0, 1)
	local kick = speed * 0.125
	local s = l.start
	local sx = ((((kick * axes[6] + s[0]) * 3) * (u * u) + (((ex * 3) * u + ex * t) * t)) * t) + ((s[0] * u) * (u * u))
	local sy = (((((speed * 0.375 + s[1]) + kick * axes[7]) * 3) * (u * u)
		+ ((((speed * 0.5 + ey) * 3) * u + ey * t) * t)) * t) + ((u * s[1]) * (u * u))
	local sz = (((((ez * 3) * u + ez * t) * t) + ((kick * axes[8] + s[2]) * 3) * (u * u)) * t) + ((u * s[2]) * (u * u))
	l.swing[0] = (sx + hipTarget[0]) + h.step_offset[0]
	l.swing[1] = h.step_offset[1] + (sy + hipTarget[1])
	l.swing[2] = h.step_offset[2] + (sz + hipTarget[2])
	l.contact = 0
end

local LIE_LIMITS = {[0] = 0.0625, 0.0625, 0.0625}

local function lieLegs(h)
	local pelvis = h.bones[BONE_PELVIS]
	local r = pelvis.rotation
	local ankles, hips = {[0] = v3(), v3()}, {[0] = v3(), v3()}
	h.standing = false
	h.legs[0].state = LEG_LOOSE
	h.legs[1].state = LEG_LOOSE
	for leg = 0, 1 do
		anklePoint(h, leg, ankles[leg])
		hipPoint(pelvis, leg, hips[leg])
	end
	updateCentre(h)

	local v = h.trunk_velocity
	for leg = 0, 1 do
		local l = h.legs[leg]
		l.previous_pitch = l.pitch
		l.pitch = 0
		local hx, hy, hz = v[0] + hips[leg][0], v[1] + hips[leg][1], v[2] + hips[leg][2]
		local x, y, z = v[0] + pelvis.position[0], v[1] + pelvis.position[1], v[2] + pelvis.position[2]
		local spread
		if leg == 1 then
			spread = max(r[1] * -0.5, 0)
			y = (r[1] * 0.25 + y) + spread * r[1]
			z = r[2] * 0.25 + z
			x = (r[0] * 0.25 + x) + spread * r[0]
		else
			spread = -max(r[1] * 0.5, 0)
			x = (x - r[0] * 0.25) + r[0] * spread
			y = (y - r[1] * 0.25) + r[1] * spread
			z = z - r[2] * 0.25
		end
		local tx = ((x - r[6] * 0.25) - r[3] * 0.75) - r[6] * 0.125
		local ty = ((y - r[7] * 0.25) - r[4] * 0.75) - r[7] * 0.125
		local tz = (((z + spread * r[2]) - r[8] * 0.25) - r[5] * 0.75) - r[8] * 0.125

		if not h.on_ground then
			local ax, ay, az = v[0] + ankles[leg][0], v[1] + ankles[leg][1], v[2] + ankles[leg][2]
			tx = (tx - ax) * 0.015625 + ax
			ty = (ty - ay) * 0.015625 + ay
			tz = (tz - az) * 0.015625 + az
		end
		local thigh = BONE_THIGH + 3 * leg
		limbIK(h, BONE_PELVIS, thigh, v3(tx - hx, ty - hy, tz - hz), r, ZERO3, 1, 0, {[0] = 0, 0, 0, 1},
			0.01840777, LIE_LIMITS, 0.78539819, 24)
		setJointAxis(h, BONE_PELVIS, thigh, 0.0009765625)
		setJointAxis(h, thigh, thigh + 1, 0.0009765625)
	end
end

local SIT_LIMITS = {[0] = 0.015625, 0.015625, 0.015625}
local function sitLegs(h)
	local pelvis = h.bones[BONE_PELVIS]
	local r, p = pelvis.rotation, pelvis.position
	local hips = {[0] = v3(), v3()}
	h.standing = false
	h.legs[0].state = LEG_LOOSE
	h.legs[1].state = LEG_LOOSE
	hipPoint(pelvis, 0, hips[0])
	hipPoint(pelvis, 1, hips[1])
	updateCentre(h)
	for leg = 0, 1 do
		local l = h.legs[leg]
		l.previous_pitch = l.pitch
		l.pitch = 0
		local side = leg == 1 and 0.3125 or -0.3125
		local x, y, z = r[0] * side + p[0], r[1] * side + p[1], r[2] * side + p[2]
		local target = v3(((x - r[6] * 0.75) - r[3] * 0.125) - hips[leg][0],
			((y - r[7] * 0.75) - r[4] * 0.125) - hips[leg][1],
			((z - r[8] * 0.75) - r[5] * 0.125) - hips[leg][2])
		limbIK(h, BONE_PELVIS, BONE_THIGH + 3 * leg, target, r, ZERO3, 1, 0, {[0] = 0, 0, 0, 1},
			0.01840777, SIT_LIMITS, 0.78539819, 0)
	end
end

local function holdInSeat(h, seat)
	local b, car = h.bones[BONE_PELVIS].body, seat.body
	local r = car.R



	local old = seat.frame
	if old then
		local a = old.R
		local function turn(x,y,z)
			local u,v,w=x*a[0]+y*a[1]+z*a[2],x*a[3]+y*a[4]+z*a[5],x*a[6]+y*a[7]+z*a[8]
			return u*r[0]+v*r[3]+w*r[6],u*r[1]+v*r[4]+w*r[7],u*r[2]+v*r[5]+w*r[8]
		end
		for i=0,15 do
			local bone=h.bones[i];local body=bone.body
			local x,y,z=turn(body.px-old.px,body.py-old.py,body.pz-old.pz)
			body.px,body.py,body.pz=car.px+x,car.py+y,car.pz+z
			local vx,vy,vz=turn(body.vx-(seat.vx or 0),body.vy-(seat.vy or 0),body.vz-(seat.vz or 0))
			body.vx,body.vy,body.vz=vx+car.vx,vy+car.vy,vz+car.vz
			for axis=0,6,3 do
				body.R[axis],body.R[axis+1],body.R[axis+2]=turn(body.R[axis],body.R[axis+1],body.R[axis+2])
			end
			body.Lx,body.Ly,body.Lz=turn(body.Lx or 0,body.Ly or 0,body.Lz or 0)
			if bone.position then
				local p,q=bone.position,bone.previous_position
				local x,y,z=turn(p[0]-old.px,p[1]-old.py,p[2]-old.pz)
				p[0],p[1],p[2]=car.px+x,car.py+y,car.pz+z
				x,y,z=turn(q[0]-old.px,q[1]-old.py,q[2]-old.pz)
				q[0],q[1],q[2]=car.px+x,car.py+y,car.pz+z
				copy9(bone.rotation,body.R)
			end
		end
	else
		old={R={}};seat.frame=old
	end
	old.px,old.py,old.pz=car.px,car.py,car.pz;copy9(old.R,r)
	seat.vx,seat.vy,seat.vz=car.vx,car.vy,car.vz
	local x = seat.x * r[0] + seat.y * r[3] + seat.z * r[6]
	local y = seat.x * r[1] + seat.y * r[4] + seat.z * r[7]
	local z = seat.x * r[2] + seat.y * r[5] + seat.z * r[8]
	b.px, b.py, b.pz = car.px + x, car.py + y, car.pz + z
	copy9(b.R, r)
	b.vx, b.vy, b.vz = car.vx + car.wz * y - car.wy * z,
		car.vy + car.wx * z - car.wz * x, car.vz + car.wy * x - car.wx * y
	b.wx, b.wy, b.wz = car.wx, car.wy, car.wz
	b.Lx, b.Ly, b.Lz = car.Lx or 0, car.Ly or 0, car.Lz or 0
	b.settled = true
end
Bonds.holdInSeat = holdInSeat

local function balanceOnLeg(h, leg, target, turn, hip, foot, wantedCentre, wantedRotation, share)
	local gain = 3
	local changeLimit = 0.125
	local turnChangeLimit = 0.09375
	local turnLimit = 0.25
	local damping = 0.5
	local r = h.smoothed_rotation
	local cv, wv = h.centre_velocity, h.walk_velocity

	if h.damage_ticks > 0 then
		local weak = 1 - min(h.damage_ticks * 0.033333335, 1)
		changeLimit = changeLimit * weak
		turnChangeLimit = turnChangeLimit * weak
		turnLimit = weak * 0.25
	end


	local dx, dy, dz = hip[0] - foot[0], hip[1] - foot[1], hip[2] - foot[2]
	local length = sqrt((dy * dy + dx * dx) + dz * dz)
	local towardX, towardZ = 0, 0
	if length ~= 0 then
		towardX, towardZ = dx / length, dz / length
	end
	local vx = ((wantedCentre[0] - h.centre[0]) - towardX * 0.32666668) * 0.375 - (cv[0] - wv[0]) * damping
	local vz = ((wantedCentre[2] - h.centre[2]) - towardZ * 0.32666668) * 0.375 - (cv[2] - wv[2]) * damping
	length = sqrt(vx * vx + vz * vz)
	if length > 0.25 then
		local scale = 0.25 / length
		vx, vz = vx * scale, vz * scale
	end
	local vy = clamp((wantedCentre[1] - h.centre[1]) * 0.375 - (cv[1] - wv[1]) * damping, -0.125, 0.125)


	vz = vz - cv[2]
	vx = vx - cv[0]
	vy = vy - cv[1]
	length = sqrt(vx * vx + vz * vz)
	if length > changeLimit then
		local scale = changeLimit / length
		vx, vz = vx * scale, vz * scale
	end
	local lift = clamp(vy, 0, 0.125)
	local pushX, pushY, pushZ = vx * gain, lift * gain, vz * gain


	local q, kept, turnQ = {}, {}, {}
	quatFromMat3(q, wantedRotation)
	quatFromMat3(kept, r)
	if not (((q[3] * kept[3] + q[2] * kept[2]) + (q[0] * kept[0] + q[1] * kept[1])) >= 0) then
		kept[0], kept[1], kept[2], kept[3] = -kept[0], -kept[1], -kept[2], -kept[3]
	end
	kept[0], kept[1], kept[2] = -kept[0], -kept[1], -kept[2]
	quatMultiply(turnQ, kept, q)
	local ax, ay, az = turnQ[0], turnQ[1], turnQ[2]
	length = sqrt((ay * ay + ax * ax) + az * az)
	if length == 0 then
		ax, ay, az = 0, 0, 0
	else
		local angle = 2 * acos(clamp(turnQ[3], -1, 1)) / length
		ax, ay, az = ax * angle, ay * angle, az * angle
	end
	length = sqrt((ax * ax + ay * ay) + az * az)
	if length > turnLimit then
		local scale = turnLimit / length
		ax, ay, az = ax * scale, ay * scale, az * scale
	end

	local w = h.smoothed_angular_velocity
	ax = (ax + w[0] * -2) - w[0]
	ay = (ay + w[1] * -2) - w[1]
	az = (az + w[2] * -2) - w[2]
	length = sqrt((ay * ay + ax * ax) + az * az)
	if length > turnChangeLimit then
		local scale = turnChangeLimit / length
		ax, ay, az = ax * scale, ay * scale, az * scale
	end
	turn[0] = (ax * gain) * share
	turn[2] = (az * gain) * share
	turn[1] = (ay * gain) * share


	pushX = pushX * share
	pushZ = pushZ * share
	if h.bones[BONE_FOOT + 3 * leg].ground_bond_count == 0 then
		pushY = pushY * (share * 0.75 + 0.25)
	end


	local rx, ry, rz = hip[0] - h.centre[0], hip[1] - h.centre[1], hip[2] - h.centre[2]
	local x = pushX + (hip[0] + wv[0])
	local y = pushY + (hip[1] + wv[1])
	local z = (wv[2] + hip[2]) + pushZ
	target[0] = (turn[2] * ry - turn[1] * rz) + x
	target[2] = (turn[1] * rx - turn[0] * ry) + z
	target[1] = (turn[0] * rz - turn[2] * rx) + y


	local cx = rz * pushY - ry * pushZ
	local cy = rx * pushZ - rz * pushX
	local cz = ry * pushX - rx * pushY
	local hipTurn = h.hip_turn[leg]
	local along = -((cy * r[1] + cx * r[0]) + cz * r[2])
	hipTurn[0], hipTurn[1], hipTurn[2] = along * r[0], along * r[1], along * r[2]
	along = ((cy * r[4] + cx * r[3]) + cz * r[5]) * -0.25
	hipTurn[0], hipTurn[1], hipTurn[2] = r[3] * along + hipTurn[0], along * r[4] + hipTurn[1], along * r[5] + hipTurn[2]
	along = ((cy * r[7] + r[6] * cx) + cz * r[8]) * -2
	hipTurn[0], hipTurn[1], hipTurn[2] = r[6] * along + hipTurn[0], along * r[7] + hipTurn[1], along * r[8] + hipTurn[2]
end

local function yawFromPelvis(h)
	local r = h.bones[BONE_PELVIS].rotation
	if not (0.875 >= r[4]) then
		h.view_yaw = atan2(-r[6], r[8])
	end
end

local function updateState(h)
	if h.movement_state == STATE_STAND then
		h.standing = true
		if h.legs[0].state == LEG_LOOSE and h.legs[1].state == LEG_LOOSE then
			if not h.on_ground or not (0.016666668 >= h.centre_velocity[1]) then
				yawFromPelvis(h)
				h.movement_state = STATE_FALL
				h.jump_charge = 0
			end
			h.standing = false
		end
	elseif h.movement_state == STATE_FALL then
		h.standing = false
		h.jump_charge = 0
		yawFromPelvis(h)
		if h.on_ground and 0.016666668 > h.centre_velocity[1] then
			h.movement_state = STATE_STAND
			h.standing = true
		end
	end
end

local function setGroundGrip(h, leg, fast)
	local l = h.legs[leg]
	if h.bones[BONE_FOOT + 3 * leg].ground_bond_count == 0 or not l.ground_bond then
		return
	end
	local bond = l.ground_bond
	bond.friction = 0.89999998
	bond.stiffness = 0.5
	bond.damping = 0.5
	if l.state == LEG_LOOSE then
		bond.friction = 0
		bond.weight0 = 0
	elseif l.state == LEG_STEPPING then
		local slow = 1 - fast
		bond.friction = 0
		bond.weight0 = 0
		slow = slow * slow
		slow = slow * slow
		local soft = 0.5 - (1 - slow) * 0.4375
		bond.stiffness = soft
		bond.damping = soft
	end
end

local function standLegs(h)
	local pelvis = h.bones[BONE_PELVIS]
	local legHealth = {[0] = 1, 1}
	local hips, ankles = {[0] = v3(), v3()}, {[0] = v3(), v3()}
	local targets, turns = {[0] = v3(), v3()}, {[0] = v3(), v3()}
	local share = {}
	local tv = h.trunk_velocity

	local fast = clamp(sqrt((tv[0] * tv[0] + tv[1] * tv[1]) + tv[2] * tv[2]) * 60 - 0.5, 0, 1)
	for leg = 0, 1 do
		if h.leg_health[leg] < 100 then
			legHealth[leg] = h.leg_health[leg] * 0.0099999998
		end
	end

	updateState(h)

	for k = 0, 2 do
		h.hip_turn[0][k] = 0
		h.hip_turn[1][k] = 0
	end
	for leg = 0, 1 do
		anklePoint(h, leg, ankles[leg])
		hipPoint(pelvis, leg, hips[leg])
	end
	local axes = headingAxes(h.view_yaw)
	local wanted = headingAxes(h.view_yaw)


	local sum = (axes[8] * (hips[0][2] - ankles[0][2])) * -2 - (axes[6] * (hips[0][0] - ankles[0][0])) * 2
	do
		local alongX = axes[6] * (hips[1][0] - ankles[1][0])
		local alongZ = axes[8] * (hips[1][2] - ankles[1][2])
		sum = ((sum + alongZ) + alongZ) + (alongX + alongX)
	end
	if h.legs[0].state == LEG_LOOSE and h.legs[1].state == LEG_LOOSE then
		sum = sum * 0.5
	end
	h.stride_lean = (sum - h.stride_lean) * 0.5 + h.stride_lean

	updateWalkPoint(h)


	rotateAboutRow(wanted, 2, clamp(h.lean_side * 7.5, -PI_4, PI_4))
	rotateAboutRow(wanted, 0, clamp(h.lean_forward * -7.5, -PI_4, PI_4))

	h.walk_velocity[1] = 0
	for k = 0, 2 do
		h.step_offset[k] = h.walk_velocity[k] + h.ground_velocity[k]
	end

	planSteps(h, hips, ankles)


	sum = h.legs[1].contact + h.legs[0].contact
	if sum > 1 then
		share[0], share[1] = h.legs[0].contact / sum, h.legs[1].contact / sum
	else
		share[0], share[1] = h.legs[0].contact, h.legs[1].contact
	end
	for leg = 0, 1 do
		for k = 0, 2 do
			targets[leg][k] = hips[leg][k] + tv[k]
			turns[leg][k] = 0
		end
		if h.legs[leg].state == LEG_PLANTED then
			balanceOnLeg(h, leg, targets[leg], turns[leg], hips[leg], ankles[leg], h.walk_point, wanted, share[leg])
		end
		if h.legs[leg].state == LEG_STEPPING then
			swingStep(h, leg, hips[leg], axes)
		end
	end


	local q, kept, turnQ = {}, {}, {}
	quatFromMat3(q, wanted)
	quatFromMat3(kept, pelvis.rotation)
	if not (((q[3] * kept[3] + q[2] * kept[2]) + (q[0] * kept[0] + q[1] * kept[1])) >= 0) then
		kept[0], kept[1], kept[2], kept[3] = -kept[0], -kept[1], -kept[2], -kept[3]
	end
	kept[0], kept[1], kept[2] = -kept[0], -kept[1], -kept[2]
	quatMultiply(turnQ, kept, q)
	local x, y, z = turnQ[0], turnQ[1], turnQ[2]
	local length = sqrt((y * y + x * x) + z * z)
	if length == 0 then
		x, y, z = 0, 0, 0
	else
		local scale = 1 / length
		x, y, z = x * scale, y * scale, z * scale
	end
	local angle = 2 * acos(clamp(turnQ[3], -1, 1))
	local upright = max(min(h.smoothed_rotation[4] + 0.5, 1), 0.125) * 0.25
	x, y, z = (x * angle) * upright, (y * angle) * upright, (z * angle) * upright
	copy9(wanted, pelvis.rotation)
	length = sqrt((y * y + x * x) + z * z)
	if length > 0.000015258789 then
		local scale = 1 / length
		rotateRows(wanted, x * scale, y * scale, z * scale, length)
	end
	local row1x, row1y, row1z = wanted[3], wanted[4], wanted[5]

	for leg = 0, 1 do
		local l = h.legs[leg]
		local foot = h.bones[BONE_FOOT + 3 * leg]
		local footQ, wantedQ, wristTurn = {}, {}, {}

		setGroundGrip(h, leg, fast)


		axes = headingAxes(l.state == LEG_PLANTED and l.yaw or h.view_yaw)
		rotateAboutRow(axes, 0, -l.pitch)
		local state = l.state
		quatFromMat3(footQ, axes)
		quatFromMat3(wantedQ, wanted)

		if not (((wantedQ[3] * footQ[3] + wantedQ[2] * footQ[2]) + (wantedQ[0] * footQ[0] + wantedQ[1] * footQ[1])) >= 0) then
			footQ[0], footQ[1], footQ[2], footQ[3] = -footQ[0], -footQ[1], -footQ[2], -footQ[3]
		end
		footQ[0], footQ[1], footQ[2] = -footQ[0], -footQ[1], -footQ[2]
		quatMultiply(wristTurn, wantedQ, footQ)
		if state == LEG_LOOSE or state == LEG_STATE_8 then
			wristTurn[0], wristTurn[1], wristTurn[2], wristTurn[3] = 0, 0, 0, 1
		end


		local tx, ty, tz = hips[leg][0] + tv[0], hips[leg][1] + tv[1], hips[leg][2] + tv[2]
		if state == LEG_PLANTED then
			tx, ty, tz = targets[leg][0], targets[leg][1], targets[leg][2]
		else
			turns[leg][0], turns[leg][1], turns[leg][2] = 0, 0, 0
		end


		local fx, fy, fz = ankles[leg][0], ankles[leg][1], ankles[leg][2]
		if state == LEG_PLANTED then

			local bx = foot.position[0] - foot.rotation[6] * 0.09375
			local by = foot.position[1] - foot.rotation[7] * 0.09375
			local bz = foot.position[2] - foot.rotation[8] * 0.09375
			if levelRay(v3(foot.position[0], foot.position[1] + 0.25, foot.position[2]),
					v3(foot.position[0], foot.position[1] - 0.25, foot.position[2])) then
				by = collisionHit.point[1] + 0.03125
			end
			if foot.ground_bond_count > 0 then
				by = l.ground_height + 0.03125
			end
			local forward = 0.09375 - SHIN_OFFSET
			fx = axes[6] * forward + bx
			fy = axes[7] * forward + by
			fz = axes[8] * forward + bz
		end
		if state == LEG_STEPPING then
			fx, fy, fz = l.swing[0], l.swing[1], l.swing[2]
		elseif state == LEG_STATE_8 then
			fx, fy, fz = tx - row1x * 0.25, ty - row1y * 0.25, tz - row1z * 0.25
		elseif state == LEG_LOOSE then

			local hang = h.walk_amount * -0.75
			local r = pelvis.rotation
			fy = r[4] * hang + ty
			fz = r[5] * hang + tz
			fx = r[3] * hang + tx
			if h.on_ground then
				fy = fy - max(h.smoothed_rotation[4], 0) * 0.25
			elseif 0.016666668 > tv[1] then
				local level = max(r[4], 0)
				local vz = level * h.centre_velocity[2]
				local vx = level * h.centre_velocity[0]
				if leg == h.push_leg then
					fx = vx * 6 + fx
					fz = vz * 6 + fz
				else
					fx = (fx - vx * 3) + r[3] * 0.25
					fy = r[4] * 0.25 + fy
					fz = (fz - vz * 3) + r[5] * 0.25
				end
			end
		end
		local target = v3(fx - tx, fy - ty, fz - tz)


		local health = legHealth[leg]
		local changeLimit = health * 0.22089323 + 0.073631078
		local flags = state ~= LEG_LOOSE and 2 or 3
		if not (health >= 1) then
			flags = flags + 0x10
		end
		local angularLimit = {[0] = 0, 0, 0}
		if state == LEG_LOOSE then
			local limit = 0.875 > pelvis.rotation[4] and 0.0078125 or 0.0625
			angularLimit[0], angularLimit[1], angularLimit[2] = limit, limit, limit
		end
		if h.damage_ticks > 0 then
			local loose = 0.125 - min(h.damage_ticks * 0.033333335, 1) * 0.09375
			angularLimit[0], angularLimit[1], angularLimit[2] = loose, loose, loose
		end
		limbIK(h, BONE_PELVIS, BONE_THIGH + 3 * leg, target, pelvis.rotation, turns[leg], 1, 0, wristTurn,
			changeLimit, angularLimit, 0.78539819, flags)
	end
end

local JUMP_LIMITS = {[0] = 0.0625, 0.0625, 0.0625}

local function launchBodies(h, vx, vy, vz, spin)
	local cx, cy, cz, total = 0, 0, 0, 0
	for i = 0, 15 do
		local b = h.bones[i]
		cx = cx + b.mass * b.position[0]
		cy = cy + b.mass * b.position[1]
		cz = cz + b.mass * b.position[2]
		total = total + b.mass
	end
	cx, cy, cz = cx / total, cy / total, cz / total
	for i = 0, 15 do
		local body = h.bones[i].body
		local rx, ry, rz = body.px - cx, body.py - cy, body.pz - cz
		body.vx = (spin[2] * ry - spin[1] * rz) + vx
		body.vy = (spin[0] * rz - spin[2] * rx) + vy
		body.vz = (spin[1] * rx - spin[0] * ry) + vz
		body.wx, body.wy, body.wz = spin[0], spin[1], spin[2]
		local r = body.R
		local inertia = {[0] = body.ix, body.iy, body.iz}
		local lx, ly, lz = 0, 0, 0
		for row = 0, 2 do
			local about = ((spin[1] * r[row * 3 + 1] + r[row * 3] * spin[0]) + spin[2] * r[row * 3 + 2]) * inertia[row]
			lx = lx + r[row * 3] * about
			ly = ly + r[row * 3 + 1] * about
			lz = lz + r[row * 3 + 2] * about
		end
		body.Lx, body.Ly, body.Lz = lx, ly, lz
	end
end

local function launchJump(h)
	local pelvis = h.bones[BONE_PELVIS]
	local v = h.trunk_velocity
	local r = h.smoothed_rotation
	local ankles, hips = {[0] = v3(), v3()}, {[0] = v3(), v3()}
	local targets, turns = {[0] = v3(), v3()}, {[0] = v3(), v3()}
	local wp, wv = h.walk_point, h.walk_velocity

	for leg = 0, 1 do
		anklePoint(h, leg, ankles[leg])
		hipPoint(pelvis, leg, hips[leg])
	end
	local axes = headingAxes(h.view_yaw)
	local wanted = headingAxes(h.view_yaw)


	wv[1] = 0
	wp[0], wp[2] = wv[0] + wp[0], wp[2] + wv[2]
	local reach = h.walk_amount * 0.875 + wanted[4] * 0.25
	wp[1] = h.centre[1]
	if levelRay(h.centre, v3(h.centre[0], h.centre[1] - 1.75, h.centre[2])) then
		wp[1] = collisionHit.point[1] + reach
	end


	local push = v3()
	for k = 0, 2 do
		push[k] = ((wp[k] - h.centre[k]) * 0.375 - (v[k] - wv[k]) * 0.75) - v[k]
	end
	push[1] = clamp(push[1], 0, 0.5)

	h.legs[0].progress = min(h.legs[0].progress + 0.125, 1)

	for leg = 0, 1 do
		for k = 0, 2 do
			targets[leg][k] = (v[k] + hips[leg][k]) + push[k] * 3
		end
	end


	local q, kept, turnQ = {}, {}, {}
	quatFromMat3(q, wanted)
	quatFromMat3(kept, r)
	if not (((q[3] * kept[3] + q[2] * kept[2]) + (q[0] * kept[0] + q[1] * kept[1])) >= 0) then
		kept[0], kept[1], kept[2], kept[3] = -kept[0], -kept[1], -kept[2], -kept[3]
	end
	kept[0], kept[1], kept[2] = -kept[0], -kept[1], -kept[2]
	quatMultiply(turnQ, kept, q)
	local x, y, z = turnQ[0], turnQ[1], turnQ[2]
	local length = sqrt((y * y + x * x) + z * z)
	if length == 0 then
		x, y, z = 0, 0, 0
	else
		x, y, z = x / length, y / length, z / length
	end
	local angle = 2 * acos(clamp(turnQ[3], -1, 1))
	local w = h.smoothed_angular_velocity
	local wx, wy, wz = w[0], w[1], w[2]
	x = ((x * angle) * 0.375 - wx * 0.75) - wx
	y = ((y * angle) * 0.375 - wy * 0.75) - wy
	z = ((z * angle) * 0.375 - wz * 0.75) - wz
	length = sqrt((y * y + x * x) + z * z)
	if length > 0.25 then
		local scale = 0.25 / length
		x, y, z = x * scale, y * scale, z * scale
	end
	copy9(wanted, pelvis.rotation)
	do
		local ex, ey, ez = x + wx, y + wy, z + wz
		length = sqrt((ey * ey + ex * ex) + ez * ez)
		if length > 0.000015258789 then
			rotateRows(wanted, ex / length, ey / length, ez / length, length)
		end
	end
	local turn = v3(x * 3, y * 3, z * 3)


	for leg = 0, 1 do
		local ax, ay, az = hips[leg][0] - h.centre[0], hips[leg][1] - h.centre[1], hips[leg][2] - h.centre[2]
		targets[leg][0] = (ay * turn[2] - az * turn[1]) + targets[leg][0]
		targets[leg][1] = targets[leg][1] + (az * turn[0] - ax * turn[2])
		targets[leg][2] = targets[leg][2] + (ax * turn[1] - ay * turn[0])

		local cx = push[1] * az - push[2] * ay
		local cy = push[2] * ax - push[0] * az
		local cz = push[0] * ay - push[1] * ax
		local k0 = ((cy * r[1] + cx * r[0]) + cz * r[2]) * -3
		local k1 = ((cy * r[4] + cx * r[3]) + cz * r[5]) * -0.75
		local k2 = ((cy * r[7] + cx * r[6]) + cz * r[8]) * -6
		turns[leg][0] = (k2 * r[6] + k1 * r[3]) + (k0 * r[0] + turn[0])
		turns[leg][2] = (k2 * r[8] + k1 * r[5]) + (k0 * r[2] + turn[2])
		turns[leg][1] = (k2 * r[7] + k1 * r[4]) + (k0 * r[1] + turn[1])
	end

	for leg = 0, 1 do
		local l = h.legs[leg]
		local foot = h.bones[BONE_FOOT + 3 * leg]
		local target = v3()
		local changeLimit

		if (l.state == LEG_PLANTED and foot.ground_bond_count == 0) or not (1 > h.legs[0].progress) then
			for k = 0, 2 do
				targets[leg][k] = hips[leg][k] + v[k]
				turns[leg][k] = 0
			end
		end

		local box = headingAxes(h.view_yaw)
		rotateAboutRow(box, 0, -l.pitch)
		multiplyTransposed(box, box, pelvis.rotation)
		local wristTurn = {}
		quatFromMat3(wristTurn, box)

		local state = l.state
		local progress = h.legs[0].progress
		if state == LEG_PLANTED then

			for k = 0, 2 do
				target[k] = ankles[leg][k] - targets[leg][k]
			end
			changeLimit = 0.29452431
			if foot.ground_bond_count == 0 then
				for k = 0, 2 do
					target[k] = ankles[leg][k] - hips[leg][k]
					turns[leg][k] = 0
				end
			end
		else

			local drawn = min(progress, 1)
			turns[leg][0], turns[leg][1], turns[leg][2] = 0, 0, 0
			changeLimit = 1.1780972
			target[0] = l.start[0] - l.start[0] * drawn
			target[2] = l.start[2] - l.start[2] * drawn
			target[1] = (-0.375 - l.start[1]) * drawn + l.start[1]
		end
		if progress >= 1 then
			changeLimit = 0
		end
		limbIK(h, BONE_PELVIS, BONE_THIGH + 3 * leg, target, wanted, turns[leg], 1, 0, wristTurn, changeLimit,
			JUMP_LIMITS, 0.78539819, (state == LEG_PLANTED and 1 or 0) + 1)
	end


	h.push_leg = h.legs[0].state == LEG_PLANTED and 1 or 0
	h.movement_state = STATE_FALL
	h.legs[0].state = LEG_LOOSE
	h.legs[1].state = LEG_LOOSE
	local side = clamp(h.jump_side, -0.5, 0.5) * 0.125
	local forward = clamp(h.jump_forward, -0.75, 0.75) * 0.125
	local spin = v3(
		forward * axes[3] + side * axes[0],
		forward * axes[4] + side * axes[1],
		forward * axes[5] + side * axes[2])


	local speed
	if h.jump_charge < 8 then
		speed = 0.033333335
	elseif h.jump_charge < 16 then
		speed = 0.050000001
	elseif h.jump_charge < 24 then
		speed = 0.06666667
	else
		speed = 0.083333336
	end
	speed = speed * jumpScale
	local lift = speed - v[1]
	launchBodies(h, v[0], lift + v[1], v[2], spin)
	h.trunk_velocity[1] = lift * 3 + h.trunk_velocity[1]
	h.jump_charge = 0
	h.jump_pose_angle = 1.5707964
end

local function boneMeetsLevel(h, bone)
	if bone == 12 or bone == 15 then
		return false
	end
	if bone == 11 or bone == 14 then
		return h.movement_state == STATE_LIE or h.old_health <= 0 or h.health < 50
	end
	return true
end

local function collideLevel(h)
	gatherBoxes(h.bounds_min, h.bounds_max)
	if nearBoxCount == 0 then
		return
	end
	for i = 0, 15 do
		if boneMeetsLevel(h, i) then
			local bone = h.bones[i]
			local radius = SKELETON[i].radius
			local a, b = bone.segment0, bone.segment1
			local nearest = radius
			local hx, hy, hz, nx, ny, nz
			for sample = 0, 2 do
				local t = sample * 0.5
				local px = a[0] + (b[0] - a[0]) * t
				local py = a[1] + (b[1] - a[1]) * t
				local pz = a[2] + (b[2] - a[2]) * t
				for n = 1, nearBoxCount do
					local distance, cx, cy, cz, ux, uy, uz = boxDistance(nearBoxes[n], px, py, pz)
					if distance < nearest then
						nearest = distance
						hx, hy, hz, nx, ny, nz = cx, cy, cz, ux, uy, uz
					end
				end
			end
			if hx then
				local body = bone.body
				addWorldContact(body, hx - body.px, hy - body.py, hz - body.pz, nx, ny, nz,
					radius - nearest, 0.4, 0.03125, 0.0625)
			end
		end
	end
end

function Bonds.supportHumanFloor(h)
	if h.seat then return end
	local pelvis=h.bones[BONE_PELVIS].body
	local feet=h.old_health>0 and h.health>=50 and h.movement_state~=STATE_LIE and pelvis.vy>=-.2
	local lift,landed,hitPart=0
	for i=0,15 do
		local foot=feet and (i==BONE_FOOT or i==BONE_FOOT+3)
		if foot or i==BONE_PELVIS or i==BONE_CHEST or i==BONE_HEAD then
			local bone=h.bones[i]
			local bottom=foot and bone.position[1]-.03125 or min(bone.segment0[1],bone.segment1[1])-SKELETON[i].radius
			local previous=bottom+bone.previous_position[1]-bone.position[1]
			if bottom<previous+.0625 and levelRay(v3(bone.position[0],max(previous,bottom)+.5,bone.position[2]),
					v3(bone.position[0],bottom-.03125,bone.position[2])) then
				local ground=collisionHit.point[1]
				local solid=collisionHit.part.CanCollide
				if solid and collisionHit.normal.y>.5 and ground<=previous+.0625 then
					local correction=ground-bottom+.001
					if correction>.0625 and correction>lift then lift,landed,hitPart=correction,i,collisionHit.part end
				end
			end
		end
	end
	if lift==0 then return end
	for i=0,15 do
		local bone=h.bones[i]
		bone.body.py=bone.body.py+lift
		bone.body.vy=max(0,bone.body.vy)
		bone.position[1]=bone.position[1]+lift
		bone.segment0[1]=bone.segment0[1]+lift;bone.segment1[1]=bone.segment1[1]+lift
	end
	h.bounds_min[1]=h.bounds_min[1]+lift;h.bounds_max[1]=h.bounds_max[1]+lift
	if lift>.25 then
		h.floorRecoveries=(h.floorRecoveries or 0)+1
		if h.floorRecoveries<=3 then print(string.format("Sub Rosa floor sweep: stopped %.2f stud crossing of %s (bone %d)",lift*SCALE,hitPart.Name,landed)) end
	end
end

local function humanUpdate(h)

	if h.health < 75 then
		local ticks = min((75 - h.health) * 2, 60)
		if h.damage_ticks < ticks then
			h.damage_ticks = ticks
		end
	end





	if h.old_health <= 0 then
		h.health = 0
		h.bleeding = false
	else
		local bleeding = h.bleeding
		if gameTick % (bleeding and 64 or 32) == 0 and h.health < 100 then
			h.health = h.health + 1
		end
		if not bleeding then
			if gameTick % 256 == 0 and h.blood < 100 then
				h.blood = h.blood + 1
			end
			if gameTick % 64 == 0 then
				for side = 0, 1 do
					if h.arm_health[side] < 100 then
						h.arm_health[side] = h.arm_health[side] + 1
					end
					if h.leg_health[side] < 100 then
						h.leg_health[side] = h.leg_health[side] + 1
					end
				end
			end
		else
			if h.blood < 20 then
				h.health = min(h.health, h.blood * 2 + 10)
			end
			if h.blood > 0 and gameTick % 256 == h.bleed_phase then
				h.blood = h.blood - 3
				local stomach = h.bones[BONE_STOMACH].position
				Items.spawnBlood(stomach[0], stomach[1] + 0.5, stomach[2])
			end
			if h.blood <= 10 then
				h.old_health = 0
				h.health = 0
			end
		end
	end
	if gameTick % 32 == 0 and h.stamina < min(h.max_stamina, 127) then
		h.stamina = h.stamina + 1
	end
	if gameTick % 8 == 0 and h.damage_ticks > 0 then
		h.damage_ticks = h.damage_ticks - 1
	end


	local amount = hasFlag(h.input_flags, INPUT_CROUCH) and 0.625 or 1
	if h.walk_amount >= amount - 0.015625 then
		if h.walk_amount <= amount + 0.015625 then
			h.walk_amount = amount
		else
			h.walk_amount = h.walk_amount - 0.015625
		end
	else
		h.walk_amount = h.walk_amount + 0.015625
	end



	local difference = angleDifference(h.input_yaw, h.view_yaw)
	local step = clamp(difference, -0.046875, 0.046875)
	if not h.standing then
		step = 0
	end
	h.look_yaw_offset = clamp(difference - step, -1.570796326795, 1.570796326795)
	h.view_yaw = h.view_yaw + step
	if h.view_yaw < -PI then
		h.view_yaw = h.view_yaw + TWO_PI
	elseif h.view_yaw > PI then
		h.view_yaw = h.view_yaw - TWO_PI
	end
	h.view_pitch = h.input_pitch

	h.on_ground = false
	for i = 0, 15 do
		h.bones[i].ground_bond_count = 0
	end
	updateCentre(h)


	local heading = headingAxes(h.view_yaw)
	local pelvis = h.bones[BONE_PELVIS]
	for leg = 0, 1 do
		local l = h.legs[leg]
		local foot = h.bones[BONE_FOOT + 3 * leg]
		l.previous_pitch = l.pitch
		local along = ((pelvis.position[1] - foot.position[1]) * heading[7]
			+ (pelvis.position[0] - foot.position[0]) * heading[6])
			+ ((pelvis.position[2] - foot.position[2]) * heading[8] + 0.1875)
		if along >= 0 then
			l.pitch = 0
		else
			l.pitch = max(along * 3, -1.5707964)
		end
	end


	local seat = h.seat
	if seat then
		h.movement_state = 4
		h.jump_charge = 0
		holdInSeat(h, seat)
	elseif h.movement_state == 4 then
		h.movement_state = STATE_FALL
	end
	-- Gripping a wall used to let the normal jump charge build (feet near the ground
	-- while hanging) and launch you backward into the wall, which could injure and
	-- lock out grabbing. Space now does a dedicated push-off instead (below).
	local gripping = h.grabs and ((h.grabs[0] and h.grabs[0].part) or (h.grabs[1] and h.grabs[1].part))
	if h.old_health > 0 and h.movement_state == STATE_STAND and hasFlag(h.input_flags, INPUT_JUMP)
			and h.jump_charge < 32 and not gripping then
		h.jump_charge = h.jump_charge + 1
	end
	if h.old_health > 0 and h.health >= 50 and h.movement_state ~= STATE_LIE and not seat then
		footGroundContact(h, 0)
		footGroundContact(h, 1)
	end
	if h.movement_state ~= STATE_JUMP and h.jump_charge > 0 and not hasFlag(h.input_flags, INPUT_JUMP)
			and h.legs[0].state == LEG_PLANTED and h.legs[1].state == LEG_PLANTED
			and h.bones[BONE_FOOT].ground_bond_count > 0 and h.bones[BONE_FOOT + 3].ground_bond_count > 0
			and not gripping then
		startJump(h, 1)
	end

	if not (Bonds.boxing and Bonds.boxing:posing(h)) then Items.useHands(h) end
	Items.updateActions(h)
	Grab.update(h)
	driveRagdoll(h)
	if pelvis.rotation[4] < 0.70700002 then
		h.jump_charge = 0
	end


	local state = h.movement_state
	if state == STATE_LIE and not h.input_ragdoll then
		state = STATE_STAND
		h.movement_state = STATE_STAND
	end
	if seat then
		sitLegs(h)
	elseif state ~= STATE_JUMP and h.input_ragdoll then
		h.movement_state = STATE_LIE
		lieLegs(h)
	elseif state == STATE_JUMP then
		launchJump(h)
	else
		standLegs(h)
	end


	if h.old_health <= 0 or h.health < 50 then
		for bone = 1, 15 do
			local j = h.bones[bone].bond
			j.bias[0], j.bias[1], j.bias[2] = 0, 0, 0
			j.has_axis = false
			j.axis[0], j.axis[1], j.axis[2] = 0, 0, 0
			limitJointAngles(h, SKELETON[bone].parent, bone, j.axis)
			if (j.axis[0] * j.axis[0] + j.axis[1] * j.axis[1]) + j.axis[2] * j.axis[2] > 0 then
				j.has_axis = true
			end
			j.angular_limit = 0.000244140625
		end
	end

	collideLevel(h)
	Grab.bind(h)
	-- Wall push-off: a fresh Space press while gripping world geometry kicks off the
	-- wall, instead of fighting the normal jump. Whole body moves together so it
	-- doesn't tumble into fall damage, and grabbing is briefly cooled down so the
	-- hand doesn't immediately snap back onto the same spot.
	if h.grabs and hasFlag(h.input_flags, INPUT_JUMP) and not hasFlag(h.last_input_flags, INPUT_JUMP) then
		local pushed = false
		for side = 0, 1 do
			local g = h.grabs[side]
			if g and g.part then
				local half = g.part.Size * 0.5
				local v = g.offset
				local xFace = math.abs(v.X) / math.max(half.X, 0.01) > math.abs(v.Z) / math.max(half.Z, 0.01)
				local outward = g.part.CFrame:VectorToWorldSpace(
					xFace and Vector3.new(math.sign(v.X), 0, 0) or Vector3.new(0, 0, math.sign(v.Z)))
				local push, lift = WALL_PUSH.speed * TICK / BASE_SCALE, WALL_PUSH.lift * TICK / BASE_SCALE
				for i = 0, 15 do
					local bd = h.bones[i].body
					bd.vx, bd.vy, bd.vz = bd.vx + outward.X * push, bd.vy + lift, bd.vz + outward.Z * push
				end
				Grab.release(h, side)
				pushed = true
			end
		end
		if pushed then h.mantle_cool = WALL_PUSH.cool end
	end
	h.last_input_flags = h.input_flags
end

function Bonds.teleportHuman(h,transform)
	local rotation=transform-transform.p
	local function turn(r)
		local frame=rotation*CFrame.new(0,0,0,r[0],r[3],r[6],r[1],r[4],r[7],r[2],r[5],r[8])
		local _,_,_,a,b,c,d,e,f,g,j,k=frame:components()
		r[0],r[1],r[2],r[3],r[4],r[5],r[6],r[7],r[8]=a,d,g,b,e,j,c,f,k
	end
	local function heading(yaw)
		local v=rotation:vectorToWorldSpace(Vector3.new(sin(yaw),0,-cos(yaw)))
		return atan2(v.x,-v.z)
	end
	for i=0,15 do
		local bone=h.bones[i]
		local body=bone.body
		local p=transform*Vector3.new(body.px*SCALE,body.py*SCALE,body.pz*SCALE)
		body.px,body.py,body.pz=p.x/SCALE,p.y/SCALE,p.z/SCALE
		body.vx,body.vy,body.vz,body.dvx,body.dvy,body.dvz=0,0,0,0,0,0
		body.Lx,body.Ly,body.Lz,body.wx,body.wy,body.wz=0,0,0,0,0,0
		body.dwx,body.dwy,body.dwz=0,0,0
		turn(body.R)
		bone.position[0],bone.position[1],bone.position[2]=body.px,body.py,body.pz
		bone.ground_bond_count=0
	end
	turn(h.smoothed_rotation)
	quatFromMat3(h.smoothed_quat,h.smoothed_rotation)
	for _,v in ipairs({h.trunk_velocity,h.centre_velocity,h.ground_velocity,h.walk_velocity,
		h.smoothed_angular_velocity,h.mean_angular_velocity,h.step_offset}) do
		v[0],v[1],v[2]=0,0,0
	end
	h.legs={[0]=newLeg(),newLeg()}
	h.jump_charge,h.jump_side,h.jump_forward=0,0,0
	h.input_jump_forward,h.input_jump_side=0,0
	h.on_ground=false
	h.movement_state=h.input_ragdoll and STATE_LIE or STATE_STAND
	h.view_yaw,h.input_yaw=heading(h.view_yaw),heading(h.input_yaw)
	syncBones(h)
	updateCentre(h)
	for k=0,2 do h.walk_point[k]=h.centre[k] end
end

function Bonds.characterVelocity(h,velocity)
	local pelvis=h.bones[BONE_PELVIS].body
	local x,y,z=velocity.x*TICK/SCALE-pelvis.vx,velocity.y*TICK/SCALE-pelvis.vy,velocity.z*TICK/SCALE-pelvis.vz
	for i=0,15 do
		local b=h.bones[i].body
		b.vx,b.vy,b.vz=b.vx+x,b.vy+y,b.vz+z
	end
	for _,v in ipairs({h.trunk_velocity,h.centre_velocity}) do v[0],v[1],v[2]=v[0]+x,v[1]+y,v[2]+z end
end

function physicsTick(h)
	gameTick = gameTick + 1
	integrateBodyPositions()
	if h.seat then holdInSeat(h, h.seat) end
	syncBones(h)
	Bonds.supportHumanFloor(h)
	if Bonds.thrower then Bonds.thrower:update(h) end
	if Bonds.boxing then Bonds.boxing:update(h) end
	humanUpdate(h)
	Items.tick()

	if Bonds.vehicles then Bonds.vehicles:prepareTick() end
	if Bonds.boxing then Bonds.boxing:contacts(h) end
	if Bonds.peers then Bonds.peers:prepare(h) end
	physicsSolve()
	if Bonds.thrower then Bonds.thrower:after(h) end
	Items.updateBullets()
	Items.updateParticles()
end

end


local PeerRagdolls = {}
PeerRagdolls.__index = PeerRagdolls
local PEER_PARTS = {{"Torso",{0,1,2}}, {"Head",{3}}, {"Left Arm",{4,5,6}},
	{"Right Arm",{7,8,9}}, {"Left Leg",{10,11,12}}, {"Right Leg",{13,14,15}}}
local GRIP_NAMES = {[0]="Left","Right"}
local PART_BONES = {["Torso"]=0,["Head"]=3,["Left Arm"]=5,["Right Arm"]=8,["Left Leg"]=11,["Right Leg"]=14}
local SINGLE_PULL_ASSIST, MUTUAL_PULL_ASSIST = .25, 1
local SINGLE_PULL_IMPULSE = .12

local function anchor(g,mass,x,y,z,vx,vy,vz)
	local b=g.anchor or {R=identity3(),mass=mass,wx=0,wy=0,wz=0}
	b.px,b.py,b.pz=x,y,z
	b.vx,b.vy,b.vz=vx,vy,vz
	b.dvx,b.dvy,b.dvz,b.dwx,b.dwy,b.dwz=0,0,0,0,0,0
	g.anchor=b
	return b
end

function PeerRagdolls.new(hat,player,getHuman,ownParts)
	local self=setmetatable({hat=hat,player=player,getHuman=getHuman,ownParts=ownParts,
		records={},wearers={},incoming={},targets={},offsets={},nextDiscovery=0},PeerRagdolls)
	self.marker = (hat and hat:FindFirstChild("ClientRagdoll")) or {Value = true}
	self.marker.Value = true
	for side=0,1 do
		self.targets[side] = (hat and hat:FindFirstChild("Grab"..GRIP_NAMES[side])) or {Value = nil}
		self.offsets[side] = (hat and hat:FindFirstChild("GrabOffset"..GRIP_NAMES[side])) or {Value = Vector3.new()}
	end
	Bonds.peers=self
	Bonds.grab.bindPeer=function(h,side,g)self:bind(h,side,g)end
	Bonds.grab.moveProp=function(h,side,g,point,hand)self:moveProp(g,point,hand)end
	local previousRelease=Bonds.grab.release
	Bonds.grab.release=function(h,side)
		for i=0,1 do
			if side==nil or side==i then
				if self.targets[i] and self.targets[i].Value then self.targets[i].Value=nil end
				local g=h and h.grabs and h.grabs[i]
				if g and g.mover then g.mover:Destroy();g.mover=nil end
			end
		end
		previousRelease(h,side)
	end
	Bonds.releaseGrab=Bonds.grab.release
	return self
end

function PeerRagdolls:refresh(h)
	local now=os.clock()
	if now>=self.nextDiscovery then
		self.nextDiscovery=now+.25
		local wearers={}
		for _,other in ipairs(Players:GetPlayers()) do
			if other~=self.player and other.Character and other.Character.Parent then
				local foundHat = nil
				for _,child in ipairs(other.Character:GetChildren()) do
					local marker=child:FindFirstChild("ClientRagdoll")
					if marker and marker.Value and child:FindFirstChild("GrabLeft") and child:FindFirstChild("GrabRight") then
						foundHat = {hat=child,character=other.Character,marker=marker}
						break
					end
				end
				if foundHat then
					wearers[#wearers+1]=foundHat
				elseif other.Character:FindFirstChild("Torso") then
					wearers[#wearers+1]={hat=other.Character,character=other.Character,marker={Value=true}}
				end
			end
		end
		self.wearers=wearers
	end
	local seen,active={},{}
	local pelvis=h.bones[BONE_PELVIS].body
	local at=Vector3.new(pelvis.px*SCALE,pelvis.py*SCALE,pelvis.pz*SCALE)
	for _,wearer in ipairs(self.wearers) do
		local hat,character=wearer.hat,wearer.character
		local torso=character:FindFirstChild("Torso")
		if (hat==character or hat.Parent==character) and character.Parent and wearer.marker.Value and torso and (torso.CFrame.p-at).magnitude<14*(SCALE/BASE_SCALE) then
			active[hat]=true
			for _,entry in ipairs(PEER_PARTS) do
				local part=character:FindFirstChild(entry[1])
				if part and part:IsA("BasePart") then
					local r=self.records[part] or {part=part,hat=hat,character=character,velocity=Vector3.new()}
					local frame=part.CFrame
					if not r.last or (frame.p-r.last).magnitude>.0001 then
						if r.last then
							r.velocity=(frame.p-r.last)*(1/(SCALE*max((now-r.at)/TICK,1)))
							if r.velocity.magnitude>.3 then r.velocity=Vector3.new() end
						end
						r.last,r.at=frame.p,now
					elseif now-r.at>.15 then r.velocity=Vector3.new() end
					r.frame=frame
					local x,y,z,a,b,c,d,e,f,g,j,k=frame:components()
					local size=part.Size
					r.box={x=x/SCALE,y=y/SCALE,z=z/SCALE,r00=a,r01=b,r02=c,r10=d,r11=e,r12=f,r20=g,r21=j,r22=k,
						hx=size.x/(2*SCALE),hy=size.y/(2*SCALE),hz=size.z/(2*SCALE)}
					r.mass=0
					for _,bone in ipairs(entry[2]) do r.mass=r.mass+SKELETON[bone].mass end
					self.records[part],seen[part]=r,true
				end
			end
		end
	end
	for part in pairs(self.records) do if not seen[part] then self.records[part]=nil end end
	for hat in pairs(self.incoming) do if not active[hat] then self.incoming[hat]=nil end end
end

function PeerRagdolls:bind(h,side,g)
	if not Cfg.PlayerCollision then
		Bonds.releaseGrab(h,side);return
	end
	local record=g.peer
	if not record or self.records[record.part]~=record or not record.part.Parent then
		Bonds.releaseGrab(h,side);return
	end
	local point=record.frame*g.offset
	local hand=h.bones[BONE_HAND+side*3].body
	local x,y,z=point.x/SCALE,point.y/SCALE,point.z/SCALE
	if (x-hand.px)^2+(y-hand.py)^2+(z-hand.pz)^2>1 then Bonds.releaseGrab(h,side);return end

	if self.targets[side] and self.targets[side].Value~=record.part then
		self.offsets[side].Value=g.offset
		self.targets[side].Value=record.part
	end
	local v=record.velocity
	local b=anchor(g,record.mass,x,y,z,v.x,v.y,v.z)
	g.last=point
	local c=Bonds.point(hand,b,0,0,0,0,0,0)
	c.share_b=0
end

function PeerRagdolls:incomingBonds(h)
	if not Cfg.PlayerCollision then
		self.incoming = {}
		return
	end
	local active={}
	for _,wearer in ipairs(self.wearers) do
		if (wearer.hat==wearer.character or wearer.hat.Parent==wearer.character) and wearer.marker.Value then
			local mutual=false
			for side=0,1 do
				local target=self.targets[side] and self.targets[side].Value
				if target and target.Parent==wearer.character then mutual=true end
			end
			local budget=not mutual and {left=SINGLE_PULL_IMPULSE} or nil
			for side=0,1 do
				local target=wearer.hat:FindFirstChild("Grab"..GRIP_NAMES[side])
				local offset=wearer.hat:FindFirstChild("GrabOffset"..GRIP_NAMES[side])
				local part=target and target.Value
				local index=part and PART_BONES[part.Name]
				local arm=wearer.character:FindFirstChild(side==0 and "Left Arm" or "Right Arm")
				if index and part==self.ownParts[part.Name] and offset and arm and self.records[arm] then
					local o=offset.Value
					local size=part.Size
					if o.x==o.x and o.y==o.y and o.z==o.z and abs(o.x)<=size.x*.5+.3 and abs(o.y)<=size.y*.5+.3 and abs(o.z)<=size.z*.5+.3 then
						local point=part.CFrame*o
						local palm=arm.CFrame*Vector3.new(0,-1,0)
						if (palm-point).magnitude<3 and not levelRay(v3(palm.x/SCALE,palm.y/SCALE,palm.z/SCALE),v3(point.x/SCALE,point.y/SCALE,point.z/SCALE)) then
							local torso=wearer.character:FindFirstChild("Torso")
							if torso then
								local shoulder=torso.CFrame*Vector3.new(side==0 and -1.5 or 1.5,.5,0)
								local reach=palm-shoulder
								if reach.magnitude>1.8 then
									local assist=(shoulder+reach*(1.8/reach.magnitude)-palm)*(mutual and MUTUAL_PULL_ASSIST or SINGLE_PULL_ASSIST)
									if not mutual and assist.magnitude>.3 then assist=assist*(.3/assist.magnitude) end
									palm=palm+assist
								end
							end
							local list=self.incoming[wearer.hat] or {}
							local g=list[side] or {velocity=Vector3.new()}
							if not g.last or (palm-g.last).magnitude>.0001 then
								if g.last then
									g.velocity=(palm-g.last)*(1/(SCALE*max((os.clock()-g.at)/TICK,1)))
									if g.velocity.magnitude>.3 then g.velocity=Vector3.new() end
								end
								g.last,g.at=palm,os.clock()
							elseif os.clock()-g.at>.15 then g.velocity=Vector3.new() end
							local v=g.velocity
							local b=anchor(g,1.5,palm.x/SCALE,palm.y/SCALE,palm.z/SCALE,v.x,v.y,v.z)
							local body=h.bones[index].body
							local localPoint=v3()
							toLocal(localPoint,body.R,v3(point.x/SCALE-body.px,point.y/SCALE-body.py,point.z/SCALE-body.pz))
							local c=Bonds.point(body,b,localPoint[0],localPoint[1],localPoint[2],0,0,0)
							c.share_b=0
							c.gripBudget=budget
							local half=SKELETON[index].half
							local lever=v3()
							toWorld(lever,body.R,v3(clamp(localPoint[0],-half[0],half[0]),clamp(localPoint[1],-half[1],half[1]),clamp(localPoint[2],-half[2],half[2])))
							if not mutual then c.rax,c.ray,c.raz=lever[0],lever[1],lever[2] end
							list[side],self.incoming[wearer.hat]=g,list
							active[g]=true
						end
					end
				end
			end
		end
	end
	for hat,list in pairs(self.incoming) do
		for side=0,1 do if list[side] and not active[list[side]] then list[side]=nil end end
		if not next(list) then self.incoming[hat]=nil end
	end
end

function PeerRagdolls:prepare(h)
	self:refresh(h)
	if not Cfg.PlayerCollision then
		return
	end
	for side=0,1 do
		local g=h.grabs and h.grabs[side]
		if g and not g.peer and not g.item and not g.part then
			local hand=h.bones[BONE_HAND+side*3].body
			local nearest=.1
			local record,offset
			for _,r in pairs(self.records) do
				local distance,x,y,z=boxDistance(r.box,hand.px,hand.py,hand.pz)
				if distance<nearest and not levelRay(v3(hand.px,hand.py,hand.pz),v3(x,y,z)) then
					nearest,record,offset=distance,r,r.frame:inverse()*Vector3.new(x*SCALE,y*SCALE,z*SCALE)
				end
			end
			if record then g.peer,g.offset=record,offset;self:bind(h,side,g) end
		end
	end
	self:incomingBonds(h)
	for i=0,15 do
		local bone=h.bones[i]
		local radius=SKELETON[i].radius
		for _,r in pairs(self.records) do
			local nearest=radius
			local hx,hy,hz,nx,ny,nz
			for sample=0,2 do
				local a,b,t=bone.segment0,bone.segment1,sample*.5
				local distance,x,y,z,ux,uy,uz=boxDistance(r.box,a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t,a[2]+(b[2]-a[2])*t)
				if distance<nearest then nearest,hx,hy,hz,nx,ny,nz=distance,x,y,z,ux,uy,uz end
			end
			if hx then
				local body=bone.body
				local c=addWorldContact(body,hx-body.px,hy-body.py,hz-body.pz,nx,ny,nz,min(radius-nearest,.15),.35,.03125,.0625)
				c.tvx,c.tvy,c.tvz=r.velocity.x,r.velocity.y,r.velocity.z
				c.peerScale=r.mass/(r.mass+body.mass)
			end
		end
	end
end

function PeerRagdolls:moveProp(g,point,hand)
	if g.part.Anchored then
		if g.mover then g.mover:Destroy();g.mover=nil end
		return
	end
	if not g.mover then
		g.mover=Instance.new("BodyPosition")
		g.mover.Name="RagdollGrab"
		g.mover.MaxForce=Vector3.new(12000,12000,12000)
		g.mover.P,g.mover.D=5000,350
	end
	if os.clock()>=(g.nextPropUpdate or 0) then
		g.nextPropUpdate=os.clock()+1/15
		g.mover.Position=Vector3.new(hand.px*SCALE,hand.py*SCALE,hand.pz*SCALE)-(point-g.part.Position)
		g.mover.Parent=g.part
	end
end

function PeerRagdolls:stop()
	local h = self.getHuman and self.getHuman()
	if h then Bonds.releaseGrab(h) end
	if self.marker then self.marker.Value=false end
	self.records,self.wearers,self.incoming={},{},{}
	Bonds.peers=nil
end

local HatBoxing = {}
HatBoxing.__index = HatBoxing
do
local REGIONS = {
	["Torso"]={bone=2,damage=175,kick=2.75,hp="chest"},
	["Head"]={bone=3,damage=345,kick=8.75,hp="head"},
	["Left Arm"]={bone=5,damage=0,kick=2.25},
	["Right Arm"]={bone=8,damage=0,kick=2.25},
	["Left Leg"]={bone=11,damage=125,kick=2.75,leg=0},
	["Right Leg"]={bone=14,damage=125,kick=2.75,leg=1},
}
local SOUND_IDS = {"95664","95665"}
local COOLDOWN = 25

function HatBoxing.allowed(world)
	return true
end

function HatBoxing.new(peers,allowed)
	local self=setmetatable({peers=peers,allowed=allowed~=false,mode=Cfg.BoxingMode==true,blocking=false,
		cooldown=0,side=1,serial=0,seen={},sounds={},hp={head=100,chest=100}},HatBoxing)
	self.permission = (peers and peers.hat and peers.hat:FindFirstChild("BoxingAllowed")) or {Value = true}
	self.hit = (peers and peers.hat and peers.hat:FindFirstChild("BoxingHit")) or {Value = ""}
	self.hit.Value=""
	self.permission.Value=self.allowed
	if self.allowed then Bonds.boxing=self end
	return self
end

function HatBoxing:cancel()
	self.swing,self.blocking,self.previous,self.swingAge=nil,false,nil,nil
end

function HatBoxing:posing(h)
	return self.allowed and self.mode and h.old_health>0 and h.health>=50
		and not h.input_grab and not h.input_ragdoll and not h.seat
		and not h.hands[0] and not h.hands[1] and not hasFlag(h.input_flags,INPUT_THROW)
		and not (Bonds.thrower and Bonds.thrower:hasHeld(h))
end

function HatBoxing:update(h)
	if self.cooldown>0 then self.cooldown=self.cooldown-1 end
	if self.startCooldown and self.startCooldown>0 then self.startCooldown=self.startCooldown-1 end
	local primary=hasFlag(h.input_flags,INPUT_PRIMARY)
	local fresh=primary and not self.primaryDown
	self.primaryDown=primary
	local chord=primary and hasFlag(h.input_flags,INPUT_CROUCH) and hasFlag(h.input_flags,0x10)
	if chord and not self.toggleDown then
		self.mode=not self.mode
		Cfg.BoxingMode=self.mode
		self:cancel()
		self.toggleDown=true
	end
	if not primary then self.toggleDown=false end
	if not self:posing(h) or chord then self:cancel();return end
	self.blocking=hasFlag(h.input_flags,INPUT_AIM)
	local finishing=self.swing~=nil and not self.spent and self.swingAge
		and self.swingAge<(self.minSwingTicks or 0)
	if self.blocking or (not primary and not finishing) or hasFlag(h.input_flags,INPUT_JUMP) then
		self.swing,self.previous,self.swingAge=nil,nil,nil
	end
	if not self.swing then
		local turn=h.bones[BONE_HEAD].body.wy
		local yaw=angleDifference(h.input_yaw,self.lastYaw or h.input_yaw)
		if turn<=-.01 or yaw<-.001 then self.side=1
		elseif turn>=.01 or yaw>.001 then self.side=0 end
	end
	self.lastYaw=h.input_yaw
	if fresh and not finishing and not self.blocking and not hasFlag(h.input_flags,INPUT_JUMP)
		and self.cooldown==0 and (self.startCooldown or 0)==0 then
		self.swing,self.spent=self.side,false
		self.swingAge=0
		self.startCooldown=self.swingCooldownTicks or 0
		local bone=h.bones[BONE_HAND+self.side*3]
		self.previous=v3(bone.previous_position[0],bone.previous_position[1],bone.previous_position[2])
	end
	if self.swing~=nil then self.swingAge=(self.swingAge or 0)+1 end
end

function HatBoxing:target(h,side,target,rotation)
	if not self:posing(h) then return false end
	local yaw=0
	if self.blocking then
		target[0],target[1],target[2]=side==0 and -.19 or .19,.22,-.4
		yaw=side==0 and -1 or 1
	elseif self.swing~=nil and not self.spent and self.cooldown==0 then
		if side==self.swing then
			target[0],target[1],target[2]=side==0 and .1 or -.1,.015,-.95
			if self.swingAge and self.swingAge<(self.prepTicks or 6) then
				target[0],target[1],target[2]=side==0 and .16 or -.16,-.03,-.3
			end
			yaw=side==0 and -.4 or .4
		else target[0],target[1],target[2]=side==0 and -.19 or .19,.12,-.4 end
	else target[0],target[1],target[2]=side==0 and -.19 or .19,.14,-.4 end
	copy9(rotation,identity3())
	rotateRows(rotation,0,1,0,yaw)
	return true
end

local function sweep(record,from,to,radius)
	local inverse=record.frame:inverse()
	local a=inverse*Vector3.new(from[0]*SCALE,from[1]*SCALE,from[2]*SCALE)
	local b=inverse*Vector3.new(to[0]*SCALE,to[1]*SCALE,to[2]*SCALE)
	local lo,hi=0,1
	for _,axis in ipairs({"x","y","z"}) do
		local x,d=a[axis]/SCALE,(b[axis]-a[axis])/SCALE
		local half=record.part.Size[axis]/(2*SCALE)+(radius or .1)
		if abs(d)<1e-8 then
			if abs(x)>half then return end
		else
			local near,far=(-half-x)/d,(half-x)/d
			if near>far then near,far=far,near end
			lo,hi=max(lo,near),min(hi,far)
			if lo>hi then return end
		end
	end
	return lo
end

local function eligible(hat)
	return true
end

function HatBoxing:outgoing(h)
	if self.swing==nil or self.spent or self.cooldown>0 or not self.mode or self.blocking
		or h.input_grab or h.input_ragdoll or h.old_health<=0 or h.health<50 then return end
	local hand=h.bones[BONE_HAND+self.swing*3].body
	local to=v3(hand.px,hand.py,hand.pz)
	local from=self.previous or to
	self.previous=to

	if self.swingAge and self.swingAge<(self.prepTicks or 6) then return end
	if (to[0]-from[0])^2+(to[1]-from[1])^2+(to[2]-from[2])^2>1 then return end
	local nearest,record,point=2
	for _,r in pairs(self.peers.records) do
		local humanoid=r.character:FindFirstChild("Humanoid")
		if eligible(r.hat) and humanoid and humanoid.Health>0 then
			local t=sweep(r,from,to,self.fistRadius)
			if t and t<nearest then
				local p=v3(from[0]+(to[0]-from[0])*t,from[1]+(to[1]-from[1])*t,from[2]+(to[2]-from[2])*t)
				local chest=h.bones[BONE_CHEST].body
				if not levelRay(from,p) and not levelRay(v3(chest.px,chest.py,chest.pz),p) then
					nearest,record,point=t,r,p
				end
			end
		end
	end
	if not record then return end
	local vx,vy,vz=hand.vx,hand.vy,hand.vz
	local speed=sqrt(vx*vx+vy*vy+vz*vz)
	if speed>.3 then vx,vy,vz=vx*.3/speed,vy*.3/speed,vz*.3/speed end
	local v=record.velocity
	local relative=sqrt((vx-v.x)^2+(vy-v.y)^2+(vz-v.z)^2)
	if relative<.002 then return end
	self.serial=self.serial+1
	if not self.serverTransport and self.hit then
		self.hit.Value=string.format("%d|%s|%s|%.6f|%.6f|%.6f|%.6f|%.6f|%.6f|%.6f",self.serial,
			record.character.Name,record.part.Name,vx,vy,vz,relative,point[0],point[1],point[2])
	end
	self.spent,self.cooldown=true,self.cooldownTicks or COOLDOWN
	self:playSound(record.part)
	if self.onImpact then self:onImpact(record,point,Vector3.new(vx,vy,vz),relative) end
end

function HatBoxing:playSound(part)
	if not part then return end
	local variant=math.random(1,2)
	local sound=self.sounds[variant]
	if not sound then
		sound=Instance.new("Sound")
		sound.Name="BoxingImpact"..variant
		sound.SoundId="rbxassetid://"..SOUND_IDS[variant]
		sound.Volume=1
		self.sounds[variant]=sound
	end
	sound:Stop()
	sound.Pitch=.7+math.random(1,6)*.1
	sound.Parent=part
	sound:Play()
end

function HatBoxing:apply(h,name,vx,vy,vz,relative,confirmedDeath)
	local region=REGIONS[name]
	if not region or (h.old_health<=0 and not confirmedDeath) then return end
	local damage=min(95,relative*region.damage)
	if region.hp then
		self.hp[region.hp]=max(0,self.hp[region.hp]-damage)
		h.health=min(h.health,self.hp[region.hp])
		if self.hp[region.hp]<=0 then h.old_health=0 end
	elseif region.leg~=nil then
		h.leg_health[region.leg]=max(0,h.leg_health[region.leg]-damage)
	end
	local body=h.bones[region.bone].body
	body.vx,body.vy,body.vz=body.vx+vx*region.kick,body.vy+vy*region.kick,body.vz+vz*region.kick
	if h.health<50 then Bonds.releaseGrab(h);self:cancel() end
	self:playSound(self.peers.ownParts[name])
end

function HatBoxing:incoming(h)
	if not Cfg.PlayerCollision then return end
	local active={}
	for _,wearer in ipairs(self.peers.wearers) do
		local hat=wearer.hat
		if hat and (hat==wearer.character or hat.Parent==wearer.character) and wearer.character.Parent and eligible(hat) then
			local value=hat:FindFirstChild("BoxingHit")
			if value and value:IsA("StringValue") then
				active[hat]=true
				local seen=self.seen[hat]
				if not seen then
					seen={value=value.Value,nextHit=0};self.seen[hat]=seen
				elseif value.Value~=seen.value then
					seen.value=value.Value
					local fields={}
					for field in string.gmatch(value.Value,"[^|]+") do fields[#fields+1]=field end
					local myName = self.peers.player and self.peers.player.Name or ""
					local valid=#fields==10 and fields[2]==myName and REGIONS[fields[3]]~=nil
					for i=4,10 do
						fields[i]=tonumber(fields[i])
						valid=valid and fields[i]~=nil and fields[i]==fields[i] and abs(fields[i])<1e6
					end
					if valid and os.clock()+1e-6>=seen.nextHit and h.old_health>0 then
						local vx,vy,vz,relative=fields[4],fields[5],fields[6],fields[7]
						local point=Vector3.new(fields[8]*SCALE,fields[9]*SCALE,fields[10]*SCALE)
						local part=self.peers.ownParts[fields[3]]
						local torso=wearer.torso or wearer.character:FindFirstChild("Torso")
						if vx*vx+vy*vy+vz*vz<=.09001 and relative>=.002 and relative<=.60001 and part and torso
							and (point-part.CFrame.p).magnitude<=part.Size.magnitude*.5+1
							and (point-torso.CFrame.p).magnitude<6*(SCALE/BASE_SCALE)
							and not levelRay(v3(torso.CFrame.p.x/SCALE,torso.CFrame.p.y/SCALE,torso.CFrame.p.z/SCALE),v3(fields[8],fields[9],fields[10])) then
							seen.nextHit=os.clock()+COOLDOWN*TICK
							self:apply(h,fields[3],vx,vy,vz,relative)
						end
					end
				end
			end
		end
	end
	for hat in pairs(self.seen) do if not active[hat] then self.seen[hat]=nil end end
end

function HatBoxing:contacts(h)
	if not self.allowed then return end
	self:incoming(h)
	self:outgoing(h)
end

function HatBoxing:stop()
	self.allowed,self.mode=false,false
	self:cancel()
	if self.permission then self.permission.Value=false end
	if self.hit then self.hit.Value="" end
	for _,sound in pairs(self.sounds) do sound:Destroy() end
	self.sounds,self.seen={},{}
	if Bonds.boxing==self then Bonds.boxing=nil end
end
end

local HatGear = {}
do
local UP=Vector3.new(0,1,0)
local function bodyFrame(body)
	local r=body.R
	return CFrame.new(body.px*SCALE,body.py*SCALE,body.pz*SCALE,
		r[0],r[3],r[6],r[1],r[4],r[7],r[2],r[5],r[8])
end

local function bool(tool,name)
	local value=tool:FindFirstChild(name)
	if value and value:IsA("BoolValue") then return value.Value end
end

local function facing(direction)
	local forward=direction.unit
	local right=forward:Cross(UP)
	if right.magnitude<.001 then right=forward:Cross(Vector3.new(0,0,1)) end
	right=right.unit
	local up=right:Cross(forward)
	return CFrame.new(0,0,0,right.x,up.x,-forward.x,right.y,up.y,-forward.y,right.z,up.z,-forward.z)
end

local function localPoint(record,object)
	if object:IsA("BasePart") then return record.handle.CFrame:inverse()*object.CFrame.p end
	if object:IsA("Attachment") and object.Parent and object.Parent:IsA("BasePart") then
		return record.handle.CFrame:inverse()*(object.Parent.CFrame*object.Position)
	end
end

function HatGear.restore(record)
	local joint=record.joint
	if joint and joint.Parent and record.lastMount and joint[record.mountProperty]==record.lastMount
		and ((joint.Part0==record.arm and joint.Part1==record.handle) or (joint.Part1==record.arm and joint.Part0==record.handle)) then
		joint[record.mountProperty]=record.authorMount
	end
	record.lastMount=nil
end

function HatGear.bind(record,character)
	local arm=character:FindFirstChild(record.side==0 and "Left Arm" or "Right Arm")
	local joint=arm and arm:FindFirstChild(record.side==0 and "LeftGrip" or "RightGrip")
	if not joint or not ((joint.Part0==arm and joint.Part1==record.handle) or (joint.Part1==arm and joint.Part0==record.handle)) then joint=nil end
	if joint~=record.joint then
		HatGear.restore(record)
		record.arm,record.joint=arm,joint
		if joint then
			record.mountProperty=joint.Part0==arm and "C0" or "C1"
			record.handleProperty=joint.Part0==arm and "C1" or "C0"
			record.authorMount=joint[record.mountProperty] or CFrame.new(0,-1,0)
			record.baseMount=record.authorMount
			record.referenceGrip=joint[record.handleProperty] or record.tool.Grip or CFrame.new()
			record.nextScan=nil
		end
	end
	if os.clock()>=(record.nextScan or 0) then HatGear.scan(record) end
end

function HatGear.scan(record)
	record.nextScan=os.clock()+.25
	local name=string.lower(record.tool.Name)
	local words=" "..string.gsub(name,"[^%w]"," ").." "
	local compact=string.gsub(name,"[^%w]","")
	local gun=name:find("gun",1,true)~=nil
	local long=compact=="ak47" or compact=="m16" or compact=="m4a1"
	gun=gun or long
	for _,word in ipairs({"rifle","shotgun","carbine","musket","smg","mp5","uzi","ak47","m16","m4a1","sniper"}) do
		if words:find(" "..word.." ",1,true) then gun,long=true,true end
	end
	for _,word in ipairs({"pistol","revolver","glock","magnum","blaster","9mm","1911","colt","deagle","beretta"}) do
		if words:find(" "..word.." ",1,true) then gun=true end
	end
	local muzzle,support
	local function inspect(parent)
		for _,child in ipairs(parent:GetChildren()) do
			local n=string.lower(child.Name):gsub("[^%w]","")
			if n=="ammo" or n=="ammocount" or n=="clipammo" or n=="ammunition"
				or n=="gun" or n=="gunscript" or n=="gunscriptlocal" or n=="gunscriptserver" or n=="gunclient" or n=="gunserver" then gun=true end
			if n=="muzzle" or n=="muzzleattachment" or n=="muzzlepoint" or n=="firepoint" or n=="bulletspawn" or n=="barrel" then
				local point=localPoint(record,child)
				if point and (not muzzle or n~="barrel") then muzzle=point;gun=true end
			end
			if n=="subrosasupportgrip" then
				if child:IsA("CFrameValue") then support=child.Value.p
				elseif child:IsA("Vector3Value") then support=child.Value
				else support=localPoint(record,child) end
			elseif not support and (n=="supportgrip" or n=="lefthandgrip" or n=="leftgripattachment" or n=="foregrip") then
				support=localPoint(record,child)
			end
			inspect(child)
		end
	end
	inspect(record.tool)
	local forced=bool(record.tool,"SubRosaGun")
	local two=bool(record.tool,"SubRosaTwoHanded")
	if two==true then gun=true end
	if forced~=nil then gun=forced end
	local reference=record.referenceGrip or record.tool.Grip or CFrame.new()
	local gripRotation=reference-reference.p
	local direction=muzzle and gripRotation:inverse():vectorToWorldSpace(muzzle)
	if direction and direction.magnitude>.1 then
		long=long or direction.magnitude>1.6
		record.calibration=facing(direction):inverse()
	else record.calibration=CFrame.new() end
	local size=record.handle.Size
	long=long or (size and max(size.x,size.y,size.z)>2) or false
	record.gun,record.twoHanded,record.long=gun,gun and two~=false,long
	record.supportPoint=support
	local brace=Vector3.new(record.side==1 and -.65 or .65,-.08,long and -.65 or -.12)
	record.defaultSupport=reference*record.calibration:inverse()*brace
end

local function updateMount(record)
	local joint=record.joint
	if joint and joint.Parent then
		local mount=joint[record.mountProperty]
		if mount and mount~=record.lastMount then record.authorMount=mount end
	end
end

function HatGear.gripFrame(record,h)
	updateMount(record)
	local wrist=bodyFrame(h.bones[BONE_HAND+record.side*3].body)
	local calibration=record.gun and record.calibration or CFrame.new()
	local extra=record.baseMount and record.baseMount:inverse()*record.authorMount or CFrame.new()
	local grip=wrist*calibration*(extra-extra.p)


	if record.authorMount then
		local forearm=bodyFrame(h.bones[BONE_FOREARM+record.side*3].body)
		grip=grip+forearm:vectorToWorldSpace(record.authorMount.p+Vector3.new(0,1,0))
	end
	return grip
end

function HatGear.supportWorld(record,h)
	local grip=HatGear.gripFrame(record,h)



	local handleGrip=record.joint and record.joint[record.handleProperty] or record.tool.Grip or CFrame.new()
	return grip*handleGrip:inverse()*(record.supportPoint or record.defaultSupport)
end

function HatGear.apply(record,h,armFrame)
	if not record.joint or not record.joint.Parent then return end
	if not ((record.joint.Part0==record.arm and record.joint.Part1==record.handle)
		or (record.joint.Part1==record.arm and record.joint.Part0==record.handle)) then return end
	local grip=HatGear.gripFrame(record,h)
	local mount=armFrame:inverse()*grip
	record.joint[record.mountProperty]=mount
	record.lastMount=mount
end
end

local HatThrow = {}
HatThrow.__index = HatThrow
do
local MAX_BEND = .196349540849375

local function inside(object,parent)
	while object do
		if object==parent then return true end
		object=object.Parent
	end
	return false
end

function HatThrow.new(player,character)
	local self=setmetatable({player=player,character=character,tools={},visibleParts={}},HatThrow)
	Bonds.thrower=self
	return self
end

function HatThrow:refresh()
	local tools={}
	for _,tool in ipairs(self.character:GetChildren()) do
		if tool:IsA("Tool") then
			local handle=tool:FindFirstChild("Handle")
			if handle and handle:IsA("BasePart") and not handle.Anchored then
				local side=1
				local left=self.character:FindFirstChild("Left Arm")
				local grip=left and left:FindFirstChild("LeftGrip")
				if grip and (grip.Part0==handle or grip.Part1==handle) then side=0 end
				local record=self.tools[side]
				if not record or record.tool~=tool or record.handle~=handle then
					record={tool=tool,handle=handle,side=side}
				end
				HatGear.bind(record,self.character)
				tools[side]=record
			end
		end
	end
	for side,record in pairs(self.tools) do if tools[side]~=record then HatGear.restore(record) end end
	self.tools=tools
end

function HatThrow:supportFor(side,h)
	local record=self.tools[1-side]
	if not record or not record.twoHanded or self.tools[side] then return end
	if h and (h.hands[side==0 and 1 or 0] or h.old_health<=0 or h.health<50) then return end
	if self.state and self.selected==record then return end
	return record
end

function HatThrow:holdsArm(side)
	return self.tools[side]~=nil or self:supportFor(side,self.human)~=nil
end

function HatThrow:hasHeld(h)
	return next(self.tools)~=nil or h.hands[0]~=nil or h.hands[1]~=nil
end

function HatThrow:aiming(h)
	for _,record in pairs(self.tools) do if record.gun then return true end end
	return false
end

function HatThrow:leftGun()
	return self.tools[0] and self.tools[0].gun and not (self.tools[1] and self.tools[1].gun)
end

function HatThrow:valid(h,record)
	if not record then return false end
	if record.tool then
		return record.tool.Parent==self.character and record.handle.Parent==record.tool
			and not record.handle.Anchored
	end
	local item=record.item
	return item and h.hands[record.hand]==item and item.holder==h and item.body and not item.gone
end

function HatThrow:begin(h,otherHand)
	if not h or self.state or h.old_health<=0 or h.health<50 or h.seat then return false end
	self:refresh()

	local first=otherHand and 0 or 1
	local function held(hand)
		local item=h.hands[hand]
		if item and item.body and item.holder==h and not item.gone then
			return {item=item,hand=hand,side=hand==0 and 1 or 0}
		end
		return self.tools[hand==0 and 1 or 0]
	end
	self.selected=held(first) or held(1-first)
	if not self.selected then return false end
	self.state,self.windPitch="wind",0
	h.throw_pitch=0
	return true
end

function HatThrow:winding()
	return self.state=="wind"
end

function HatThrow:release(h,bend)
	if self.state~="wind" or not self:valid(h,self.selected) then self:cancel(h);return end
	h.throw_pitch=clamp(bend or 0,-MAX_BEND,MAX_BEND)*8
	self.state,self.windPitch="swing",h.throw_pitch
	if self.dial then self.dial.Visible=false end
end

function HatThrow:cancel(h)
	self.state,self.selected,self.ready,self.windPitch=nil,nil,nil,0
	if h then h.throw_pitch=0;h.inventory_anim_flags=-1 end
	if self.dial then self.dial.Visible=false end
end

function HatThrow:update(h)
	self.human=h
	self:refresh()
	if self.state and (not self:valid(h,self.selected) or h.old_health<=0 or h.health<50 or h.seat) then
		self:cancel(h)
	end
	h.inventory_anim_flags=-1
	if self.state=="wind" then
		h.throw_pitch=clamp(h.input_spine_bend,-MAX_BEND,MAX_BEND)*8
	elseif self.state=="swing" then
		h.inventory_anim_flags=0

		local pitch=h.throw_pitch
		self.ready=pitch>-.196349540849375 and pitch<.0981747704246875
		if pitch>=-.1595340019401172 then
			h.throw_pitch=pitch<=.14726215563703127 and 0 or pitch-.14726215563703127
		else h.throw_pitch=pitch+.1595340019401172 end
	end
end

function HatThrow:target(h,side,target,rotation)
	local record=self.tools[side]
	local support=not record and self:supportFor(side,h)
	if support then
		local point=HatGear.supportWorld(support,h)
		local chest=h.bones[BONE_CHEST]
		toLocal(target,chest.rotation,v3(point.x/SCALE-chest.body.px,point.y/SCALE-chest.body.py,point.z/SCALE-chest.body.pz))
		local main=h.bones[BONE_HAND+support.side*3].rotation
		multiplyTransposed(rotation,main,chest.rotation)
		for k=0,2 do target[k]=target[k]+rotation[3+k]*.0625-ARM_OFFSET[side][k] end
		return true
	end
	if not record then return false end



	local item={type={id=0,gun=record.gun,grip={[0]=v3()},sight=v3(0,0,.24625)}}
	local hand=side==0 and 1 or 0
	local pose=setmetatable({hands={[hand]=item}}, {__index=h})


	pose.input_flags=h.input_flags-(hasFlag(h.input_flags,INPUT_AIM) and INPUT_AIM or 0)
	if not (self.state and self.selected.side==side) then
		pose.input_flags=pose.input_flags-(hasFlag(pose.input_flags,INPUT_THROW) and INPUT_THROW or 0)
		pose.inventory_anim_flags=-1
	end
	copy9(rotation,identity3())
	Bonds.arm.baseHandRotation(pose,item,record.gun,rotation)
	local offset=v3()
	local throwing=self.state and self.selected==record
	if record.gun and not throwing then
		Bonds.arm.aimHandTarget(offset,pose,0,item.type,rotation)
		if side==0 then offset[0]=offset[0]-.25 end
	else Bonds.arm.handOffset(pose,side,item,rotation,offset) end
	local shoulder=ARM_OFFSET[side]
	for k=0,2 do target[k]=offset[k]+rotation[3+k]*.0625-shoulder[k] end


	if not record.gun and not throwing then target[1]=target[1]-.125 end
	return true
end

function HatThrow:twist(h,side)
	if self:supportFor(side,h) then return .9 end
	local record=self.tools[side]
	return record and record.gun and (record.long and 1.15 or .9) or PI_4
end

function HatThrow:render(h,places)
	for side,record in pairs(self.tools) do
		if self:valid(h,record) then HatGear.apply(record,h,places[side==0 and 3 or 4]) end
	end
end

function HatThrow:showTools()
	local present={}
	local function show(parent)
		for _,child in ipairs(parent:GetChildren()) do
			if child:IsA("BasePart") then
				if self.visibleParts[child]==nil then
					self.visibleParts[child]=child.LocalTransparencyModifier or 0
				end
				present[child]=true
				child.LocalTransparencyModifier=0
			end
			show(child)
		end
	end
	for _,tool in ipairs(self.character:GetChildren()) do
		if tool:IsA("Tool") then show(tool) end
	end
	for part,original in pairs(self.visibleParts) do
		if not present[part] then
			pcall(function() part.LocalTransparencyModifier=original end)
			self.visibleParts[part]=nil
		end
	end
end

local function detachGrips(root,tool)
	for _,child in ipairs(root:GetChildren()) do
		if child:IsA("JointInstance") then
			local a,b=child.Part0,child.Part1
			if a and b and inside(a,tool)~=inside(b,tool) then child:Destroy() end
		else detachGrips(child,tool) end
	end
end

local function placeDroppedTool(tool,handle,h,hand)
	local palm=Vector3.new(hand.px*SCALE,hand.py*SCALE,hand.pz*SCALE)
	local forward=Vector3.new(sin(h.input_yaw),0,-cos(h.input_yaw))


	local destination=palm+forward*(1.5+handle.Size.magnitude*.5)
	if levelRay(v3(palm.x/SCALE,palm.y/SCALE,palm.z/SCALE),
		v3(destination.x/SCALE,destination.y/SCALE,destination.z/SCALE)) then return end
	local delta=destination-handle.CFrame.p
	local parts={}
	local function gather(parent)
		for _,child in ipairs(parent:GetChildren()) do
			if child:IsA("BasePart") then parts[#parts+1]={part=child,frame=child.CFrame} end
			gather(child)
		end
	end
	gather(tool)
	for _,row in ipairs(parts) do row.part.CFrame=row.frame+delta end
end

function HatThrow:after(h)
	if not self.ready then return end
	local record=self.selected
	if not self:valid(h,record) then self:cancel(h);return end
	if record.tool then
		local hand=h.bones[BONE_HAND+record.side*3].body
		local velocity=Vector3.new(hand.vx*SCALE/TICK,hand.vy*SCALE/TICK,hand.vz*SCALE/TICK)

		if velocity.magnitude>60 then velocity=velocity*(60/velocity.magnitude) end
		local handle,tool=record.handle,record.tool
		detachGrips(self.character,tool)
		placeDroppedTool(tool,handle,h,hand)
		handle.CanCollide=true
		tool.Parent=Workspace
		handle.Velocity=velocity
		handle.RotVelocity=Vector3.new()
		self.tools[record.side]=nil
	else


		local item=record.item
		h.hands[record.hand]=nil
		item.holder,item.slot,item.hidden,item.rest=nil,nil,false,0
		local body=item.body
		body.Lx,body.Ly,body.Lz,body.wx,body.wy,body.wz=0,0,0,0,0,0
		body.settled=false
	end
	self:cancel(h)
end

local function point(angle)
	return 608-cos(angle)*32,352+sin(angle)*64
end

local function line(frame,x1,y1,x2,y2)
	local dx,dy=x2-x1,y2-y1
	local length=sqrt(dx*dx+dy*dy)
	frame.Size=UDim2.new(length/1024,0,2/576,0)
	frame.Position=UDim2.new(((x1+x2)*.5-length*.5)/1024,0,((y1+y2)*.5-1)/576,0)
	frame.Rotation=math.deg(atan2(dy,dx))
end

function HatThrow:draw(h)
	local visible=self:winding() and self:valid(h,self.selected) and h.old_health>0 and h.health>=50
	if not visible then
		if self.dial then self.dial.Visible=false end
		return
	end
	if not self.gui then
		local playerGui=self.player:FindFirstChild("PlayerGui")
		if not playerGui then return end
		local gui=Instance.new("ScreenGui")
		gui.Name="SubRosaHatThrow"
		local dial=Instance.new("Frame")
		dial.Name="Throw"
		dial.BackgroundTransparency,dial.BorderSizePixel=1,0
		dial.Size=UDim2.new(1,0,1,0)
		dial.Parent=gui
		local lines={}
		for i=1,5 do
			local f=Instance.new("Frame")
			f.Name="Line"..i
			f.BorderSizePixel=0
			f.BackgroundColor3=i<3 and Color3.new(1,1,1) or Color3.new(1,1,0)
			f.BackgroundTransparency=i==3 and .25 or .5
			f.Parent=dial
			lines[i]=f
		end
		gui.Parent=playerGui
		self.gui,self.dial,self.lines=gui,dial,lines
	end
	self.dial.Visible=true
	local x,y=point(-PI_8)
	line(self.lines[1],608,352,x,y)
	x,y=point(PI_8)
	line(self.lines[2],608,352,x,y)
	local bend=h.input_spine_bend
	local x1,y1=point(bend*15)
	line(self.lines[3],608,352,x1,y1)
	local x2,y2=point(bend*14.0625)
	line(self.lines[4],x1,y1,x2,y2)
	local x3,y3=point(bend*13.125)
	line(self.lines[5],x2,y2,x3,y3)
end

function HatThrow:stop(h)
	self:cancel(h)
	for _,record in pairs(self.tools) do HatGear.restore(record) end
	for part,original in pairs(self.visibleParts) do
		pcall(function() part.LocalTransparencyModifier=original end)
	end
	self.visibleParts={}
	if self.gui then self.gui:Destroy() end
	self.gui,self.dial,self.lines,self.tools=nil,nil,nil,{}
	if Bonds.thrower==self then Bonds.thrower=nil end
end
end

local HatWorld = {}
HatWorld.__index = HatWorld
do
local function finiteVector(v)
	return v and v.x==v.x and v.y==v.y and v.z==v.z
		and abs(v.x)<1e8 and abs(v.y)<1e8 and abs(v.z)<1e8
end

local function finiteFrame(frame)
	for _,n in ipairs({frame:components()}) do
		if n~=n or abs(n)>1e8 then return false end
	end
	return true
end

local function moved(a,b,distance)
	return (a.p-b.p).magnitude>distance
		or a.lookVector:Dot(b.lookVector)<.999999
		or a:vectorToWorldSpace(Vector3.new(0,1,0)):Dot(b:vectorToWorldSpace(Vector3.new(0,1,0)))<.999999
end

function HatWorld.new(character,torso,parts)
	local self=setmetatable({character=character,torso=torso,parts={},connections={}},HatWorld)
	for _,part in pairs(parts) do self:remember(part) end




	self:remember(torso)
	local head=character:FindFirstChild("Head")
	if head and head:IsA("BasePart") then self:remember(head) end
	self:watch(torso)
	self:findRoot()
	return self
end

function HatWorld:remember(part)
	if self.parts[part] then return end
	local saved={anchored=part.Anchored,collide=part.CanCollide}
	pcall(function() saved.touch=part.CanTouch end)
	self.parts[part]=saved
end

function HatWorld:findRoot()
	local root=self.character:FindFirstChild("HumanoidRootPart")
	if root and not root:IsA("BasePart") then root=nil end
	if root==self.root then return end
	self.root=root
	if root and root:IsA("BasePart") then
		self:remember(root)
		self.rootOffset=self.torso.CFrame:inverse()*root.CFrame
		local joint=root:FindFirstChild("RootJoint") or self.torso:FindFirstChild("RootJoint")
		self.rootJoint=joint
		if joint then
			self.rootC0,self.rootC1=joint.C0,joint.C1
			if joint.Part0==root and joint.Part1==self.torso then self.rootOffset=joint.C1*joint.C0:inverse()
			elseif joint.Part0==self.torso and joint.Part1==root then self.rootOffset=joint.C0*joint.C1:inverse() end
		end
		self:watch(root)
	end
end

function HatWorld:watch(part)
	if not part.Changed then return end
	self.connections[#self.connections+1]=part.Changed:Connect(function(property)
		if self.writing or not self.expectedTorso or not part.Parent
			or (part~=self.torso and part~=self.root) then return end
		if property=="CFrame" or property=="Position" or property=="Rotation" or property=="Orientation" then
			local target=part==self.torso and part.CFrame or part.CFrame*self.rootOffset:inverse()
			if finiteFrame(target) and moved(target,self.expectedTorso,.001) then self.pendingFrame=target end
		elseif property=="Velocity" or property=="AssemblyLinearVelocity" then
			local velocity=part.Velocity
			if finiteVector(velocity) then self.pendingVelocity=velocity end
		end
	end)
end

function HatWorld:read()
	self:findRoot()
	local target,velocity=self.pendingFrame,self.pendingVelocity
	self.pendingFrame,self.pendingVelocity=nil,nil



	if not target and self.expectedTorso then
		local dt=max(0,os.clock()-self.writtenAt)
		local advance=self.velocity*dt
		local tolerance=1.5+advance.magnitude*.25+100*dt*dt
		if (self.torso.CFrame.p-self.expectedTorso.p-advance).magnitude>tolerance then target=self.torso.CFrame
		elseif self.root and self.expectedRoot and (self.root.CFrame.p-self.expectedRoot.p-advance).magnitude>tolerance then
			target=self.root.CFrame*self.rootOffset:inverse()
		end
	end
	if target and not finiteFrame(target) then target=nil end
	return target,velocity
end

function HatWorld:beginPose(frame,velocity,angular)
	self.writing=true
	for part,saved in pairs(self.parts) do
		if part.Parent then
			if part.Anchored then part.Anchored=false end
			if part.CanCollide then part.CanCollide=false end
			if saved.touch~=nil and not part.CanTouch then part.CanTouch=true end
		end
	end
	if self.rootJoint and self.rootJoint.Parent then
		self.rootJoint.C0,self.rootJoint.C1=self.rootC0,self.rootC1
	end
	self.torso.CFrame=frame
	if self.root and self.root.Parent then
		self.root.CFrame=frame*self.rootOffset
		self.root.Velocity,self.root.RotVelocity=velocity,angular
	end
	self.torso.Velocity,self.torso.RotVelocity=velocity,angular
	self.expectedTorso,self.expectedRoot=frame,self.root and frame*self.rootOffset
	self.velocity,self.writtenAt=velocity,os.clock()
end

function HatWorld:endPose()
	self.writing=false
end

function HatWorld:stop()
	for _,connection in ipairs(self.connections) do connection:Disconnect() end
	self.connections={}
	self.writing=true
	for part,saved in pairs(self.parts) do
		if part.Parent then
			part.Anchored,part.CanCollide=saved.anchored,saved.collide
			if saved.touch~=nil then part.CanTouch=saved.touch end
		end
	end
	self.pendingFrame,self.pendingVelocity=nil,nil
end
end


