	local TORSO_UP = 0.8
	local RIG_LIFT = 0.5
	local NECK_UP = 0.6
	local HEAD_UP = 0.9
	local HEAD_PITCH_GAIN = -1

	local RIG = {
		{"Head", "Neck", BONE_HEAD, 0, 0},
		{"Left Arm", "Left Shoulder", BONE_FOREARM, 0.35, -0.8},
		{"Right Arm", "Right Shoulder", BONE_FOREARM + 3, 0.35, 0.8},
		{"Left Leg", "Left Hip", BONE_SHIN, 0.45, -0.27},
		{"Right Leg", "Right Hip", BONE_SHIN + 3, 0.45, 0.27},
	}

	local function extractNumber(v)
		if type(v) == "number" and v == v then
			return v
		elseif type(v) == "table" then
			local tv = rawget(v, "Value")
			if tv == nil then tv = rawget(v, "State") end
			if tv == nil then tv = rawget(v, "Current") end
			if type(tv) == "number" and tv == tv then
				return tv
			end
		elseif typeof(v) == "Instance" and v:IsA("ValueBase") and type(v.Value) == "number" then
			return v.Value
		end
		return nil
	end

	local SCALE_KEY_NAMES = {
		characterscale = true,
		scale = true,
		rigscale = true,
		reanimscale = true,
		reanimationscale = true,
		charactersize = true,
		size = true,
		scalefactor = true,
	}

	local function readReanimConfigScale()
		local roots = {
			Global and Global.Configuration,
			_G and _G.Configuration,
			Global and Global.Uhhhhhh,
			_G and _G.Uhhhhhh,
		}
		for _, root in ipairs(roots) do
			if type(root) == "table" then
				for k, v in pairs(root) do
					if type(k) == "string" and SCALE_KEY_NAMES[string.lower(k)] then
						local n = extractNumber(v)
						if n and n >= 0.1 and n <= 25 then
							return n
						end
					elseif type(v) == "table" then
						for sk, sv in pairs(v) do
							if type(sk) == "string" and SCALE_KEY_NAMES[string.lower(sk)] then
								local n = extractNumber(sv)
								if n and n >= 0.1 and n <= 25 then
									return n
								end
							end
						end
					end
				end
			end
		end
		return nil
	end

	local State = nil

	local function restoreOtherPlayerCollisions(S)
		if not S or not S.otherPlayerParts then
			return
		end
		for part, origCollide in pairs(S.otherPlayerParts) do
			if part and part.Parent then
				pcall(function()
					part.CanCollide = origCollide
				end)
			end
		end
		S.otherPlayerParts = {}
	end

	local function cleanupState()
		if not State then
			return
		end
		local S = State
		State = nil
		S.running = false
		restoreOtherPlayerCollisions(S)
		pcall(function()
			if S.thrower then S.thrower:stop(S.human) end
			if S.boxing then S.boxing:stop() end
			if S.peers then S.peers:stop() end
			if S.world then S.world:stop() end
			if S.human then Bonds.releaseGrab(S.human) end
		end)
		for _, conn in ipairs(S.connections or {}) do
			pcall(function()
				conn:Disconnect()
			end)
		end
		if S.character and S.character.Parent then
			pcall(function()
				for i, motor in ipairs(S.motors or {}) do
					if motor and motor.Parent then
						if S.savedC0[i] then motor.C0 = S.savedC0[i] end
						if S.savedC1[i] then motor.C1 = S.savedC1[i] end
					end
				end
				if S.setHeadHidden then
					S.setHeadHidden(0)
				end
				if S.humanoid then
					S.humanoid.PlatformStand = false
				end
				if S.animate then
					S.animate.Disabled = false
				end
			end)
		end
		if S.usedCustomCamera then
			pcall(function()
				local camera = Workspace.CurrentCamera
				if camera then
					camera.CameraType = Enum.CameraType.Custom
					if S.humanoid then
						camera.CameraSubject = S.humanoid
					end
					camera.FieldOfView = 70
				end
				UserInputService.MouseBehavior = Enum.MouseBehavior.Default
				UserInputService.MouseIconEnabled = true
			end)
		end
		SCALE = BASE_SCALE
	end

	local POSE_HOTKEYS = {
		[Enum.KeyCode.H] = 1, -- Hands Up / Surrender
		[Enum.KeyCode.G] = 2, -- Wave / Greet
		[Enum.KeyCode.J] = 3, -- Crossed Arms
		[Enum.KeyCode.K] = 4, -- Hands Behind Back / Parade Rest
