	local function startFigure(figure)
		if typeof(figure) ~= "Instance" or not figure.Parent then
			return nil
		end
		local torso = figure:FindFirstChild("Torso") or figure:FindFirstChild("UpperTorso")
		local humanoid = figure:FindFirstChildOfClass("Humanoid")
		if not torso or not torso:IsA("BasePart") then
			return nil
		end

		cleanupState()

		local player = Players.LocalPlayer or Players:GetPlayerFromCharacter(figure)
		local S = {
			character = figure,
			torso = torso,
			humanoid = humanoid,
			player = player,
			running = true,
			connections = {},
			keys = {},
			throwBend = 0,
			mouseUnlocked = false,
			firstPerson = true,
			cameraYaw = 0,
			cameraPitch = 0,
			headCFrame = nil,
			accumulated = 0,
			lastUpdateClock = os.clock(),
			nextIgnoreUpdate = 0,
			previousHumanoidHealth = humanoid and humanoid.Health or 100,
			peerParts = {},
			otherPlayerParts = {},
			motors = {},
			savedC0 = {},
			savedC1 = {},
			prevPose = {},
			currPose = {},
			blendedPose = {},
			usedCustomCamera = false,
			charScale = 1,
			armPoseMode = math.floor((Cfg.ArmPose or 0) + 0.5),
			dropkickTicks = 0,
		}

		local function listen(signal, fn)
			if signal and signal.Connect then
				local conn = signal:Connect(fn)
				S.connections[#S.connections + 1] = conn
				return conn
			end
			return nil
		end

		for _, name in ipairs({"Torso", "Head", "Left Arm", "Right Arm", "Left Leg", "Right Leg"}) do
			local part = figure:FindFirstChild(name)
			if part and part:IsA("BasePart") then
				S.peerParts[name] = part
				part.Massless = true
				part.CanCollide = false
			end
		end

		for i, entry in ipairs(RIG) do
			local motor = torso:FindFirstChild(entry[2])
			S.motors[i] = motor
			if motor and motor:IsA("Motor6D") then
				S.savedC0[i] = motor.C0
				S.savedC1[i] = motor.C1
			end
		end

		-- Detect Character Scale from UhhhhhhReanim settings, Model:GetScale(), Motor6D offsets, and limb part sizes
		S.detectCharScale = function()
			if type(Cfg.CharacterScale) == "number" and Cfg.CharacterScale > 0.05 then
				return clamp(Cfg.CharacterScale, 0.2, 15)
			end

			local candidates = {}

			local cfgScale = readReanimConfigScale()
			if cfgScale then
				candidates[#candidates + 1] = cfgScale
			end

			local okModelScale, modelScale = pcall(function()
				return figure:GetScale()
			end)
			if okModelScale and type(modelScale) == "number" and modelScale >= 0.1 and modelScale <= 25 then
				candidates[#candidates + 1] = modelScale
			end

			for _, attrName in ipairs({"CharacterScale", "Scale", "Size", "RigScale"}) do
				local attrVal = figure:GetAttribute(attrName)
				if type(attrVal) == "number" and attrVal >= 0.1 and attrVal <= 25 then
					candidates[#candidates + 1] = attrVal
				end
			end

			if humanoid then
				local hs = humanoid:FindFirstChild("BodyHeightScale") or humanoid:FindFirstChild("Scale")
				if hs and hs:IsA("ValueBase") and type(hs.Value) == "number" and hs.Value >= 0.1 and hs.Value <= 25 then
					candidates[#candidates + 1] = hs.Value
				end
			end

			if torso and torso.Parent then
				local ty = torso.Size.Y / 2
				local tx = torso.Size.X / 2
				if ty >= 0.1 and ty <= 25 then
					candidates[#candidates + 1] = ty
				end
				if tx >= 0.1 and tx <= 25 then
					candidates[#candidates + 1] = tx
				end
			end

			local neckMotor = S.motors[1]
			if neckMotor and neckMotor.Parent then
				local c1y = abs(neckMotor.C1.Position.Y) / 0.5
				if c1y >= 0.1 and c1y <= 25 and abs(c1y - 1) > 0.02 then
					candidates[#candidates + 1] = c1y
				end
			end
			if S.savedC0[1] then
				local c0y = abs(S.savedC0[1].Position.Y) / 1.0
				if c0y >= 0.1 and c0y <= 25 and abs(c0y - 1) > 0.02 then
					candidates[#candidates + 1] = c0y
				end
			end
			local hipMotor = S.motors[4]
			if hipMotor and hipMotor.Parent then
				local h1y = abs(hipMotor.C1.Position.Y) / 1.0
				if h1y >= 0.1 and h1y <= 25 and abs(h1y - 1) > 0.02 then
					candidates[#candidates + 1] = h1y
				end
			end
			if S.savedC0[4] then
				local h0y = abs(S.savedC0[4].Position.Y) / 1.0
				if h0y >= 0.1 and h0y <= 25 and abs(h0y - 1) > 0.02 then
					candidates[#candidates + 1] = h0y
				end
			end

			local maxLimbScale = 0
			for _, name in ipairs({"Torso", "Left Arm", "Right Arm", "Left Leg", "Right Leg"}) do
				local p = S.peerParts[name]
				if p and p.Parent then
					local sy = p.Size.Y / 2
					if sy > maxLimbScale and sy <= 25 then
						maxLimbScale = sy
					end
				end
			end

			local chosen = 1
			for _, c in ipairs(candidates) do
				if abs(c - 1) > 0.02 then
					chosen = c
					break
				end
			end
			if maxLimbScale > chosen then
				chosen = maxLimbScale
			end
			return clamp(chosen, 0.2, 15)
		end

		S.applyCharScale = function(newScale)
			newScale = clamp(newScale or 1, 0.2, 15)
			local oldScale = S.charScale or 1
			if abs(newScale - oldScale) < 1e-3 and abs(SCALE - BASE_SCALE * newScale) < 1e-3 then
				return
			end
			local oldWorldScale = SCALE
			local newWorldScale = BASE_SCALE * newScale
			SCALE = newWorldScale
			S.charScale = newScale

			if S.human and oldWorldScale > 0 and newWorldScale > 0 and abs(newWorldScale - oldWorldScale) > 1e-4 then
				local h = S.human
				local foot0 = h.bones[BONE_FOOT].body
				local foot1 = h.bones[BONE_FOOT + 3].body
				local groundSubRosaY = min(foot0.py, foot1.py) - 0.0625
				local groundStudsY = groundSubRosaY * oldWorldScale
				local centreStudsX = h.centre[0] * oldWorldScale
				local centreStudsZ = h.centre[2] * oldWorldScale

				local dx = centreStudsX * (1 / newWorldScale - 1 / oldWorldScale)
				local dy = groundStudsY * (1 / newWorldScale - 1 / oldWorldScale)
				local dz = centreStudsZ * (1 / newWorldScale - 1 / oldWorldScale)

				for i = 0, 15 do
					local bone = h.bones[i]
					local body = bone.body
					body.px = body.px + dx
					body.py = body.py + dy
					body.pz = body.pz + dz
					bone.position[0] = bone.position[0] + dx
					bone.position[1] = bone.position[1] + dy
					bone.position[2] = bone.position[2] + dz
					bone.previous_position[0] = bone.previous_position[0] + dx
					bone.previous_position[1] = bone.previous_position[1] + dy
					bone.previous_position[2] = bone.previous_position[2] + dz
					bone.segment0[0] = bone.segment0[0] + dx
					bone.segment0[1] = bone.segment0[1] + dy
					bone.segment0[2] = bone.segment0[2] + dz
					bone.segment1[0] = bone.segment1[0] + dx
					bone.segment1[1] = bone.segment1[1] + dy
					bone.segment1[2] = bone.segment1[2] + dz
				end
				h.centre[0] = h.centre[0] + dx
				h.centre[1] = h.centre[1] + dy
				h.centre[2] = h.centre[2] + dz
				h.walk_point[0] = h.walk_point[0] + dx
				h.walk_point[1] = h.walk_point[1] + dy
				h.walk_point[2] = h.walk_point[2] + dz
				for side = 0, 1 do
					local l = h.legs[side]
					l.planted[0] = l.planted[0] + dx
					l.planted[2] = l.planted[2] + dz
					l.landing[0] = l.landing[0] + dx
					l.landing[1] = l.landing[1] + dy
					l.landing[2] = l.landing[2] + dz
					l.ground_height = l.ground_height + dy
				end
			end
		end

		S.world = HatWorld.new(figure, torso, S.peerParts)
		S.peers = PeerRagdolls.new(figure, player, function() return S.human end, S.peerParts)
		S.boxing = HatBoxing.new(S.peers, true)
		S.thrower = HatThrow.new(player, figure)

		S.stopAnimations = function()
			S.animate = S.animate or figure:FindFirstChild("Animate")
			if S.animate and S.animate:IsA("LocalScript") and not S.animate.Disabled then
				S.animate.Disabled = true
			end
			if humanoid then
				pcall(function()
					for _, track in pairs(humanoid:GetPlayingAnimationTracks()) do
						track:Stop(0)
					end
				end)
			end
		end
		S.stopAnimations()
		if humanoid then
			pcall(function()
				listen(humanoid.AnimationPlayed, function(track)
					if S.running then
						track:Stop(0)
					end
				end)
			end)
		end

		S.updateIgnoreList = function(now)
			if player and player.Character and player.Character ~= figure then
				for _, ch in ipairs(player.Character:GetChildren()) do
					if ch:IsA("BasePart") and ch.CanCollide then
						if S.otherPlayerParts[ch] == nil then
							S.otherPlayerParts[ch] = true
						end
						ch.CanCollide = false
					end
				end
			end

			if not Cfg.PlayerCollision then
				for _, other in ipairs(Players:GetPlayers()) do
					if other ~= player and other.Character and other.Character ~= figure then
						for _, ch in ipairs(other.Character:GetChildren()) do
							if ch:IsA("BasePart") and ch.CanCollide then
								if S.otherPlayerParts[ch] == nil then
									S.otherPlayerParts[ch] = true
								end
								ch.CanCollide = false
							end
						end
					end
				end
			elseif next(S.otherPlayerParts) ~= nil then
				restoreOtherPlayerCollisions(S)
			end

			if now < S.nextIgnoreUpdate then
				return
			end
			S.nextIgnoreUpdate = now + 0.25
			local list = {figure}
			if player and player.Character and player.Character ~= figure then
				list[#list + 1] = player.Character
			end
			for _, other in ipairs(Players:GetPlayers()) do
				if other.Character and other.Character ~= figure and other.Character ~= (player and player.Character) then
					list[#list + 1] = other.Character
				end
			end
			ignoreList = list
		end

		S.boneCFrame = function(bone)
			local body = S.human.bones[bone].body
			local r = body.R
			return CFrame.new(body.px * SCALE, body.py * SCALE, body.pz * SCALE,
				r[0], r[3], r[6], r[1], r[4], r[7], r[2], r[5], r[8])
		end

		S.computePose = function(outPose)
			local cs = S.charScale or 1
			local maxUpperHalfY = (torso and torso.Size.Y or (2 * cs)) * 0.5
			for _, armName in ipairs({"Left Arm", "Right Arm"}) do
				local ap = S.peerParts[armName]
				if ap and ap.Parent and ap.Size.Y * 0.5 > maxUpperHalfY then
					maxUpperHalfY = ap.Size.Y * 0.5
				end
			end

			local torsoLift = max((TORSO_UP + RIG_LIFT) * cs, maxUpperHalfY + 0.3 * cs)
			local torsoCFrame = S.boneCFrame(BONE_PELVIS) * CFrame.new(0, torsoLift, 0)
			outPose[1] = torsoCFrame

			for i, entry in ipairs(RIG) do
				local limb = S.boneCFrame(entry[3])
				if entry[3] == BONE_HEAD then
					local neck = torsoCFrame - torsoCFrame.p + torsoCFrame:pointToWorldSpace(Vector3.new(0, NECK_UP * cs, 0))
					local look = S.human.view_pitch * HEAD_PITCH_GAIN
					limb = neck * CFrame.Angles(look, 0, 0) * CFrame.new(0, HEAD_UP * cs, 0)
				else
					local side = entry[3] == BONE_FOREARM and 0 or (entry[3] == BONE_FOREARM + 3 and 1 or nil)
					local armActivePose = side ~= nil and S.human.arm_active_pose and S.human.arm_active_pose[side] == true
					if side and ((S.human.grabs and S.human.grabs[side]) or S.boxing:posing(S.human) or S.thrower:holdsArm(side) or armActivePose) then
						limb = Bonds.grab.armFrame(S.human, side, limb, torsoCFrame)
						if armActivePose then
							-- Lift posed arm by RIG_LIFT * cs * 0.65 so hands align with the elevated R6 Torso/Head
							limb = limb + torsoCFrame:vectorToWorldSpace(Vector3.new(0, RIG_LIFT * cs * 0.65, 0))
						end
					elseif side ~= nil then
						-- Arm: blend UpperArm (BONE_SHOULDER) and Forearm (BONE_FOREARM) for natural elbow-to-shoulder line
						local shoulderCF = S.boneCFrame(BONE_SHOULDER + side * 3)
						local armPart = S.peerParts[entry[1]]
						local armHalfY = armPart and armPart.Parent and (armPart.Size.Y * 0.5) or cs
						local alongUp = max(entry[4] * cs, armHalfY - 0.65 * cs)
						local blendedRot = (shoulderCF - shoulderCF.p):Lerp(limb - limb.p, 0.72)
						local armPos = (limb * CFrame.new(0, alongUp, 0)).p
							+ torsoCFrame:vectorToWorldSpace(Vector3.new(entry[5] * cs, RIG_LIFT * cs * 0.7, 0))
						limb = blendedRot + armPos
					else
						-- Leg: Realistic Thigh + Shin + Foot IK alignment
						local legIdx = (entry[3] == BONE_SHIN) and 0 or 1
						local legPart = S.peerParts[entry[1]]
						local legHalfY = legPart and legPart.Parent and (legPart.Size.Y * 0.5) or cs
						local alongUp = max(entry[4] * cs, legHalfY - 0.55 * cs)

						if Cfg.RealisticLegs then
							local thighCF = S.boneCFrame(BONE_THIGH + legIdx * 3)
							local shinCF = limb
							local footCF = S.boneCFrame(BONE_FOOT + legIdx * 3)
							local legState = S.human.legs[legIdx]
							local stepArc = 0
							if legState and legState.state == LEG_STEPPING then
								stepArc = sin(clamp(legState.progress, 0, 1) * PI) * 0.22 * (Cfg.LegKneelLift or 1) * cs
							end
							local legRot = (thighCF - thighCF.p):Lerp(shinCF - shinCF.p, 0.58)
							local midPoint = thighCF.p:Lerp(footCF.p, 0.52)
								+ shinCF.UpVector * (alongUp * 0.65 + stepArc)
								+ torsoCFrame:vectorToWorldSpace(Vector3.new(entry[5] * cs, 0.12 * cs, 0))
							local minLegCenterY = footCF.p.Y - 0.1 * cs + legHalfY
							if midPoint.Y < minLegCenterY then
								midPoint = Vector3.new(midPoint.X, minLegCenterY, midPoint.Z)
							end
							limb = legRot + midPoint
						else
							limb = limb * CFrame.new(0, alongUp, 0)
							limb = limb + torsoCFrame:vectorToWorldSpace(Vector3.new(entry[5] * cs, 0.1 * cs, 0))
						end
					end
				end
				outPose[i + 1] = limb
			end
		end

		S.apply = function(places)
			if not torso.Parent then
				return
			end
			local rate = clamp(Cfg.TickRate or 30, 15, 60)
			local body = S.human.bones[BONE_PELVIS].body
			local linVel = Vector3.new(body.vx, body.vy, body.vz) * (SCALE * rate)
			local angVel = Vector3.new(body.wx, body.wy, body.wz) * rate
			S.world:beginPose(places[1], linVel, angVel)
			local inverse = places[1]:inverse()
			for i = 1, 5 do
				local motor = S.motors[i]
				local part = S.peerParts[RIG[i][1]]
				if motor and motor.Parent then
					motor.DesiredAngle = 0
					motor.CurrentAngle = 0
					motor.C0 = inverse * places[i + 1] * motor.C1
				end
				if part and part.Parent then
					part.CFrame = places[i + 1]
					local limb = S.human.bones[RIG[i][3]].body
					part.Velocity = Vector3.new(limb.vx, limb.vy, limb.vz) * (SCALE * rate)
				end
			end
			S.headCFrame = places[2]
			torso.CFrame = places[1]
			torso.Velocity, torso.RotVelocity = linVel, angVel
			if S.world.root and S.world.root.Parent then
				S.world.root.CFrame = places[1] * S.world.rootOffset
				S.world.root.Velocity, S.world.root.RotVelocity = linVel, angVel
			end
			S.thrower:render(S.human, places)
			S.world:endPose()
		end

		S.showBones = function(alpha)
			if Cfg.Interpolate and S.prevPose[1] and S.currPose[1] and alpha and alpha < 0.999 then
				local a = clamp(alpha, 0, 1)
				for i = 1, 6 do
					S.blendedPose[i] = S.prevPose[i]:Lerp(S.currPose[i], a)
				end
				S.apply(S.blendedPose)
			elseif S.currPose[1] then
				S.apply(S.currPose)
			end
		end

		S.setHeadHidden = function(hidden)
			for _, child in pairs(figure:GetChildren()) do
				local handle = child:FindFirstChild("Handle")
				if (child:IsA("Accoutrement") or child:IsA("Hat") or child:IsA("Accessory")) and handle and handle:IsA("BasePart") then
					handle.LocalTransparencyModifier = hidden
				end
			end
			local head = figure:FindFirstChild("Head")
			if head and head:IsA("BasePart") then
				head.LocalTransparencyModifier = hidden
				local face = head:FindFirstChild("face")
				if face and face:IsA("Decal") then
					pcall(function()
						face.LocalTransparencyModifier = hidden
					end)
				end
			end
		end

		S.updateCamera = function()
			local camera = Workspace.CurrentCamera
			if not camera or not S.headCFrame then
				return
			end
			if Cfg.SubRosaCamera then
				local cs = S.charScale or 1
				S.usedCustomCamera = true
				local cursorFree = S.mouseUnlocked or S.keys.textFocused == true
				UserInputService.MouseBehavior = cursorFree and Enum.MouseBehavior.Default or Enum.MouseBehavior.LockCenter
				UserInputService.MouseIconEnabled = cursorFree
				camera.CameraType = Enum.CameraType.Scriptable
				camera.FieldOfView = math.deg(2 * math.atan((1 - zoomEased) * 0.5625))
				if S.firstPerson then
					camera.CFrame = S.headCFrame * CFrame.new(0, 0.1 * cs, -0.3 * cs)
				else
					camera.CFrame = S.headCFrame * CFrame.new(0, 1.5 * cs, CAMERA_DISTANCE * cs)
				end
				S.setHeadHidden(S.firstPerson and 1 or 0)
				S.thrower:showTools()
			elseif S.usedCustomCamera then
				S.usedCustomCamera = false
				S.setHeadHidden(0)
				camera.CameraType = Enum.CameraType.Custom
				if humanoid then
					camera.CameraSubject = humanoid
				end
				camera.FieldOfView = 70
				UserInputService.MouseBehavior = Enum.MouseBehavior.Default
				UserInputService.MouseIconEnabled = true
			end
		end

		-- Trigger a physics-driven Sub Rosa Dropkick (X key)
		S.triggerDropkick = function()
			if not S.human or S.dropkickTicks > 0 then
				return
			end
			local h = S.human
			if h.old_health <= 0 or h.seat then
				return
			end
			S.dropkickTicks = 22
			local fx = sin(S.cameraYaw) * 0.13 * (Cfg.JumpPower or 1)
			local fz = -cos(S.cameraYaw) * 0.13 * (Cfg.JumpPower or 1)
			local fy = 0.085 * (Cfg.JumpPower or 1)
			for i = 0, 15 do
				local b = h.bones[i].body
				b.vx = b.vx + fx
				b.vy = max(b.vy, 0) + fy
				b.vz = b.vz + fz
			end
			for leg = 0, 1 do
				for _, boneIdx in ipairs({BONE_THIGH + leg * 3, BONE_SHIN + leg * 3, BONE_FOOT + leg * 3}) do
					local lb = h.bones[boneIdx].body
					lb.vx = lb.vx + fx * 0.85
					lb.vy = lb.vy + fy * 0.45
					lb.vz = lb.vz + fz * 0.85
				end
				h.legs[leg].state = LEG_LOOSE
			end
			h.movement_state = STATE_JUMP
			h.on_ground = false
		end

		-- Detect initial Character Scale and spawn the 16-bone Sub Rosa human
		S.updateIgnoreList(os.clock())
		S.charScale = S.detectCharScale()
		SCALE = BASE_SCALE * S.charScale

		local position = torso.Position
		local look = torso.CFrame.LookVector
		local cam = Workspace.CurrentCamera
		if cam then
			look = cam.CFrame.LookVector
		end
		S.cameraYaw = atan2(look.X, -look.Z)
		S.cameraPitch = clamp(asin(clamp(look.Y, -0.99, 0.99)), -1.4, 1.4)
		local groundY = position.Y - 3 * S.charScale
		rayParams.FilterDescendantsInstances = ignoreList
		local hit = Workspace:Raycast(position + Vector3.new(0, 2 * S.charScale, 0), Vector3.new(0, -900, 0), rayParams)
		if hit and (position.Y - hit.Position.Y) < 12 * max(S.charScale, 1) then
			groundY = hit.Position.Y
		end
		if humanoid then
			humanoid.PlatformStand = true
		end
		speedScale = clamp(Cfg.Speed or 0.85, SCALE_MIN, SCALE_MAX)
		jumpScale = clamp(Cfg.JumpPower or 1, SCALE_MIN, SCALE_MAX)
		gravityScale = clamp(Cfg.Gravity or 1, SCALE_MIN, SCALE_MAX)
		S.human = createHuman(position.X / SCALE, groundY / SCALE + 1.125, position.Z / SCALE, S.cameraYaw)
		if humanoid and humanoid.Health <= 0 then
			S.human.old_health = 0
		end

		-- Input listeners
		listen(UserInputService.TextBoxFocused, function()
			for key in pairs(S.keys) do S.keys[key] = nil end
			S.keys.textFocused = true
			S.throwBend = 0
			if S.human then S.human.jump_charge, S.human.input_jump_side, S.human.input_jump_forward = 0, 0, 0 end
			S.thrower:cancel(S.human)
			Bonds.releaseGrab(S.human)
			S.boxing:cancel()
		end)
		listen(UserInputService.TextBoxFocusReleased, function()
			S.keys.textFocused = nil
		end)
		pcall(function()
			listen(UserInputService.WindowFocusReleased, function()
				for key in pairs(S.keys) do S.keys[key] = nil end
				S.throwBend = 0
				if S.human then S.human.jump_charge, S.human.input_jump_side, S.human.input_jump_forward = 0, 0, 0 end
				S.thrower:cancel(S.human)
				Bonds.releaseGrab(S.human)
				S.boxing:cancel()
			end)
		end)

		listen(UserInputService.InputBegan, function(input, processed)
			if S.keys.textFocused or UserInputService:GetFocusedTextBox() then
				return
			end
			if processed and input.UserInputType ~= Enum.UserInputType.Keyboard
					and input.UserInputType ~= Enum.UserInputType.MouseButton1
					and input.UserInputType ~= Enum.UserInputType.MouseButton2 then
				return
			end
			if input.UserInputType == Enum.UserInputType.Keyboard then
				local wasDown = S.keys[input.KeyCode] == true
				S.keys[input.KeyCode] = true
				local poseId = POSE_HOTKEYS[input.KeyCode]
				if poseId and not wasDown and not processed then
					S.armPoseMode = (S.armPoseMode == poseId) and 0 or poseId
					Cfg.ArmPose = S.armPoseMode
				elseif input.KeyCode == Enum.KeyCode.N and not wasDown and not processed then
					S.armPoseMode = ((S.armPoseMode or 0) + 1) % 13
					Cfg.ArmPose = S.armPoseMode
				elseif input.KeyCode == Enum.KeyCode.M and not wasDown and not processed then
					S.armPoseMode = ((S.armPoseMode or 0) + 12) % 13
					Cfg.ArmPose = S.armPoseMode
				elseif input.KeyCode == Enum.KeyCode.Zero and not wasDown and not processed then
					S.armPoseMode = 0
					Cfg.ArmPose = 0
				elseif input.KeyCode == Enum.KeyCode.LeftAlt and not wasDown and not processed and Cfg.SubRosaCamera then
					S.mouseUnlocked = not S.mouseUnlocked
					UserInputService.MouseBehavior = S.mouseUnlocked and Enum.MouseBehavior.Default or Enum.MouseBehavior.LockCenter
					UserInputService.MouseIconEnabled = S.mouseUnlocked
				elseif input.KeyCode == Enum.KeyCode.V and not wasDown and not processed and Cfg.SubRosaCamera then
					S.firstPerson = not S.firstPerson
				elseif input.KeyCode == Enum.KeyCode.B and not wasDown and not processed then
					S.boxing.mode = not S.boxing.mode
					Cfg.BoxingMode = S.boxing.mode
					if not S.boxing.mode then
						S.boxing:cancel()
					end
				elseif input.KeyCode == Enum.KeyCode.X and not wasDown and not processed then
					S.triggerDropkick()
				elseif input.KeyCode == Enum.KeyCode.LeftBracket and not wasDown and not processed then
					Cfg.TickRate = clamp((Cfg.TickRate or 30) - 5, 15, 60)
				elseif input.KeyCode == Enum.KeyCode.RightBracket and not wasDown and not processed then
					Cfg.TickRate = clamp((Cfg.TickRate or 30) + 5, 15, 60)
				elseif input.KeyCode == Enum.KeyCode.Minus and not wasDown and not processed then
					Cfg.Speed = clamp((Cfg.Speed or 0.85) - 0.1, SCALE_MIN, SCALE_MAX)
				elseif input.KeyCode == Enum.KeyCode.Equals and not wasDown and not processed then
					Cfg.Speed = clamp((Cfg.Speed or 0.85) + 0.1, SCALE_MIN, SCALE_MAX)
				elseif input.KeyCode == Enum.KeyCode.Q and not wasDown and not S.mouseUnlocked then
					S.throwBend = 0
					S.thrower:begin(S.human, S.keys[Enum.KeyCode.LeftShift] == true)
				end
			elseif input.UserInputType == Enum.UserInputType.MouseButton1 and not S.mouseUnlocked then
				S.keys.primary = true
			elseif input.UserInputType == Enum.UserInputType.MouseButton2 and not S.mouseUnlocked then
				S.keys.aim = true
			end
		end)

		listen(UserInputService.InputEnded, function(input)
			if input.UserInputType == Enum.UserInputType.Keyboard then
				S.keys[input.KeyCode] = nil
				if input.KeyCode == Enum.KeyCode.E and S.human then
					Bonds.releaseGrab(S.human)
				end
				if input.KeyCode == Enum.KeyCode.Q and S.human then
					S.thrower:release(S.human, S.throwBend)
				end
			elseif input.UserInputType == Enum.UserInputType.MouseButton1 then
				S.keys.primary = nil
			elseif input.UserInputType == Enum.UserInputType.MouseButton2 then
				S.keys.aim = nil
			end
		end)

		listen(UserInputService.InputChanged, function(input)
			if S.mouseUnlocked or S.keys.textFocused or UserInputService:GetFocusedTextBox() then
				return
			end
			if input.UserInputType == Enum.UserInputType.MouseMovement and Cfg.SubRosaCamera then
				local delta = input.Delta
				local turn = MOUSE_SENSITIVITY * (1 - zoomEased)
				S.cameraYaw = S.cameraYaw + delta.X * turn
				S.keys.jumpX = (S.keys.jumpX or 0) + delta.X * turn * 0.5
				S.keys.jumpY = (S.keys.jumpY or 0) + delta.Y * turn * 0.5
				if S.thrower:winding() then
					S.throwBend = clamp(S.throwBend + delta.Y * MOUSE_SENSITIVITY * 0.25, -0.196349540849375, 0.196349540849375)
				else
					S.cameraPitch = clamp(S.cameraPitch - delta.Y * turn, -1.4, 1.4)
				end
				if S.cameraYaw > PI then
					S.cameraYaw = S.cameraYaw - TWO_PI
				elseif S.cameraYaw < -PI then
					S.cameraYaw = S.cameraYaw + TWO_PI
				end
			elseif input.UserInputType == Enum.UserInputType.MouseWheel and S.human and Cfg.SubRosaCamera then
				local level = S.human.zoom_level + (input.Position.Z > 0 and 1 or -1)
				S.human.zoom_level = clamp(level, 0, 2)
			end
		end)

		if humanoid then
			listen(humanoid.Died, function()
				if S.human then
					S.human.old_health = 0
					S.thrower:cancel(S.human)
					Bonds.releaseGrab(S.human)
					S.boxing:cancel()
				end
			end)
		end

		S.readInput = function(h)
			local textBoxFocused = S.keys.textFocused or (UserInputService:GetFocusedTextBox() ~= nil)
			local function isDown(keyCode)
				if textBoxFocused then
					return false
				end
				return S.keys[keyCode] == true or UserInputService:IsKeyDown(keyCode)
			end

			if not Cfg.SubRosaCamera then
				local camera = Workspace.CurrentCamera
				if camera then
					local lookVec = camera.CFrame.LookVector
					local newYaw = atan2(lookVec.X, -lookVec.Z)
					local newPitch = clamp(asin(clamp(lookVec.Y, -0.99, 0.99)), -1.4, 1.4)
					local dYaw = angleDifference(newYaw, S.cameraYaw)
					local dPitch = newPitch - S.cameraPitch
					S.keys.jumpX = (S.keys.jumpX or 0) + dYaw * 0.5
					S.keys.jumpY = (S.keys.jumpY or 0) - dPitch * 0.5
					S.cameraYaw = newYaw
					S.cameraPitch = newPitch
				end
			end

			local forward, strafe = 0, 0
			if isDown(Enum.KeyCode.W) or isDown(Enum.KeyCode.Up) then
				forward = forward + 1
			end
			if isDown(Enum.KeyCode.S) or isDown(Enum.KeyCode.Down) then
				forward = forward - 1
			end
			if isDown(Enum.KeyCode.D) or isDown(Enum.KeyCode.Right) then
				strafe = strafe + 1
			end
			if isDown(Enum.KeyCode.A) or isDown(Enum.KeyCode.Left) then
				strafe = strafe - 1
			end

			if forward == 0 and strafe == 0 and humanoid and humanoid.MoveDirection.Magnitude > 0.05 then
				local md = humanoid.MoveDirection
				local fx, fz = sin(S.cameraYaw), -cos(S.cameraYaw)
				local rx, rz = cos(S.cameraYaw), sin(S.cameraYaw)
				forward = clamp(md.X * fx + md.Z * fz, -1, 1)
				strafe = clamp(md.X * rx + md.Z * rz, -1, 1)
			end

			h.input_forward = forward
			h.input_strafe = strafe
			h.input_yaw = S.cameraYaw
			h.input_pitch = S.cameraPitch * PITCH_SIGN
			h.input_spine_bend = S.thrower:winding() and S.throwBend or 0
			h.input_jump_forward = (h.input_jump_forward + (S.keys.jumpX or 0)) * 0.9375
			h.input_jump_side = (h.input_jump_side + (S.keys.jumpY or 0)) * 0.9375
			S.keys.jumpX, S.keys.jumpY = nil, nil
			h.arm_pose_mode = S.armPoseMode or 0

			if S.dropkickTicks and S.dropkickTicks > 0 then
				S.dropkickTicks = S.dropkickTicks - 1
				local fx = sin(S.cameraYaw) * 0.018
				local fz = -cos(S.cameraYaw) * 0.018
				for leg = 0, 1 do
					local fb = h.bones[BONE_FOOT + leg * 3].body
					fb.vx = fb.vx + fx
					fb.vy = fb.vy + 0.006
					fb.vz = fb.vz + fz
				end
			end

			local flags = 0
			local primaryDown = S.keys.primary or (not textBoxFocused and UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1))
			local aimDown = S.keys.aim or (not textBoxFocused and UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2))
			local shiftDown = isDown(Enum.KeyCode.LeftShift)
			if primaryDown then
				flags = flags + INPUT_PRIMARY
			end
			if aimDown then
				flags = flags + INPUT_AIM
			end
			if isDown(Enum.KeyCode.Space) or (humanoid and humanoid.Jump) then
				flags = flags + INPUT_JUMP
			end
			if isDown(Enum.KeyCode.LeftControl) or isDown(Enum.KeyCode.RightControl) or isDown(Enum.KeyCode.C) then
				flags = flags + INPUT_CROUCH
			end
			if shiftDown then
				flags = flags + 0x10
			end
			if S.thrower:winding() then
				flags = flags + INPUT_THROW
			end
			h.input_flags = flags

			if not Cfg.SubRosaCamera then
				if Cfg.SprintWithShift then
					h.zoom_level = shiftDown and 0 or 1
				else
					h.zoom_level = 0
				end
			end

			local grabDown = isDown(Enum.KeyCode.E)
			if S.wasGrabbing and not grabDown then
				Bonds.releaseGrab(h)
			end
			S.wasGrabbing = grabDown
			h.input_grab = grabDown
			h.input_ragdoll = Cfg.Limp == true or isDown(Enum.KeyCode.Z)
		end

		S.adoptCharacterChanges = function()
			if S.world.expectedTorso and torso.Parent then
				local dist = (torso.CFrame.p - S.world.expectedTorso.p).Magnitude
				if dist > 15 * max(S.charScale or 1, 1) then
					local transform = torso.CFrame * S.world.expectedTorso:inverse()
					Bonds.releaseGrab(S.human)
					S.thrower:cancel(S.human)
					S.boxing:cancel()
					S.keys.jumpX, S.keys.jumpY, S.keys[Enum.KeyCode.E] = nil, nil, nil
					S.throwBend = 0
					Bonds.teleportHuman(S.human, transform)
					local direction = transform:vectorToWorldSpace(Vector3.new(sin(S.cameraYaw), 0, -cos(S.cameraYaw)))
					S.cameraYaw = atan2(direction.X, -direction.Z)
					S.human.input_yaw = S.cameraYaw
					S.peers.records, S.peers.incoming, S.peers.nextDiscovery = {}, {}, 0
					S.computePose(S.currPose)
					for i = 1, 6 do
						S.prevPose[i] = S.currPose[i]
					end
				end
			end
			if humanoid then
				if humanoid.Health <= 0 then
					S.human.old_health, S.human.health = 0, 0
				else
					local scale = 100 / max(humanoid.MaxHealth or 100, 1)
					S.human.health = clamp(S.human.health + (humanoid.Health - S.previousHumanoidHealth) * scale, 0, 100)
					S.human.health = min(S.human.health, humanoid.Health * scale)
					if S.human.health <= 0 then
						S.human.old_health = 0
					end
				end
				S.previousHumanoidHealth = humanoid.Health
			end
		end

		-- Perform initial physics tick and pose sync immediately
		physicsTick(S.human)
		S.computePose(S.currPose)
		for i = 1, 6 do
			S.prevPose[i] = S.currPose[i]
		end
		S.showBones(1)
		return S
	end

	m.Init = function(figure)
		if typeof(figure) ~= "Instance" then
			return
		end
		pcall(function()
			if LimbReanimator and LimbReanimator.SetRootPartMode then
				LimbReanimator.SetRootPartMode(3)
			end
		end)
		State = startFigure(figure)
	end

	m.Update = function(a, b)
		local figure = (typeof(b) == "Instance" and b) or (typeof(a) == "Instance" and a) or (State and State.character)
		if not State or (typeof(figure) == "Instance" and State.character ~= figure) then
			if typeof(figure) == "Instance" and figure.Parent then
				State = startFigure(figure)
			end
			if not State then
				return
			end
		end

		local S = State
		if not S.character or not S.character.Parent or not S.torso or not S.torso.Parent then
			cleanupState()
			return
		end

		if S.humanoid and S.humanoid.PlatformStand ~= true then
			S.humanoid.PlatformStand = true
		end
		S.stopAnimations()
		pollWidgets()
		S.applyCharScale(S.detectCharScale())

		local tickRate = clamp(Cfg.TickRate or 30, 15, 60)
		local stepInterval = 1 / tickRate

		speedScale = clamp(Cfg.Speed or 0.85, SCALE_MIN, SCALE_MAX)
		jumpScale = clamp(Cfg.JumpPower or 1, SCALE_MIN, SCALE_MAX)
		gravityScale = clamp(Cfg.Gravity or 1, SCALE_MIN, SCALE_MAX)
		if S.boxing then
			S.boxing.mode = Cfg.BoxingMode == true
		end

		local now = os.clock()
		local realDt = clamp(now - (S.lastUpdateClock or (now - stepInterval)), 0, 0.1)
		S.lastUpdateClock = now

		S.updateIgnoreList(now)
		S.adoptCharacterChanges()

		S.accumulated = min(S.accumulated + realDt, stepInterval * 3)
		while S.accumulated >= stepInterval do
			S.accumulated = S.accumulated - stepInterval
			for i = 1, 6 do
				S.prevPose[i] = S.currPose[i]
			end
			S.readInput(S.human)
			physicsTick(S.human)
			zoomEased = zoomEased + ((ZOOM_TARGET[S.human.zoom_level] or 0) - zoomEased) * ZOOM_EASE
			S.computePose(S.currPose)
		end

		local alpha = clamp(S.accumulated / stepInterval, 0, 1)
		S.showBones(alpha)
		S.thrower:draw(S.human)
		S.updateCamera()
	end

	m.Destroy = function(figure)
		cleanupState()
	end

	return m
end)

return Modules

end)
if not ok then
    (warn or print)("[KernelPacker] failed to load subrosaragdoll.lua: " .. tostring(result))
elseif type(result) == "table" and result ~= modules then
    for _, fn in ipairs(result) do table.insert(modules, fn) end
end
end

return modules
